          <div id="settings-sec-channel_routing" style="${secContent('channel_routing')}">
            <div id="channelRoutingPanelBody"><div style="text-align:center;padding:24px;color:var(--text2);font-size:13px;">${loadingEyeBlock()}</div></div>
          </div>
