function ensureFreeObserversCached() {
  return apiFetch('/api/observer/peers/free')
    .then(d => { window._freeObserversCache = (d && d.peers) || []; })
    .catch(() => { window._freeObserversCache = []; });
}
window.ensureFreeObserversCached = ensureFreeObserversCached;

// LLM form builder.
// plan_tier options for the LLM forms. The tier set is a closed enum on
// the daemon (inference.PlanTier); the server rejects anything else with
// an actionable 400, so a fixed list is enough for the UI.
const LLM_PLAN_TIERS = ['pro', 'max_5x', 'max_20x', 'api'];
function planTierOptions(selected) {
  const opts = [`<option value="" ${!selected ? 'selected' : ''}>${escHtml(t('llm_plan_tier_unset')||'(unset — no tier cap)')}</option>`];
  for (const v of LLM_PLAN_TIERS) opts.push(`<option value="${v}" ${selected === v ? 'selected' : ''}>${v}</option>`);
  return opts.join('');
}
// One-line “effective inflight cap + source” display, present only when
// the daemon returned the derived fields (effective_max_inflight /
// inflight_source). Older daemons simply don't show the line.
function llmEffectiveCapLine(l) {
  if (!l || l.effective_max_inflight == null) return '';
  const src = l.inflight_source ? ` (${l.inflight_source})` : '';
  return `<div style="font-size:11px;color:var(--text2);margin-top:2px;">${escHtml((t('llm_effective_cap')||'Effective inflight cap')+': '+l.effective_max_inflight+src)}</div>`;
}
// Dollar budget group for the LLM edit form. Field names follow the REST
// "budget" object (ceiling_usd, hours, weekday, time, zone, allocation_pct,
// peer_window). The weekday enum is lowercase English on the daemon, so the
// option text is the value itself, like the plan tier select.
const LLM_BUDGET_WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
function budgetWeekdayOptions(selected) {
  const sel = String(selected || '').toLowerCase();
  const opts = [`<option value="" ${!sel ? 'selected' : ''}>${escHtml(t('llm_budget_weekday_unset')||'(none — rolling window)')}</option>`];
  for (const v of LLM_BUDGET_WEEKDAYS) opts.push(`<option value="${v}" ${sel === v ? 'selected' : ''}>${v}</option>`);
  return opts.join('');
}
function buildLLMBudgetGroup(l) {
  const b = (l && l.budget) || {};
  const lbl = 'font-size:11px;color:var(--text2);margin-top:6px;';
  const hint = 'font-size:11px;color:var(--text2);margin-top:2px;';
  return `
    <div style="margin-top:12px;padding-top:8px;border-top:1px solid var(--border);">
    <div style="font-size:12px;font-weight:600;">${escHtml(t('llm_budget_group')||'Budget')}</div>
    <div style="${hint}">${escHtml(t('llm_budget_hint')||'A dollar ceiling for one window. Pick either a rolling window in hours or a weekly window; an empty ceiling removes the budget.')}</div>
    <label style="${lbl}">${escHtml(t('llm_field_budget_ceiling')||'Budget ceiling (USD per window; empty = no budget)')}</label>
    <input id="fe_llm_budget_ceiling" type="number" min="0" step="any" class="form-input" value="${b.ceiling_usd ? escHtml(String(b.ceiling_usd)) : ''}" />
    <label style="${lbl}">${escHtml(t('llm_field_budget_hours')||'Rolling window (hours, 1–720)')}</label>
    <input id="fe_llm_budget_hours" type="number" min="1" max="720" step="1" class="form-input" value="${b.hours ? escHtml(String(b.hours)) : ''}" />
    <label style="${lbl}">${escHtml(t('llm_field_budget_weekday')||'Weekly window starts on')}</label>
    <select id="fe_llm_budget_weekday" class="form-select">${budgetWeekdayOptions(b.weekday)}</select>
    <label style="${lbl}">${escHtml(t('llm_field_budget_time')||'Weekly window time (24h HH:MM, default 00:00)')}</label>
    <input id="fe_llm_budget_time" class="form-input" placeholder="00:00" value="${escHtml(b.time||'')}" />
    <label style="${lbl}">${escHtml(t('llm_field_budget_zone')||'Weekly window time zone (IANA name, default UTC)')}</label>
    <input id="fe_llm_budget_zone" class="form-input" placeholder="UTC" value="${escHtml(b.zone||'')}" />
    <label style="${lbl}display:flex;align-items:center;gap:6px;">
      <input id="fe_llm_budget_allocation" type="checkbox" ${b.allocation_pct ? 'checked' : ''} />
      <span>${escHtml(t('llm_field_budget_allocation')||'Show share of plan allocation (an estimate)')}</span>
    </label>
    <label style="${lbl}">${escHtml(t('llm_field_budget_peers')||'Peer window (comma-separated peer names)')}</label>
    <input id="fe_llm_budget_peers" class="form-input" value="${escHtml((b.peer_window||[]).join(', '))}" />
    <div style="${hint}">${escHtml(t('llm_budget_peers_hint')||'Federation peer spend is off for every peer unless the peer is listed here.')}</div>
    <label style="${lbl}">${escHtml(t('llm_billing_group_label')||'Billing group')}</label>
    <input id="fe_llm_billing_group" class="form-input" value="${escHtml(l.billing_group||'')}" title="Free-text label grouping LLM entries that share a billing account / plan" />
    </div>`;
}
// Reads the budget group back into the REST "budget" value. An empty
// ceiling means "no budget" and yields null, which the daemon treats as
// clearing the stored budget. Window fields are sent as typed; the daemon
// validates them and returns an actionable error.
function collectLLMBudget() {
  const val = id => ((document.getElementById(id)||{}).value || '').trim();
  const ceilingRaw = val('fe_llm_budget_ceiling');
  if (ceilingRaw === '') return null;
  const budget = { ceiling_usd: parseFloat(ceilingRaw) || 0 };
  const hours = parseInt(val('fe_llm_budget_hours') || '0', 10) || 0;
  if (hours) budget.hours = hours;
  const weekday = val('fe_llm_budget_weekday');
  if (weekday) budget.weekday = weekday;
  const time = val('fe_llm_budget_time');
  if (time) budget.time = time;
  const zone = val('fe_llm_budget_zone');
  if (zone) budget.zone = zone;
  if ((document.getElementById('fe_llm_budget_allocation')||{}).checked) budget.allocation_pct = true;
  const peers = val('fe_llm_budget_peers').split(',').map(s => s.trim()).filter(Boolean);
  if (peers.length) budget.peer_window = peers;
  return budget;
}
function buildLLMForm(l) {
  const nodes = (window._computeNodesCache||[]);
  const nodeOpts = nodes.map(n =>
    `<option value="${escHtml(n.name)}" ${(l.compute_nodes||[]).includes(n.name) ? 'selected' : ''}>${escHtml(n.name)} (${escHtml(n.kind||'?')})</option>`
  ).join('');
  return `
    <label style="font-size:11px;color:var(--text2);">${escHtml(t('llm_field_kind')||'Kind')}</label>
    <input id="fe_llm_kind" class="form-input" value="${escHtml(l.kind||'')}" readonly title="Kind is immutable; delete + recreate to change" />
    <label style="font-size:11px;color:var(--text2);margin-top:6px;">${escHtml(t('llm_field_model')||'Model')}</label>
    <input id="fe_llm_model" class="form-input" value="${escHtml(l.model||'')}" />
    <label style="font-size:11px;color:var(--text2);margin-top:6px;">${escHtml(t('llm_field_compute_nodes')||'ComputeNodes (multi-select; ordered failover)')}</label>
    <select id="fe_llm_compute_nodes" class="form-select" multiple size="4" style="min-height:80px;">${nodeOpts}</select>
    <label style="font-size:11px;color:var(--text2);margin-top:6px;">${escHtml(t('llm_field_api_key_ref')||'API key reference')}</label>
    <input id="fe_llm_api_key_ref" class="form-input" value="${escHtml(l.api_key_ref||'')}" placeholder="${l.api_key_ref_present ? escHtml((t('llm_field_api_key_ref_unchanged')||'(unchanged — key set{prefix})').replace('{prefix}', l.api_key_ref_prefix ? ' — '+l.api_key_ref_prefix+'…' : '')) : '$\{secret:anthropic-key\}'}" />
    ${l.api_key_ref_present ? `<div style="font-size:11px;color:var(--text2);">${escHtml(t('llm_field_api_key_ref_hint')||'Leave blank to keep the current key. Type a new value to replace it.')}</div>` : ''}
    <label style="font-size:11px;color:var(--text2);margin-top:6px;">${escHtml(t('llm_field_timeout')||'Timeout seconds (0 = adapter default)')}</label>
    <input id="fe_llm_timeout" type="number" min="0" class="form-input" value="${l.timeout_seconds||''}" />
    <label style="font-size:11px;color:var(--text2);margin-top:6px;">${escHtml(t('llm_field_max_inflight')||'Max in-flight autonomous sessions (0 = unlimited)')}</label>
    <input id="fe_llm_max_inflight" type="number" min="0" class="form-input" value="${l.max_inflight||''}" />
    <label style="font-size:11px;color:var(--text2);margin-top:6px;">${escHtml(t('llm_field_plan_tier')||'Plan tier (empty = unset)')}</label>
    <select id="fe_llm_plan_tier" class="form-select">${planTierOptions(l.plan_tier)}</select>
    <div style="font-size:11px;color:var(--text2);margin-top:2px;">${escHtml(t('llm_plan_tier_hint')||"The daemon's autonomous.plan_tier_max_inflight table caps inflight per tier; an explicit max_inflight > 0 wins; otherwise no tier cap (unlimited).")}</div>
    ${llmEffectiveCapLine(l)}
    ${buildLLMBudgetGroup(l)}
    <label style="font-size:11px;color:var(--text2);margin-top:6px;">${escHtml(t('llm_field_roles')||'Workload roles (comma-separated; empty = none)')}</label>
    <input id="fe_llm_roles" class="form-input" placeholder="planning, review" value="${escHtml((l.roles||[]).join(', '))}" />
    <div style="font-size:11px;color:var(--text2);margin-top:2px;">${escHtml(t('llm_roles_hint')||'Roles this entry serves. If several enabled entries claim one role, the first by name wins and a warning is shown.')}</div>
    ${(l.role_warnings||[]).map(w => `<div class="llm-role-warning" style="font-size:11px;color:var(--warning,#d97706);margin-top:2px;">${escHtml(w)}</div>`).join('')}
    <label style="font-size:11px;color:var(--text2);margin-top:6px;">${escHtml(t('llm_field_tags')||'Tags')}</label>
    ${renderBadgeInput('fe_llm_tags', (l.tags||[]).join(', '), { freeform: true, placeholder: 'fast, coding…' })}
  `;
}

function collectLLMForm(originalRecord) {
  const out = JSON.parse(JSON.stringify(originalRecord || {}));
  out.model = (document.getElementById('fe_llm_model')||{}).value || '';
  const sel = document.getElementById('fe_llm_compute_nodes');
  out.compute_nodes = sel ? Array.from(sel.selectedOptions).map(o => o.value).filter(Boolean) : [];
  const feApiKey = (document.getElementById('fe_llm_api_key_ref')||{}).value || '';
  // #179 — blank means "unchanged" when the server already has a literal
  // key (it never sends the real value back); omit the field so the
  // server-side merge-on-update preserves it instead of clearing it.
  if (feApiKey) out.api_key_ref = feApiKey;
  else if (originalRecord && originalRecord.api_key_ref_present) delete out.api_key_ref;
  else out.api_key_ref = '';
  out.timeout_seconds = parseInt((document.getElementById('fe_llm_timeout')||{}).value || '0', 10) || 0;
  out.max_inflight = parseInt((document.getElementById('fe_llm_max_inflight')||{}).value || '0', 10) || 0;
  out.plan_tier = (document.getElementById('fe_llm_plan_tier')||{}).value || '';
  out.budget = collectLLMBudget();
  // Roles: always sent, so clearing the box clears the stored list (an
  // omitted field would keep it).
  out.roles = String((document.getElementById('fe_llm_roles')||{}).value || '').split(',').map(r => r.trim()).filter(Boolean);
  // Billing group — free-text label on the LLM record (l.billing_group); an
  // empty value clears it (the daemon trims on save and omits it when blank).
  const billingGroup = String((document.getElementById('fe_llm_billing_group')||{}).value || '').trim();
  if (billingGroup) out.billing_group = billingGroup; else delete out.billing_group;
  out.tags = getBadgeInputValue('fe_llm_tags').split(',').map(s => s.trim()).filter(Boolean);
  return out;
}

// Back-compat alias — older call sites still reference openYAMLEditPopup.
window.openYAMLEditPopup = window.openFormEditPopup;

// (legacy YAML-only edit popup removed alpha.23 — replaced by the
// form-first variant above. Keeping the dead branch below for one
// release in case rollback is needed; will delete in alpha.24.)
window._legacyOpenYAMLEditPopup = function(kindCfg, name) {
  const existing = document.getElementById('yamlEditPopup');
  if (existing) existing.remove();
  apiFetch(kindCfg.getURL).then(record => {
    const popup = document.createElement('div');
    popup.id = 'yamlEditPopup';
    popup.className = 'modal-overlay';
    popup.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:1000;display:flex;align-items:center;justify-content:center;padding:16px;';
    const initialYAML = JSON.stringify(record, null, 2);
    popup.innerHTML = `
      <div style="background:var(--bg);border:1px solid var(--border);border-radius:8px;max-width:600px;width:100%;max-height:90vh;display:flex;flex-direction:column;overflow:hidden;">
        <div style="padding:12px 16px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;">
          <strong style="font-size:14px;">Edit ${escHtml(kindCfg.title)}: ${escHtml(name)}</strong>
          <button class="btn-icon" onclick="document.getElementById('yamlEditPopup').remove()" style="font-size:18px;">&times;</button>
        </div>
        <div style="padding:8px 16px;border-bottom:1px solid var(--border);font-size:11px;color:var(--text2);">
          Edit the JSON below and click <strong>Test</strong> to verify the change works <em>before</em> saving. <strong>Save</strong> commits via PUT.
        </div>
        <div style="padding:12px 16px;flex:1;overflow:auto;">
          <textarea id="yamlEditTextarea" style="width:100%;min-height:320px;font-family:var(--mono,monospace);font-size:11px;background:var(--bg2);color:var(--text);border:1px solid var(--border);border-radius:4px;padding:8px;" spellcheck="false">${escHtml(initialYAML)}</textarea>
          <div id="yamlEditStatus" style="font-size:11px;color:var(--text2);margin-top:8px;min-height:18px;"></div>
        </div>
        <div style="padding:12px 16px;border-top:1px solid var(--border);display:flex;gap:8px;justify-content:flex-end;">
          <button class="btn-secondary" onclick="document.getElementById('yamlEditPopup').remove()">Cancel</button>
          <button class="btn-secondary" id="yamlEditTestBtn">🧪 Test (unsaved values)</button>
          <button class="btn-primary" id="yamlEditSaveBtn">💾 Save</button>
        </div>
      </div>`;
    document.body.appendChild(popup);
    const ta = document.getElementById('yamlEditTextarea');
    const status = document.getElementById('yamlEditStatus');
    const setStatus = (msg, color) => { status.textContent = msg; status.style.color = color || 'var(--text2)'; };
    const parseEdit = () => {
      try { return JSON.parse(ta.value); }
      catch (e) { setStatus('JSON parse error: ' + e.message, 'var(--error)'); return null; }
    };
    document.getElementById('yamlEditTestBtn').onclick = () => {
      const obj = parseEdit();
      if (!obj) return;
      setStatus('Testing unsaved values…', 'var(--text2)');
      // Test endpoint targets the saved record. For test-before-save
      // we'd ideally PUT to a transient validation URL; absent that,
      // we PUT first then test so the test exercises the real spec.
      // (Operator can revert by editing back if test fails.)
      apiFetch(kindCfg.getURL, {
        method: kindCfg.saveMethod || 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(obj),
      }).then(() => {
        // GATE alpha.36 (operator 2026-05-10): same fix as the other
        // popup — GET/HEAD requests must not carry a body.
        const method = kindCfg.testMethod || 'POST';
        const opts = { method, headers: { 'Content-Type': 'application/json' } };
        if (method !== 'GET' && method !== 'HEAD') {
          opts.body = JSON.stringify(kindCfg.testBody || {});
        }
        return apiFetch(kindCfg.testURL, opts);
      }).then(d => {
        const summary = (d && (d.text || d.status || JSON.stringify(d).slice(0, 200))) || 'ok';
        setStatus('✓ Test passed: ' + String(summary).slice(0, 200), 'var(--success,#10b981)');
      }).catch(e => setStatus('✕ Test failed: ' + String(e.message || e).slice(0, 240), 'var(--error)'));
    };
    document.getElementById('yamlEditSaveBtn').onclick = () => {
      const obj = parseEdit();
      if (!obj) return;
      setStatus('Saving…', 'var(--text2)');
      apiFetch(kindCfg.getURL, {
        method: kindCfg.saveMethod || 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(obj),
      }).then(() => {
        showToast(`✓ ${kindCfg.title} saved: ${name}`, 'success', 2500);
        document.getElementById('yamlEditPopup').remove();
        if (typeof kindCfg.onAfterSave === 'function') kindCfg.onAfterSave();
      }).catch(e => setStatus('✕ Save failed: ' + String(e.message || e), 'var(--error)'));
    };
  }).catch(e => showError('Load failed', String(e.message || e)));
};

