// BL381 — per-story LLM override modal. Mirrors openPRDEditTaskModal's LLM
// section; calls set_story_llm. Available in needs_review + revisions_asked
// + cancelled (see renderStory's editable gate).
function openPRDSetStoryLLMModal(prdID, storyID, currentBackend, currentEffort, currentModel, currentVerif) {
  ensureLLMModelLists().then(() => {
    _prdMountModal(`
    <div class="response-modal-header">
      <strong>${t('prd_set_story_llm_title')||'Story LLM override'}</strong>
      <button class="btn-icon" onclick="_prdCloseModal()" title="${t('btn_close')||'Close'}">&#10005;</button>
    </div>
    <form id="prdModalForm" class="response-modal-body" style="display:flex;flex-direction:column;gap:8px;">
      <label style="font-size:11px;color:var(--text2);">Story ${escHtml(storyID)}</label>
      <div style="font-size:10px;color:var(--text2);">${t('prd_story_llm_hint')||'Per-story LLM override — empty inherits from the Automaton then the global config. All tasks in this story inherit this unless they have their own override.'}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;">
        <div><label style="font-size:11px;color:var(--text2);">${t('prd_new_backend_label')||'Backend'}</label>${renderBackendSelect('prdStoryLLMBackend', currentBackend || '', `refreshLLMModelField('prdStoryLLMModelWrap','prdStoryLLMModelInner','prdStoryLLMBackend','')`)}</div>
        <div><label style="font-size:11px;color:var(--text2);">${t('prd_new_effort_label')||'Effort'}</label>${renderEffortSelect('prdStoryLLMEffort', currentEffort || '', '')}</div>
        <div id="prdStoryLLMModelWrap" style="display:none;"><label style="font-size:11px;color:var(--text2);">${t('prd_new_model_label')||'Model (optional)'}</label><div id="prdStoryLLMModelInner"></div></div>
      </div>
      ${_prdVerifLLMSectionHTML('prdStoryVerif', currentVerif, 'prd_verif_llm_story_hint', 'Which LLM judges this story\'s tasks — empty inherits the Automaton, then the global verification setting. Tasks with their own verification LLM keep it.')}
      <div style="display:flex;gap:6px;justify-content:flex-end;">
        <button type="button" class="btn-secondary" onclick="_prdCloseModal()">${t('btn_cancel')||'Cancel'}</button>
        <button type="submit" class="btn-secondary" style="background:var(--accent2);color:#fff;">${t('btn_save')||'Save'}</button>
      </div>
    </form>
  `, () => {
    const backend = document.getElementById('prdStoryLLMBackend').value;
    const effort = document.getElementById('prdStoryLLMEffort').value;
    const modelEl = document.getElementById('prdStoryLLMModelInner')?.querySelector('input,select');
    const model = modelEl ? modelEl.value.trim() : '';
    const verif = _prdReadVerifLLM('prdStoryVerif');
    const calls = [];
    if (backend !== (currentBackend || '') || effort !== (currentEffort || '') || model !== (currentModel || '')) {
      calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_story_llm', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ story_id: storyID, backend, effort, model, actor: 'operator' }),
      }));
    }
    if (_prdVerifLLMChanged(verif, currentVerif)) {
      calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_story_verification_llm', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(Object.assign({ story_id: storyID, actor: 'operator' }, verif)),
      }));
    }
    if (calls.length === 0) { _prdCloseModal(); return; }
    Promise.all(calls)
      .then(() => { showToast('Story LLM saved', 'success', 1500); _prdCloseModal(); _refreshAutomataOrPRD(); })
      .catch(err => showToast('Save failed: ' + String(err), 'error', 3000));
  });
  refreshLLMModelField('prdStoryLLMModelWrap', 'prdStoryLLMModelInner', 'prdStoryLLMBackend', currentModel || '');
  refreshLLMModelField('prdStoryVerifModelWrap', 'prdStoryVerifModelInner', 'prdStoryVerifBackend', (currentVerif || {}).verification_model || '');
  });
}
window.openPRDSetStoryLLMModal = openPRDSetStoryLLMModal;

function openPRDSetLLMModal(prdID, current) {
  // v5.26.8 — same dynamic model dropdown pattern as the New PRD and
  // Edit Task modals.
  // v8.20.0 — split into planning backend (decomposition_profile, headless
  // only) and execution backend (backend, any session agent).
  ensureLLMModelLists().then(() => {
    _prdMountModal(`
    <div class="response-modal-header">
      <strong>${t('prd_set_llm_title')||'Automaton LLM settings'}</strong>
      <button class="btn-icon" onclick="_prdCloseModal()" title="${t('btn_close')||'Close'}">&#10005;</button>
    </div>
    <form id="prdModalForm" class="response-modal-body" style="display:flex;flex-direction:column;gap:10px;">
      <div style="font-size:11px;color:var(--text2);">${t('prd_set_llm_hint')||'Execution backend runs task sessions (opencode, claude-code, goose, etc.). Planning backend runs decompose — opencode/claude-code get full codebase tool access; ollama/openwebui run headless. Defaults to global autonomous.planning_backend when left empty.'}</div>
      <div>
        <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:4px;">Execution backend (task sessions)</div>
        <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;">
          <div><label style="font-size:11px;color:var(--text2);">${t('prd_new_backend_label')||'Backend'}</label>${renderBackendSelect('prdSetBackend', current.backend || '', `refreshLLMModelField('prdSetModelWrap','prdSetModelInner','prdSetBackend','')`)}</div>
          <div><label style="font-size:11px;color:var(--text2);">${t('prd_new_effort_label')||'Effort'}</label>${renderEffortSelect('prdSetEffort', current.effort || '', '')}</div>
          <div id="prdSetModelWrap" style="display:none;"><label style="font-size:11px;color:var(--text2);">${t('prd_new_model_label')||'Model (optional)'}</label><div id="prdSetModelInner"></div></div>
        </div>
      </div>
      <div>
        <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:4px;">Planning backend (decompose)</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;">
          <div><label style="font-size:11px;color:var(--text2);">Planning LLM (any configured backend)</label>${renderBackendSelect('prdSetDecompositionProfile', current.decomposition_profile || '', `refreshLLMModelField('prdSetDecompModelWrap','prdSetDecompModelInner','prdSetDecompositionProfile','')`, true)}</div>
          <div id="prdSetDecompModelWrap" style="display:none;"><label style="font-size:11px;color:var(--text2);">Planning model (optional)</label><div id="prdSetDecompModelInner"></div></div>
        </div>
      </div>
      ${_prdVerifLLMSectionHTML('prdSetVerif', current, 'prd_verif_llm_automaton_hint', 'Which LLM judges this Automaton\'s tasks — empty inherits the global verification setting. Story and task verification LLMs take precedence.')}
      <div style="display:flex;gap:6px;justify-content:flex-end;">
        <button type="button" class="btn-secondary" onclick="_prdCloseModal()">${t('btn_cancel')||'Cancel'}</button>
        <button type="submit" class="btn-secondary" style="background:var(--accent2);color:#fff;">${t('btn_save')||'Save'}</button>
      </div>
    </form>
  `, () => {
    const modelEl = document.getElementById('prdSetModelInner')?.querySelector('input,select');
    const decompModelEl = document.getElementById('prdSetDecompModelInner')?.querySelector('input,select');
    const body = {
      backend: document.getElementById('prdSetBackend').value,
      effort: document.getElementById('prdSetEffort').value,
      model: modelEl ? modelEl.value.trim() : '',
      decomposition_profile: document.getElementById('prdSetDecompositionProfile').value,
      decomposition_model: decompModelEl ? decompModelEl.value.trim() : '',
      actor: 'operator',
    };
    const calls = [apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_llm', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    })];
    const verif = _prdReadVerifLLM('prdSetVerif');
    if (_prdVerifLLMChanged(verif, current)) {
      calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_verification_llm', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(Object.assign({ actor: 'operator' }, verif)),
      }));
    }
    Promise.all(calls).then(() => { showToast('PRD LLM updated', 'success', 1500); _prdCloseModal(); _refreshAutomataOrPRD(); })
      .catch(err => showToast('Save failed: ' + String(err), 'error', 3000));
  });
  // Populate model dropdowns for the current backends now that the modal is mounted.
  refreshLLMModelField('prdSetModelWrap', 'prdSetModelInner', 'prdSetBackend', current.model || '');
  refreshLLMModelField('prdSetDecompModelWrap', 'prdSetDecompModelInner', 'prdSetDecompositionProfile', current.decomposition_model || '');
  refreshLLMModelField('prdSetVerifModelWrap', 'prdSetVerifModelInner', 'prdSetVerifBackend', current.verification_model || '');
  });
}
window.openPRDSetLLMModal = openPRDSetLLMModal;
window._prdCloseModal = _prdCloseModal;

// GH#172 D75 — edit PRD permission_mode (PWA-only per the issue's own
// decision). Reads the existing set_permission_mode REST action.
function openPRDSetPermissionModeModal(prdID, current) {
  const modes = ['', 'default', 'plan', 'acceptEdits', 'auto', 'bypassPermissions', 'dontAsk'];
  const opts = modes.map(m => `<option value="${escHtml(m)}" ${m === current ? 'selected' : ''}>${escHtml(m || '— inherit session/config default —')}</option>`).join('');
  _prdMountModal(`
    <div class="response-modal-header">
      <strong>${t('prd_permission_mode_title')||'Automaton permission mode'}</strong>
      <button class="btn-icon" onclick="_prdCloseModal()" title="${t('btn_close')||'Close'}">&#10005;</button>
    </div>
    <form id="prdModalForm" class="response-modal-body" style="display:flex;flex-direction:column;gap:10px;">
      <div style="font-size:11px;color:var(--text2);">${t('prd_permission_mode_hint')||'claude-code --permission-mode default for tasks spawned under this automaton. Inherited by each task unless overridden there.'}</div>
      <select id="prdSetPermissionMode" class="form-select">${opts}</select>
      <div style="display:flex;gap:6px;justify-content:flex-end;">
        <button type="button" class="btn-secondary" onclick="_prdCloseModal()">${t('btn_cancel')||'Cancel'}</button>
        <button type="submit" class="btn-secondary" style="background:var(--accent2);color:#fff;">${t('btn_save')||'Save'}</button>
      </div>
    </form>
  `, () => {
    const mode = document.getElementById('prdSetPermissionMode').value;
    apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_permission_mode', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ permission_mode: mode, actor: 'operator' }),
    }).then(() => { showToast(t('prd_permission_mode_updated')||'Permission mode updated', 'success', 1500); _prdCloseModal(); _refreshAutomataOrPRD(); })
      .catch(err => showToast('Save failed: ' + String(err), 'error', 3000));
  });
}
window.openPRDSetPermissionModeModal = openPRDSetPermissionModeModal;

// BL246 v6.6.0 — unified PRD Settings modal: type, backend, effort, model,
// skills, guided_mode in one place. Splits "edit spec" (handled by
// openPRDEditModal) from non-spec settings so each form stays small and
// readable.
function openPRDSettingsModal(prdID) {
  apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID))
    .then(prd => {
      const cur = {
        type:                 prd.type || '',
        kind:                 prd.kind || '',
        lane_preference:      prd.lane_preference || 'any',
        backend:              prd.backend || '',
        effort:               prd.effort || '',
        model:                prd.model || '',
        decomposition_profile: prd.decomposition_profile || '',
        decomposition_model:  prd.decomposition_model || '',
        skills:               (prd.skills || []).join(', '),
        guided_mode:          !!prd.guided_mode,
        continue_on_story_failure: !!prd.continue_on_story_failure,
        // Per-Automaton notification events: empty list = inherit the
        // guardrail profile, then the global default.
        notify_events:          (prd.notify_events || []).slice(),
        // BL407 Phase 5 — Git.AutoPR/BaseBranch are operator-settable;
        // branch/pr_url are runtime state the executor owns, shown
        // read-only below once set.
        git_auto_pr:          !!(prd.git && prd.git.auto_pr),
        git_base_branch:      (prd.git && prd.git.base_branch) || '',
        git_branch:           (prd.git && prd.git.branch) || '',
        git_pr_url:           (prd.git && prd.git.pr_url) || '',
        max_concurrent_tasks: prd.max_concurrent_tasks || 0,
        priority:             prd.priority || 0,
        read_dirs:            (prd.read_dirs || []).join(', '),
        write_dirs:           (prd.write_dirs || []).join(', '),
      };
      ensureLLMModelLists().then(() => {
        const notifyInherit = !(prd.notify_events || []).length;
        const neffEvents = (prd.notify_events_effective && Array.isArray(prd.notify_events_effective.events))
          ? prd.notify_events_effective.events : [];
        const notifyEffectiveText = neffEvents.length
          ? neffEvents.map(k => escHtml(k)).join(', ')
          : escHtml(t('notify_events_none')||'none');
        const notifyKindOptions = _renderNotifyKindOptions(prd.notify_events || [], notifyInherit);
        _prdMountModal(`
          <div class="response-modal-header">
            <strong>${escHtml(t('prd_settings_modal_title')||'Automaton settings')}</strong>
            <button class="btn-icon" onclick="_prdCloseModal()" title="${escHtml(t('btn_close')||'Close')}">&#10005;</button>
          </div>
          <!-- v6.7.5 — gap tightened from 10px to 6px; field-group internal
               spacing standardised; footer separated by a thin border + 6px
               margin so it reads as a clear action row, not another field. -->
          <!-- v6.13.2 — operator: "edit dialog has large space in rows
               between every element". Using the same wizard-mobile shape
               so spacing matches the new-automaton wizard. -->
          <form id="prdModalForm" class="response-modal-body wizard-mobile prd-settings-modal" style="display:flex;flex-direction:column;gap:6px;">
            <div class="wizard-field">
              <label class="wizard-label">${escHtml(t('prd_settings_type_label')||'Type')}</label>
              <select id="prdSettingsType" class="form-select">
                <option value="" ${!cur.type?'selected':''}>—</option>
                ${['software','research','operational','personal'].map(v => `<option value="${v}" ${cur.type===v?'selected':''}>${v}</option>`).join('')}
              </select>
            </div>
            <div class="wizard-grid-mobile">
              <div class="wizard-field">
                <label class="wizard-label">${escHtml(t('progress_card_kind_label'))}</label>
                <select id="prdSettingsKind" class="form-select">
                  <option value="" ${!cur.kind?'selected':''}>${escHtml(t('progress_card_kind_derived'))}</option>
                  ${['feature','bug','other'].map(v => `<option value="${v}" ${cur.kind===v?'selected':''}>${escHtml(t(PC_KEYS.kind[v]))}</option>`).join('')}
                </select>
              </div>
              <div class="wizard-field">
                <label class="wizard-label">${escHtml(t('lane_fill_pref_label'))}</label>
                <select id="prdSettingsLanePreference" class="form-select">
                  ${['any','gpu','claude'].map(v => `<option value="${v}" ${cur.lane_preference===v?'selected':''}>${escHtml(t(LANE_FILL_PREF_KEYS[v]))}</option>`).join('')}
                </select>
              </div>
            </div>
            <div class="wizard-grid-mobile">
              <div class="wizard-field">
                <label class="wizard-label">${escHtml(t('prd_new_backend_label')||'Execution backend (tasks)')}</label>
                ${renderBackendSelect('prdSettingsBackend', cur.backend, `refreshLLMModelField('prdSettingsModelWrap','prdSettingsModelInner','prdSettingsBackend','')`)}
              </div>
              <div class="wizard-field">
                <label class="wizard-label">${escHtml(t('prd_new_effort_label')||'Effort')}</label>
                ${renderEffortSelect('prdSettingsEffort', cur.effort, '')}
              </div>
              <div class="wizard-field" id="prdSettingsModelWrap" style="display:none;">
                <label class="wizard-label">${escHtml(t('prd_new_model_label')||'Model (optional)')}</label>
                <div id="prdSettingsModelInner"></div>
              </div>
            </div>
            <div class="wizard-field">
              <label class="wizard-label">Planning backend (decompose)</label>
              <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;">
                ${renderBackendSelect('prdSettingsDecompositionProfile', cur.decomposition_profile, `refreshLLMModelField('prdSettingsDecompModelWrap','prdSettingsDecompModelInner','prdSettingsDecompositionProfile','')`, true)}
                <div id="prdSettingsDecompModelWrap" style="display:none;"><div id="prdSettingsDecompModelInner"></div></div>
              </div>
              <div style="font-size:10px;color:var(--text2);margin-top:2px;">Any configured LLM — opencode/claude-code get full codebase tool access; ollama/openwebui run headless. Empty = use global autonomous.planning_backend.</div>
            </div>
            <!-- v6.13.4 — operator: "skills should be a selectable list
                 from what is installed... if no skills installed say
                 no skills available". + "Message under skills selector
                 isn't necessary". Render a chip-picker that loads from
                 /api/skills; empty state shows "No skills available". -->
            <div class="wizard-field">
              <label class="wizard-label">${escHtml(t('prd_settings_skills_label')||'Skills')}</label>
              <div id="prdSettingsSkillsPicker" class="skill-chip-picker" data-current="${escHtml(cur.skills)}">
                <span style="color:var(--text2);font-size:11px;">${loadingEyeBlock()}</span>
              </div>
              <input id="prdSettingsSkills" type="hidden" value="${escHtml(cur.skills)}" />
            </div>
            <!-- BL370 — per-PRD task concurrency. 0 = use global config default (sequential if not set). -->
            <div class="wizard-field" style="margin-top:2px;">
              <label class="wizard-label">${escHtml(t('prd_settings_concurrency_label')||'Max concurrent tasks (0 = global default)')}</label>
              <input type="number" id="prdSettingsConcurrency" class="form-input" min="0" max="32" value="${cur.max_concurrent_tasks}" placeholder="0" style="width:80px;" />
              <div style="font-size:10px;color:var(--text2);margin-top:2px;">0 or 1 = sequential · 2+ = fan out independent tasks in parallel</div>
            </div>
            <div class="wizard-field" style="margin-top:2px;">
              <label class="wizard-label">${escHtml(t('prd_settings_priority_label')||'Capacity queue priority (higher runs first)')}</label>
              <input type="number" id="prdSettingsPriority" class="form-input" min="-100" max="100" value="${cur.priority}" placeholder="0" style="width:80px;" />
              <div style="font-size:10px;color:var(--text2);margin-top:2px;">${escHtml(t('prd_settings_priority_hint')||'Used when tasks wait for free capacity.')}</div>
            </div>
            <div class="wizard-field" style="margin-top:2px;">
              <label class="wizard-label">${escHtml(t('prd_settings_write_dirs_label')||'Writable directories (comma-separated, absolute; empty = project dir)')}</label>
              <input type="text" id="prdSettingsWriteDirs" class="form-input" value="${escHtml(cur.write_dirs)}" placeholder="${escHtml(prd.project_dir||'')}" />
              <label class="wizard-label" style="margin-top:6px;">${escHtml(t('prd_settings_read_dirs_label')||'Read-only directories (comma-separated, absolute)')}</label>
              <input type="text" id="prdSettingsReadDirs" class="form-input" value="${escHtml(cur.read_dirs)}" />
              <div style="font-size:10px;color:var(--text2);margin-top:2px;">${escHtml(t('prd_settings_dirs_hint')||'Workers may not read or write outside these directories.')}</div>
            </div>
            <!-- v6.13.2 — operator: "guided mode is weirdly right justified
                 but checkbox is left". Switched to a single .wizard-checkbox-row
                 with the iOS-style switch (per the global mobile-first
                 pattern); checkbox + label flow left-to-right naturally. -->
            <label class="wizard-checkbox-row" style="margin-top:4px;">
              <input type="checkbox" id="prdSettingsGuidedMode" ${cur.guided_mode?'checked':''}>
              <span>${escHtml(t('prd_settings_guided_label')||'Guided mode — pause for operator after each story for review')}</span>
            </label>
            <label class="wizard-checkbox-row" style="margin-top:4px;">
              <input type="checkbox" id="prdSettingsContinueOnStoryFailure" ${cur.continue_on_story_failure?'checked':''}>
              <span>${escHtml(t('prd_settings_continue_on_story_failure_label')||'Continue past a failed story instead of halting (default: halt for re-edit/rerun)')}</span>
            </label>
            <!-- BL407 Phase 5 — Git section: AutoPR + base-branch override
                 are operator-settable; branch/PR link are read-only
                 runtime state, shown only once the executor has set them. -->
            <div class="wizard-field" style="margin-top:4px;padding-top:8px;border-top:1px solid var(--border);">
              <label class="wizard-label">${escHtml(t('prd_settings_git_section_label')||'Git')}</label>
              <label class="wizard-checkbox-row">
                <input type="checkbox" id="prdSettingsGitAutoPR" ${cur.git_auto_pr?'checked':''}>
                <span>${escHtml(t('prd_settings_git_auto_pr_label')||'Auto-PR — push the branch and open a PR automatically on completion')}</span>
              </label>
              <div style="font-size:10px;color:var(--text2);margin:2px 0 6px;">${escHtml(t('prd_settings_git_auto_pr_hint')||'Review before enabling on an automaton whose task specs you don’t fully trust — this calls out to GitHub on your own gh credentials with no per-call confirmation.')}</div>
              <label class="wizard-label">${escHtml(t('prd_settings_git_base_branch_label')||'Base branch override (empty = repo’s own default branch)')}</label>
              <input type="text" id="prdSettingsGitBaseBranch" class="form-input" value="${escHtml(cur.git_base_branch)}" placeholder="main" />
              ${cur.git_branch ? `<div style="font-size:10px;color:var(--text2);margin-top:6px;">${escHtml(t('prd_settings_git_branch_label')||'Branch')}: <code>${escHtml(cur.git_branch)}</code></div>` : ''}
              ${cur.git_pr_url ? `<div style="font-size:10px;margin-top:2px;">${escHtml(t('prd_settings_git_pr_label')||'PR')}: <a href="${escHtml(cur.git_pr_url)}" target="_blank" rel="noopener">${escHtml(cur.git_pr_url)}</a></div>` : ''}
            </div>
            <!-- Per-Automaton notification events: closed kind set in
                 NOTIFY_EVENT_KINDS; an empty stored list means inherit
                 (guardrail profile, then the global default). -->
            <div class="wizard-field" style="margin-top:4px;padding-top:8px;border-top:1px solid var(--border);">
              <label class="wizard-label">${escHtml(t('notify_events_label')||'Notification events')}</label>
              <div style="font-size:10px;color:var(--text2);margin-bottom:4px;">${escHtml(t('notify_events_help')||'Choose which lifecycle events notify. Inherit uses the guardrail profile, then the global default.')}</div>
              <div style="font-size:10px;color:var(--text2);margin-bottom:4px;">${escHtml(t('notify_events_opt_in_help')||'Opt-in events are off by default and only notify when listed here.')}</div>
              <label class="wizard-checkbox-row" style="margin:0 0 4px;">
                <input type="checkbox" id="prdSettingsNotifyInherit" ${notifyInherit?'checked':''} onchange="_prdNotifyInheritToggle(this.checked);return true;">
                <span>${escHtml(t('notify_events_inherit')||'Inherit')}</span>
              </label>
              <div id="prdSettingsNotifyEffective" style="font-size:11px;color:var(--text2);margin:0 0 6px;display:${notifyInherit?'block':'none'};">
                <strong>${escHtml(t('notify_events_effective')||'Effective notification events')}:</strong> <span>${notifyEffectiveText}</span>
              </div>
              <div style="max-height:230px;overflow:auto;border:1px solid var(--border);border-radius:4px;padding:6px 8px;background:var(--bg2);">
                ${notifyKindOptions}
              </div>
            </div>
            <div style="display:flex;gap:6px;justify-content:flex-end;margin-top:6px;padding-top:8px;border-top:1px solid var(--border);">
              <button type="button" class="btn-secondary" onclick="_prdCloseModal()">${escHtml(t('btn_cancel')||'Cancel')}</button>
              <button type="submit" class="btn-secondary" style="background:var(--accent2);color:#fff;">${escHtml(t('btn_save')||'Save')}</button>
            </div>
          </form>
        `, () => {
          const newType = document.getElementById('prdSettingsType').value;
          const newBackend = document.getElementById('prdSettingsBackend').value;
          const newEffort = document.getElementById('prdSettingsEffort').value;
          const modelEl = document.getElementById('prdSettingsModelInner')?.querySelector('input,select');
          const newModel = modelEl ? modelEl.value.trim() : '';
          const newDecompositionProfile = document.getElementById('prdSettingsDecompositionProfile').value;
          const decompModelEl = document.getElementById('prdSettingsDecompModelInner')?.querySelector('input,select');
          const newDecompositionModel = decompModelEl ? decompModelEl.value.trim() : '';
          // v6.13.4 — read skills from the chip-picker hidden input
          // (populated by _renderSkillChipPicker on toggle).
          const newSkills = (document.getElementById('prdSettingsSkills').value || '').split(',').map(s => s.trim()).filter(Boolean);
          const newGuided = !!document.getElementById('prdSettingsGuidedMode').checked;
          const newConcurrency = parseInt(document.getElementById('prdSettingsConcurrency').value || '0', 10) || 0;

          const calls = [];
          if (newType !== cur.type) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_type', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ type: newType, actor: 'operator' }),
            }));
          }
          if (newBackend !== cur.backend || newEffort !== cur.effort || newModel !== cur.model || newDecompositionProfile !== cur.decomposition_profile || newDecompositionModel !== (cur.decomposition_model||'')) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_llm', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ backend: newBackend, effort: newEffort, model: newModel, decomposition_profile: newDecompositionProfile, decomposition_model: newDecompositionModel, actor: 'operator' }),
            }));
          }
          const skillsChanged = JSON.stringify(newSkills) !== JSON.stringify((prd.skills || []));
          if (skillsChanged) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_skills', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ skills: newSkills, actor: 'operator' }),
            }));
          }
          if (newGuided !== cur.guided_mode) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_guided_mode', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ guided_mode: newGuided, actor: 'operator' }),
            }));
          }
          const newContinueOnStoryFailure = !!document.getElementById('prdSettingsContinueOnStoryFailure').checked;
          if (newContinueOnStoryFailure !== cur.continue_on_story_failure) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_continue_on_story_failure', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ continue_on_story_failure: newContinueOnStoryFailure }),
            }));
          }
          // BL407 Phase 5 — set_git takes both fields unconditionally
          // (no partial-merge on the server side), so send both
          // whenever either one changed.
          const newGitAutoPR = !!document.getElementById('prdSettingsGitAutoPR').checked;
          const newGitBaseBranch = (document.getElementById('prdSettingsGitBaseBranch').value || '').trim();
          if (newGitAutoPR !== cur.git_auto_pr || newGitBaseBranch !== cur.git_base_branch) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_git', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ auto_pr: newGitAutoPR, base_branch: newGitBaseBranch }),
            }));
          }
          if (newConcurrency !== cur.max_concurrent_tasks) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_concurrency', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ max_concurrent_tasks: newConcurrency }),
            }));
          }
          const _splitDirs = v => (v || '').split(',').map(x => x.trim()).filter(Boolean);
          const newWriteStr = (document.getElementById('prdSettingsWriteDirs')?.value || '').trim();
          const newReadStr  = (document.getElementById('prdSettingsReadDirs')?.value || '').trim();
          if (newWriteStr !== cur.write_dirs || newReadStr !== cur.read_dirs) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_dirs', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ read_dirs: _splitDirs(newReadStr), write_dirs: _splitDirs(newWriteStr) }),
            }));
          }
          const newKind = (document.getElementById('prdSettingsKind')?.value || '');
          if (newKind !== cur.kind) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_kind', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ kind: newKind }),
            }));
          }
          const newLanePreference = document.getElementById('prdSettingsLanePreference')?.value || 'any';
          if (newLanePreference !== cur.lane_preference) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_lane_preference', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ lane_preference: newLanePreference }),
            }));
          }
          const newPriority = parseInt(document.getElementById('prdSettingsPriority')?.value || '0', 10) || 0;
          if (newPriority !== cur.priority) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_priority', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ priority: newPriority }),
            }));
          }
          // Per-Automaton notification events: with inherit checked the
          // posted list is empty (profile, then global, wins); compare
          // order-insensitively so reordering stored kinds is not a save.
          const notifyInheritOn = !!document.getElementById('prdSettingsNotifyInherit')?.checked;
          const newNotifyEvents = notifyInheritOn
            ? []
            : Array.from(document.querySelectorAll('input[data-notify-kind]:checked')).map(el => el.value);
          const curNotifySorted = (cur.notify_events || []).slice().sort();
          const newNotifySorted = newNotifyEvents.slice().sort();
          const notifyEventsChanged = JSON.stringify(curNotifySorted) !== JSON.stringify(newNotifySorted);
          if (notifyEventsChanged) {
            calls.push(apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_notify_events', {
              method: 'POST', headers: {'Content-Type':'application/json'},
              body: JSON.stringify({ notify_events: newNotifyEvents }),
            }));
          }
          if (calls.length === 0) { _prdCloseModal(); return; }
          Promise.all(calls)
            .then(() => {
              if (notifyEventsChanged) {
                showToast(t('notify_events_saved')||'Notification events saved', 'success', 1500);
              }
              showToast(t('prd_settings_saved')||'Settings saved', 'success', 1500);
              _prdCloseModal(); _refreshAutomataOrPRD();
            })
            .catch(err => {
              if (notifyEventsChanged) {
                showToast((t('notify_events_save_failed')||'Could not save notification events') + ': ' + ((err && err.message) || String(err)), 'error', 6000);
              } else {
                showToast((t('prd_settings_save_failed')||'Save failed') + ': ' + String(err), 'error', 3000);
              }
            });
        });
        // Populate model dropdowns for the current backends now that the modal is mounted.
        refreshLLMModelField('prdSettingsModelWrap', 'prdSettingsModelInner', 'prdSettingsBackend', cur.model);
        refreshLLMModelField('prdSettingsDecompModelWrap', 'prdSettingsDecompModelInner', 'prdSettingsDecompositionProfile', cur.decomposition_model || '');
      });
    })
    .catch(err => showToast('Failed to load automaton: ' + String(err), 'error', 3000));
}
// v6.13.5 — operator: "clicking settings doesn't do anything".
// Root cause: my v6.13.4 wrapper assigned a new function to
// window.openPRDSettingsModal that called the unqualified name
// openPRDSettingsModal(prdID) — which resolves through the window
// global to the wrapper itself → infinite recursion → JS error →
// Settings dial silently fails. Save a reference to the original
// function before reassignment so the wrapper calls the inner impl.
const _origOpenPRDSettingsModal = openPRDSettingsModal;
window.openPRDSettingsModal = function(prdID) {
  _origOpenPRDSettingsModal(prdID);
  // Populate the skill chip picker after the modal has mounted.
  setTimeout(() => _renderSkillChipPicker('prdSettingsSkillsPicker', 'prdSettingsSkills'), 50);
};

// v6.13.4 — operator-directed skill chip picker. Loads the synced
// skills via /api/skills, renders each as a togglable chip, and writes
// the comma-joined selection back to the hidden input. Empty-state
// renders "No skills available — sync via Settings → Automate → Skill
// Registries". Call from a setTimeout AFTER the modal mounts.
function _renderSkillChipPicker(containerId, hiddenInputId) {
  const container = document.getElementById(containerId);
  const hidden = document.getElementById(hiddenInputId);
  if (!container || !hidden) return;
  const current = new Set(
    (hidden.value || '').split(',').map(s => s.trim()).filter(Boolean)
  );
  apiFetch('/api/skills').then(resp => {
    const skills = (resp && (resp.skills || resp)) || [];
    if (!Array.isArray(skills) || skills.length === 0) {
      container.innerHTML = `<span style="color:var(--text2);font-size:12px;">${escHtml(t('skills_none_available')||'No skills available — sync via Settings → Automate → Skill Registries.')}</span>`;
      return;
    }
    const renderChips = () => {
      container.innerHTML = skills.map(s => {
        const name = (s && (s.name || s.id || s)) || '';
        if (!name) return '';
        const on = current.has(name);
        const cls = on ? 'skill-chip selected' : 'skill-chip';
        return `<button type="button" class="${cls}" data-name="${escHtml(name)}" onclick="_toggleSkillChip(this,'${escHtml(containerId)}','${escHtml(hiddenInputId)}')">${escHtml(name)}</button>`;
      }).filter(Boolean).join('');
    };
    renderChips();
  }).catch(() => {
    container.innerHTML = `<span style="color:var(--text2);font-size:12px;">${escHtml(t('skills_load_failed')||'Could not load skills.')}</span>`;
  });
}
window._renderSkillChipPicker = _renderSkillChipPicker;

window._toggleSkillChip = function(btn, containerId, hiddenInputId) {
  const name = btn.getAttribute('data-name');
  const hidden = document.getElementById(hiddenInputId);
  if (!hidden) return;
  const current = new Set(
    (hidden.value || '').split(',').map(s => s.trim()).filter(Boolean)
  );
  if (current.has(name)) { current.delete(name); btn.classList.remove('selected'); }
  else { current.add(name); btn.classList.add('selected'); }
  hidden.value = [...current].join(',');
};

function openPRDInstantiateModal(templateID) {
  const varsCSV = window.prompt('Template vars (k=v,k=v):', '') || '';
  const vars = {};
  varsCSV.split(',').forEach(kv => { const i = kv.indexOf('='); if (i > 0) vars[kv.slice(0,i).trim()] = kv.slice(i+1).trim(); });
  apiFetch('/api/autonomous/prds/' + encodeURIComponent(templateID) + '/instantiate', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ vars, actor: 'operator' }),
  }).then(() => { showToast('Template instantiated', 'success', 1500); _refreshAutomataOrPRD(); })
    .catch(err => showToast('Instantiate failed: ' + String(err), 'error', 3000));
}
window.openPRDInstantiateModal = openPRDInstantiateModal;

function toggleLLM(cfgKey, enabled, name) {
  if (!cfgKey) return;
  fetch('/api/config', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify({ [cfgKey]: enabled }),
  })
    .then(r => {
      if (r.ok) {
        showToast(name + (enabled ? ' enabled' : ' disabled'), 'success', 2000);
        loadLLMTabConfig();
      } else showToast('Save failed', 'error');
    })
    .catch(() => showToast('Save failed', 'error'));
}

function openLLMSetup(name) {
  // Session-backend kinds: settings live in the LLM registry now.
  if (_llmSessionBackendKinds && _llmSessionBackendKinds.has(name)) {
    apiFetch('/api/llms/' + encodeURIComponent(name))
      .then(llm => openLLMEditPanel(llm))
      .catch(() => openLLMEditPanel({ name, kind: name }));
    return;
  }
  const section = LLM_CFG_SECTION[name];
  if (!section) { showToast('No config fields for ' + name, 'info'); return; }
  fetch('/api/config', { headers: tokenHeader() })
    .then(r => {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    })
    .then(cfg => {
      const fields = LLM_FIELDS[name] || [];
      const sectionCfg = cfg[section] || {};
      showBackendConfigPopup(section, sectionCfg, fields, name);
    })
    .catch(err => {
      console.error('openLLMSetup error:', err);
      showToast('Failed to load config: ' + err.message, 'error');
    });
}

function setActiveLLM(name) {
  fetch('/api/config', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify({ 'session.backend_family': name }),
  })
    .then(r => r.ok ? loadLLMTabConfig() : showToast('Save failed', 'error'))
    .catch(() => showToast('Save failed', 'error'));
}

