function loadDaemonLog(offset) {
  const el = document.getElementById('daemonLogPanel');
  if (!el) return;
  state._logOffset = offset || 0;
  apiFetch(`/api/logs?lines=50&offset=${state._logOffset}`).then(data => {
    if (!data?.lines) { el.textContent = t('state_log_unavailable') || 'Log unavailable'; return; }
    el.innerHTML = data.lines.map(line => {
      // Color-code log lines
      let color = 'var(--text2)';
      if (line.includes('[warn]') || line.includes('WARNING')) color = 'var(--warning)';
      else if (line.includes('ERROR') || line.includes('[error]')) color = 'var(--error)';
      else if (line.includes('[ebpf]')) color = 'var(--success)';
      else if (line.includes('[debug]')) color = 'var(--accent2)';
      return `<div style="color:${color};padding:1px 0;white-space:pre-wrap;word-break:break-all;">${escHtml(line)}</div>`;
    }).join('');
    const info = document.getElementById('daemonLogInfo');
    if (info) info.textContent = `Showing ${data.lines.length} of ${data.total} lines (offset ${state._logOffset})`;
  }).catch(() => { el.textContent = t('state_log_unavailable') || 'Log unavailable'; });
}
window.loadDaemonLog = loadDaemonLog;

// Auto-refresh daemon log every 10s when visible on monitor tab
setInterval(() => {
  if (state.activeView === 'settings' && _settingsTab === 'monitor' && document.getElementById('daemonLogPanel')) {
    loadDaemonLog(state._logOffset || 0);
  }
}, 10000);

function loadCommsConfig() {
  // Settings-tab federation pass (2026-10-08): both raw fetch()es --
  // never reflected a selected remote server's own comms config, and
  // any failure (including a federated 401/403/502) was silently
  // swallowed below with zero visible feedback.
  Promise.all([
    apiFetch('/api/config'),
    apiFetch('/api/interfaces').catch(() => [])
  ]).then(([cfg, interfaces]) => {
    if (!cfg) return;
    state._interfaces = interfaces || [];
    for (const sec of COMMS_CONFIG_FIELDS) {
      const el = document.getElementById('ccfg_' + sec.id);
      if (!el) continue;
      let html = '';
      for (const f of sec.fields) {
        const parts = f.key.split('.');
        const val = parts.reduce((o, k) => (o && o[k] !== undefined) ? o[k] : '', cfg);
        if (f.type === 'html') {
          html += f.html || '';
        } else if (f.type === 'button') {
          // BL191/BL189 (v5.2.0) — settings-side action button. Calls a
          // named function on the window object so handlers can live
          // alongside other PWA code.
          html += `<div class="settings-row" style="justify-content:space-between;align-items:center;">
            <div class="settings-label">${escHtml(f.label)}</div>
            <button class="btn-secondary" style="font-size:12px;" onclick="(window['${escHtml(f.action || '')}']||function(){showToast('Action ${escHtml(f.action || '')} not wired','error',2000);})()">Run</button>
          </div>`;
        } else if (f.type === 'select') {
          const opts = (f.options || []).map(o => `<option value="${escHtml(o)}" ${String(val) === o ? 'selected' : ''}>${escHtml(o)}</option>`).join('');
          html += `<div class="settings-row" style="justify-content:space-between;">
            <div class="settings-label">${escHtml(f.label)}</div>
            <select class="form-select general-cfg-input" onchange="saveGeneralField('${f.key}', this.value)">${opts}</select>
          </div>`;
        } else if (f.type === 'plan_tier_table') {
          // plan tier inflight caps: one numeric input per tier + Save.
          // PUTs the table as a JSON object (the daemon's PUT accepts
          // object, JSON-string, or compact "tier=N,tier=N" forms).
          const table = (val && typeof val === 'object') ? val : {};
          const tierInputs = ['pro', 'max_5x', 'max_20x', 'api'].map(tier => {
            const v = parseInt(table[tier], 10);
            return `<label style="display:flex;align-items:center;gap:4px;font-size:11px;color:var(--text2);">
              <span>${tier}</span>
              <input type="number" min="0" class="form-input" style="width:72px;" value="${isNaN(v) ? '' : v}" data-plan-tier="${tier}" />
            </label>`;
          }).join('');
          html += `<div class="settings-row" style="flex-direction:column;align-items:stretch;">
            <div class="settings-label">${escHtml(f.label)}</div>
            <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:4px;padding:8px 10px;background:var(--bg);border:1px solid var(--border);border-radius:6px;">
              ${tierInputs}
              <button class="btn-secondary" style="font-size:11px;" onclick="savePlanTierTable()">${escHtml(t('settings_plan_tier_save')||'Save')}</button>
            </div>
            <div style="font-size:11px;color:var(--text2);margin-top:3px;">${escHtml(f.hint || (t('settings_plan_tier_hint')||'Per-tier inflight caps; 0 or blank tier = unlimited; an explicit per-LLM max_inflight > 0 wins.'))}</div>
          </div>`;
        } else if (f.type === 'plan_tier_allocation_table') {
          // plan tier allocation: one dollar input per tier + Save, PUT as a
          // JSON object like the inflight caps table above.
          const table = (val && typeof val === 'object') ? val : {};
          const tierInputs = ['pro', 'max_5x', 'max_20x', 'api'].map(tier => {
            const v = parseFloat(table[tier]);
            return `<label style="display:flex;align-items:center;gap:4px;font-size:11px;color:var(--text2);">
              <span>${tier}</span>
              <input type="number" min="0" step="any" class="form-input" style="width:88px;" value="${isNaN(v) ? '' : v}" data-plan-tier-allocation="${tier}" />
            </label>`;
          }).join('');
          html += `<div class="settings-row" style="flex-direction:column;align-items:stretch;">
            <div class="settings-label">${escHtml(f.labelKey ? (t(f.labelKey)||f.label) : f.label)}</div>
            <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:4px;padding:8px 10px;background:var(--bg);border:1px solid var(--border);border-radius:6px;">
              ${tierInputs}
              <button class="btn-secondary" style="font-size:11px;" onclick="savePlanTierAllocationTable()">${escHtml(t('settings_plan_tier_save')||'Save')}</button>
            </div>
            <div style="font-size:11px;color:var(--text2);margin-top:3px;">${escHtml(t('settings_plan_tier_allocation_hint')||f.hint)}</div>
          </div>`;
        } else if (f.type === 'interface_select') {
          // v5.23.0 — operator-reported: comms interface_select wasn't
          // rendering items (treated state._interfaces strings but the
          // entries are {addr, label, name} objects), AND it was single-
          // select where operators want multi-select for binding to
          // multiple interfaces. Now mirrors the GENERAL_CONFIG_FIELDS
          // multi-select with the connected-iface protection.
          const currentVals = String(val || '0.0.0.0').split(',').map(s => s.trim());
          const ifaces = (interfaces && interfaces.length > 0) ? interfaces : [
            { addr: '0.0.0.0', label: '0.0.0.0 (all interfaces)' },
            { addr: '127.0.0.1', label: '127.0.0.1 (localhost)' },
          ];
          const connIf = typeof _resolveConnectedInterface === 'function' ? _resolveConnectedInterface() : null;
          const checkboxes = ifaces.map(iface => {
            const checked = currentVals.includes(iface.addr);
            const isConnected = connIf && iface.addr === connIf.addr;
            const badge = isConnected
              ? ' <span style="color:var(--success);font-size:10px;">(connected — auto-protected)</span>'
              : '';
            return `<label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer;padding:3px 0;">
              <input type="checkbox" ${checked ? 'checked' : ''} value="${escHtml(iface.addr)}"
                onchange="saveInterfaceField('${f.key}', this.closest('.iface-list'), this)" />
              <span style="font-family:monospace;color:var(--text);">${escHtml(iface.label)}${badge}</span>
            </label>`;
          }).join('');
          html += `<div class="settings-row" style="flex-direction:column;align-items:stretch;">
            <div class="settings-label">${escHtml(f.label)}</div>
            <div class="iface-list" style="display:flex;flex-direction:column;gap:2px;margin-top:4px;padding:8px 10px;background:var(--bg);border:1px solid var(--border);border-radius:6px;">
              ${checkboxes}
            </div>
          </div>`;
        } else if (f.type === 'toggle') {
          const checked = !!val;
          html += `<div class="settings-row" style="justify-content:space-between;align-items:center;">
            <div class="settings-label">${escHtml(f.label)}</div>
            <label class="toggle-switch">
              <input type="checkbox" ${checked ? 'checked' : ''} onchange="saveGeneralField('${f.key}', this.checked)" />
              <span class="toggle-slider"></span>
            </label>
          </div>`;
        } else if (f.type === 'acme_cert_source') {
          // BL397 — certificate-source selector: Self-signed | Custom | Let's
          // Encrypt (ACME). Folds the ACME config into the existing TLS card
          // instead of a disconnected new one, per operator direction.
          const acmeEnabled = !!(cfg.acme && cfg.acme.enabled);
          const autoGen = !!(cfg.server && cfg.server.tls_auto_generate);
          const mode = acmeEnabled ? 'acme' : (autoGen ? 'selfsigned' : 'custom');
          const domains = ((cfg.acme && cfg.acme.domains) || []).join(', ');
          const endpoint = (cfg.acme && cfg.acme.endpoint) || 'staging';
          const acmeMethod = (cfg.acme && cfg.acme.method) || 'http01';
          const dns01 = (cfg.acme && cfg.acme.dns01) || {};
          const certPath = (cfg.server && cfg.server.tls_cert) || '';
          const keyPath = (cfg.server && cfg.server.tls_key) || '';
          html += `<div class="settings-row" style="justify-content:space-between;">
            <div class="settings-label">${escHtml(f.label)}</div>
            <select class="form-select general-cfg-input" onchange="onCertSourceChange(this.value)">
              <option value="selfsigned" ${mode === 'selfsigned' ? 'selected' : ''}>Self-signed (auto-generate)</option>
              <option value="custom" ${mode === 'custom' ? 'selected' : ''}>Custom cert path</option>
              <option value="acme" ${mode === 'acme' ? 'selected' : ''}>Let's Encrypt (ACME)</option>
            </select>
          </div>
          <div id="certSourceCustom" style="${mode === 'custom' ? '' : 'display:none'}">
            <div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">TLS cert path</div>
              <input type="text" class="form-input general-cfg-input" value="${escHtml(certPath)}"
                onchange="saveGeneralField('server.tls_cert', this.value)" />
            </div>
            <div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">TLS key path</div>
              <input type="text" class="form-input general-cfg-input" value="${escHtml(keyPath)}"
                onchange="saveGeneralField('server.tls_key', this.value)" />
            </div>
          </div>
          <div id="certSourceAcme" style="${mode === 'acme' ? '' : 'display:none'}">
            <div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">Domains (comma-separated)</div>
              <input type="text" class="form-input general-cfg-input" value="${escHtml(domains)}"
                placeholder="spaceportsouth.dmzs.com" onchange="saveGeneralField('acme.domains', this.value)" />
            </div>
            <div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">Endpoint</div>
              <select class="form-select general-cfg-input" onchange="saveGeneralField('acme.endpoint', this.value)">
                <option value="staging" ${endpoint === 'staging' ? 'selected' : ''}>Staging (testing, untrusted certs)</option>
                <option value="production" ${endpoint === 'production' ? 'selected' : ''}>Production (trusted certs)</option>
              </select>
            </div>
            <div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">Validation method</div>
              <select class="form-select general-cfg-input" id="acmeMethodSelect" onchange="saveGeneralField('acme.method', this.value); document.getElementById('acmeDns01Fields').style.display = this.value === 'dns01' ? '' : 'none';">
                <option value="http01" ${acmeMethod === 'http01' ? 'selected' : ''}>HTTP-01 (no DNS management, no wildcard)</option>
                <option value="dns01" ${acmeMethod === 'dns01' ? 'selected' : ''}>DNS-01 (wildcard support, needs a provider token)</option>
              </select>
            </div>
            <div id="acmeDns01Fields" style="${acmeMethod === 'dns01' ? '' : 'display:none'}">
              <div class="settings-row" style="justify-content:space-between;">
                <div class="settings-label">DNS provider</div>
                <select class="form-select general-cfg-input" onchange="saveGeneralField('acme.dns01.provider', this.value)">
                  <option value="cloudflare" ${(dns01.provider || 'cloudflare') === 'cloudflare' ? 'selected' : ''}>Cloudflare</option>
                </select>
              </div>
              <div class="settings-row" style="justify-content:space-between;">
                <div class="settings-label">Provider token secret ref</div>
                <input type="password" class="form-input general-cfg-input" placeholder="\${secret:cf-zone-edit-token}"
                  onchange="saveGeneralField('acme.dns01.token_secret', this.value)" />
              </div>
              <div class="settings-row" style="justify-content:space-between;">
                <div class="settings-label">Zone ID (reference only)</div>
                <input type="text" class="form-input general-cfg-input" value="${escHtml(dns01.zone_id || '')}"
                  onchange="saveGeneralField('acme.dns01.zone_id', this.value)" />
              </div>
              <div style="font-size:11px;color:var(--text2);padding:2px 12px 6px;">
                Zone-scoped token only (Cloudflare "Zone &gt; DNS &gt; Edit" on one zone) — never the account-global key. Stored via the secrets manager, referenced here as <code>\${secret:name}</code>, never shown once saved.
              </div>
            </div>
            <div id="acmeStatusCard" style="font-size:12px;color:var(--text2);padding:8px 0;">${loadingEyeBlock('Loading cert status…')}</div>
            <div style="display:flex;gap:8px;padding:4px 0;">
              <button class="btn-secondary" style="font-size:11px;" onclick="acmeRenewNow()">Renew now</button>
              <button class="btn-secondary" style="font-size:11px;" onclick="acmeVerifyNow()">Verify</button>
            </div>
          </div>`;
        } else if (f.type === 'readonly') {
          // v5.28.3 — show the effective config value with no inline edit
          // control. Used to point operators at the canonical control
          // when a value is derived/synced from somewhere else (e.g.
          // whisper.language tracks the PWA UI language picker).
          html += `<div class="settings-row" style="justify-content:space-between;">
            <div class="settings-label">${escHtml(f.label)}</div>
            <div class="settings-value" style="font-family:monospace;color:var(--text2);">${escHtml(String(val || '—'))}</div>
          </div>`;
        } else {
          html += `<div class="settings-row" style="justify-content:space-between;">
            <div class="settings-label"${f.helpKey ? ` title="${escHtml(t(f.helpKey) || '')}"` : ''}>${escHtml(f.label)}</div>
            <input type="${f.type === 'number' ? 'number' : 'text'}" class="form-input general-cfg-input" value="${escHtml(String(val === 0 ? 0 : (val || '')))}"
              placeholder="${escHtml(f.placeholder || '')}"${f.min !== undefined ? ` min="${f.min}"` : ''}
              onchange="saveGeneralField('${f.key}', this.value)" />
          </div>`;
        }
      }
      el.innerHTML = html;
      if (document.getElementById('acmeStatusCard')) loadAcmeStatus(); // BL397
    }
  }).catch(e => {
    const msg = _fedMsg(e, null);
    if (!msg) return; // a local failure here was already silent before this pass -- preserve that
    for (const sec of COMMS_CONFIG_FIELDS) {
      const el = document.getElementById('ccfg_' + sec.id);
      if (el) el.innerHTML = `<span style="color:var(--error);font-size:12px;">${escHtml(msg)}</span>`;
    }
  });
}

// BL397 — ACME subsystem card helpers.
function onCertSourceChange(mode) {
  const patch = {};
  if (mode === 'selfsigned') {
    patch['server.tls_auto_generate'] = true;
    patch['acme.enabled'] = false;
  } else if (mode === 'custom') {
    patch['server.tls_auto_generate'] = false;
    patch['acme.enabled'] = false;
  } else if (mode === 'acme') {
    patch['acme.enabled'] = true;
    patch['server.tls_auto_generate'] = false;
  }
  fetch('/api/config', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify(patch),
  }).then(r => {
    if (!r.ok) { showToast('Save failed', 'error'); return; }
    showToast('Saved — restart required to apply', 'success', 2500);
    const hint = document.getElementById('restartHint');
    if (hint) hint.style.display = 'inline';
    if (state.autoRestartOnConfig) triggerAutoRestart();
    loadCommsConfig();
  }).catch(() => showToast('Save failed', 'error'));
}

function loadAcmeStatus() {
  const el = document.getElementById('acmeStatusCard');
  if (!el) return;
  apiFetch('/api/acme/status').then(data => {
    if (!data || !data.enabled || !data.domains || !data.domains.length) {
      el.textContent = 'Not yet issued — save settings, then restart to start the ACME subsystem.';
      return;
    }
    el.innerHTML = data.domains.map(d => {
      const exp = d.not_after ? new Date(d.not_after).toLocaleDateString() : '—';
      const label = d.in_flight ? 'issuing…' : (d.issued ? ('expires ' + exp) : 'not issued yet');
      const err = d.last_error ? ` <span style="color:var(--error);">(${escHtml(d.last_error)})</span>` : '';
      return `<div>${escHtml(d.domain)}: ${escHtml(label)}${err}</div>`;
    }).join('');
  }).catch(() => { el.textContent = 'Status unavailable.'; });
}

function acmeRenewNow() {
  showToast('Requesting renewal…', 'info', 2000);
  apiFetch('/api/acme/renew', { method: 'POST' }).then(() => {
    showToast('Renewed', 'success', 2000);
    loadAcmeStatus();
  }).catch(err => showToast('Renew failed: ' + err.message, 'error'));
}

function acmeVerifyNow() {
  showToast('Verifying…', 'info', 1500);
  apiFetch('/api/acme/verify').then(data => {
    if (data && data.ok) showToast('Verify OK — DNS resolves, ACME directory reachable', 'success', 3000);
    else showToast('Verify found issues — check the domains list for details', 'warning', 3500);
  }).catch(err => showToast('Verify failed: ' + err.message, 'error'));
}

function loadLLMTabConfig() {
  loadWebSearchProvidersList(); // BL391
  const nodeP = typeof window._loadComputeNodesCache === 'function'
    ? window._loadComputeNodesCache() : Promise.resolve([]);
  Promise.all([apiFetch('/api/config'), nodeP]).then(([cfg]) => {
    if (!cfg) return;
    // Resolve default for embedder_host from ollama.host
    const ollamaHost = cfg.ollama?.host || 'http://localhost:11434';
    const computeNodes = window._computeNodesCache || [];
    const embedderProvider = cfg.memory?.embedder || 'ollama';
    for (const sec of LLM_CONFIG_FIELDS) {
      const el = document.getElementById('llmCfg_' + sec.id);
      if (!el) continue;
      let html = '';
      for (const f of sec.fields) {
        // Navigate config path, preserving false/0 values
        const parts = f.key.split('.');
        let val = cfg;
        for (const k of parts) {
          if (val && typeof val === 'object' && k in val) val = val[k];
          else { val = undefined; break; }
        }
        // For embedder_host, show the actual ollama.host as default
        let effectiveVal = val;
        let effectivePlaceholder = f.placeholder || '';
        if (f.key === 'memory.embedder_host') {
          effectivePlaceholder = ollamaHost;
          if (!val) effectiveVal = ollamaHost;
        }

        if (f.type === 'toggle') {
          const checked = !!val;
          const saveAction = f.key === 'memory.enabled'
            ? `testAndEnableMemory(this)`
            : `saveGeneralField('${f.key}', this.checked)`;
          html += `<div class="settings-row" style="justify-content:space-between;align-items:center;">
            <div class="settings-label">${escHtml(f.label)}</div>
            <div style="display:flex;align-items:center;gap:6px;">
              ${f.key === 'memory.enabled' ? `<button class="btn-secondary" style="font-size:10px;padding:2px 6px;" onclick="testMemoryConnection()">Test</button>` : ''}
              <label class="toggle-switch">
                <input type="checkbox" ${checked ? 'checked' : ''} onchange="${saveAction}" />
                <span class="toggle-slider"></span>
              </label>
            </div>
          </div>`;
        } else if (f.type === 'embedder_node') {
          // Compute node picker for embedder_host: filtered by current embedder provider.
          if (embedderProvider === 'openai') {
            const displayVal = val !== undefined && val !== null ? String(val) : '';
            html += `<div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">${escHtml(f.label)} (URL)</div>
              <input type="text" class="form-input general-cfg-input" value="${escHtml(displayVal)}"
                placeholder="https://api.openai.com"
                onchange="saveGeneralField('${f.key}', this.value)" />
            </div>`;
          } else {
            // ollama (or other local) — show compute node dropdown.
            const kind = embedderProvider; // 'ollama' → kind='ollama'
            const matchingNodes = computeNodes.filter(n => !kind || n.kind === kind || kind === 'ollama' && n.kind === 'ollama');
            const currentAddr = val || ollamaHost;
            const nodeOpts = [
              `<option value="">${escHtml('(use ollama.host default: ' + ollamaHost + ')')}</option>`,
              ...matchingNodes.map(n => `<option value="${escHtml(n.address)}" ${currentAddr === n.address ? 'selected' : ''}>${escHtml(n.name)} — ${escHtml(n.address)}</option>`),
            ].join('');
            html += `<div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">${escHtml(f.label)}</div>
              <select class="form-select general-cfg-input" onchange="saveGeneralField('${f.key}', this.value)">${nodeOpts}</select>
            </div>`;
          }
        } else if (f.type === 'select') {
          const opts = f.options.map(o => `<option value="${escHtml(o)}" ${String(val || '') === o ? 'selected' : ''}>${escHtml(o)}</option>`).join('');
          html += `<div class="settings-row" style="justify-content:space-between;">
            <div class="settings-label">${escHtml(f.label)}</div>
            <select class="form-select general-cfg-input" onchange="saveGeneralField('${f.key}', this.value)">${opts}</select>
          </div>`;
        } else if (f.csv) {
          // BL327 — badge/chip multi-select for CSV list fields
          const displayVal = effectiveVal !== undefined && effectiveVal !== null ? String(effectiveVal) : '';
          const inputId = 'gcfg-input-' + f.key.replace(/[^a-z0-9_-]/gi, '-');
          html += `<div class="settings-row" style="flex-direction:column;align-items:flex-start;gap:4px;">
            <div class="settings-label">${escHtml(f.label)}</div>
            ${renderBadgeInput(inputId, displayVal, { freeform: true, placeholder: f.placeholder || 'Add item…' })}
          </div>`;
          // Wire save on change after insertion (deferred)
          setTimeout(() => {
            const el2 = document.getElementById(inputId);
            if (el2) {
              initBadgeInput(inputId, { freeform: true });
              el2.addEventListener('change', () => saveGeneralField(f.key, getBadgeInputValue(inputId)));
            }
          }, 0);
        } else {
          const displayVal = effectiveVal !== undefined && effectiveVal !== null ? String(effectiveVal) : '';
          const inputId = 'gcfg-input-' + f.key.replace(/[^a-z0-9_-]/gi, '-');
          html += `<div class="settings-row" style="justify-content:space-between;">
            <div class="settings-label"${f.helpKey ? ` title="${escHtml(t(f.helpKey) || '')}"` : ''}>${escHtml(f.label)}</div>
            <span style="display:flex;align-items:center;flex:1;justify-content:flex-end;">
              <input id="${inputId}" type="${f.type === 'number' ? 'number' : 'text'}" class="form-input general-cfg-input" value="${escHtml(displayVal)}"
                placeholder="${escHtml(effectivePlaceholder)}"
                onchange="saveGeneralField('${f.key}', this.value)" />
            </span>
          </div>`;
        }
      }
      el.innerHTML = html;
      // #95 — OpenCode Providers sub-section: load key status from
      // /api/opencode/providers and append the three provider rows.
      if (sec.id === 'opencode') {
        loadOpenCodeProvidersCard(el);
      }
    }
  }).catch(e => {
    const msg = _fedMsg(e, null);
    if (!msg) return; // a local failure here was already silent before this pass -- preserve that
    for (const sec of LLM_CONFIG_FIELDS) {
      const el = document.getElementById('llmCfg_' + sec.id);
      if (el) el.innerHTML = `<span style="color:var(--error);font-size:12px;">${escHtml(msg)}</span>`;
    }
  });
}

// ── BL391 — Web Search Providers card (Settings → Compute) ─────────────────
// List + inline-form pattern, mirrors the Remote Servers card (loadServersList
// et al., comms tab) rather than a modal — a provider entry is small enough
// (name/type/enabled/priority + 2-4 type-specific fields) not to need one.

function loadWebSearchProvidersList() {
  const el = document.getElementById('webSearchProvidersList');
  if (!el) return;
  el.innerHTML = loadingEyeBlock();
  apiFetch('/api/websearch/providers').then(d => {
    const list = (d && d.providers) ? d.providers : [];
    if (!list.length) {
      el.innerHTML = `<div style="color:var(--text-dim,#888);font-size:12px;">${t('websearch_providers_empty')||'No search providers configured.'}</div>`;
      return;
    }
    el.innerHTML = list.slice().sort((a,b) => (a.priority||0)-(b.priority||0)).map(p => `
      <div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--border);">
        <div style="flex:1;min-width:0;">
          <div style="font-size:13px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escHtml(p.name)} <span style="color:var(--text2);font-weight:400;">(${escHtml(p.type)}, priority ${p.priority||0})</span></div>
          <div style="font-size:11px;color:var(--text-dim,#888);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${p.type==='searxng' ? escHtml(p.url||'') + ' · engine: ' + escHtml(p.engine||'bing') : (t('websearch_provider_apikey_set')||'API key set')}</div>
        </div>
        <span style="font-size:11px;padding:2px 6px;border-radius:10px;background:${p.enabled?'var(--accent2,#4f8)':'var(--bg3,#2d3148)'};color:${p.enabled?'#fff':'var(--text-dim,#888)'};">${p.enabled?(t('on_label')||'on'):(t('off_label')||'off')}</span>
        <button onclick="testWebSearchProvider(${JSON.stringify(p.name)}, this)" style="font-size:11px;padding:2px 8px;border-radius:4px;background:var(--bg3,#2d3148);color:var(--text);border:1px solid var(--border);cursor:pointer;">${t('websearch_provider_test_btn')||'Test'}</button>
        <button onclick="toggleWebSearchProviderEnabled(${JSON.stringify(p.name)}, ${!p.enabled})" style="font-size:11px;padding:2px 8px;border-radius:4px;background:var(--bg3,#2d3148);color:var(--text);border:1px solid var(--border);cursor:pointer;">${p.enabled?(t('disable_btn')||'Disable'):(t('enable_btn')||'Enable')}</button>
        <button onclick="showWebSearchProviderForm(${escHtml(JSON.stringify(p))})" style="font-size:11px;padding:2px 8px;border-radius:4px;background:var(--bg3,#2d3148);color:var(--text);border:1px solid var(--border);cursor:pointer;">${t('edit_btn')||'Edit'}</button>
        <button onclick="deleteWebSearchProvider(${JSON.stringify(p.name)})" style="font-size:11px;padding:2px 8px;border-radius:4px;background:var(--bg3,#2d3148);color:var(--danger,#f66);border:1px solid var(--border);cursor:pointer;">${t('delete_btn')||'Delete'}</button>
      </div>`).join('');
  }).catch(() => {
    el.innerHTML = `<div style="color:var(--danger,#f66);font-size:12px;">${t('websearch_providers_load_failed')||'Failed to load providers.'}</div>`;
  });
}

function _webSearchProviderFormTypeChanged() {
  const typeEl = document.getElementById('webSearchProviderFormType');
  const sxWrap = document.getElementById('webSearchProviderFormSearxngFields');
  const braveWrap = document.getElementById('webSearchProviderFormBraveFields');
  if (!typeEl || !sxWrap || !braveWrap) return;
  const isBrave = typeEl.value === 'brave';
  sxWrap.style.display = isBrave ? 'none' : '';
  braveWrap.style.display = isBrave ? '' : 'none';
}

function showWebSearchProviderForm(entry) {
  const wrap = document.getElementById('webSearchProviderFormWrap');
  const nameEl = document.getElementById('webSearchProviderFormName');
  const typeEl = document.getElementById('webSearchProviderFormType');
  const priorityEl = document.getElementById('webSearchProviderFormPriority');
  const urlEl = document.getElementById('webSearchProviderFormURL');
  const engineEl = document.getElementById('webSearchProviderFormEngine');
  const apiKeyEl = document.getElementById('webSearchProviderFormAPIKey');
  const numResultsEl = document.getElementById('webSearchProviderFormNumResults');
  const enabledEl = document.getElementById('webSearchProviderFormEnabled');
  const editNameEl = document.getElementById('webSearchProviderFormEditName');
  const titleEl = document.getElementById('webSearchProviderFormTitle');
  const errEl = document.getElementById('webSearchProviderFormError');
  if (!wrap || !nameEl) return;
  if (titleEl) titleEl.textContent = entry ? `${t('websearch_provider_edit_title')||'Edit provider'} — ${entry.name}` : (t('websearch_provider_add_btn')||'Add Provider');
  nameEl.value = entry ? (entry.name||'') : '';
  nameEl.disabled = !!entry;
  typeEl.value = entry ? (entry.type||'searxng') : 'searxng';
  priorityEl.value = entry ? (entry.priority||0) : 0;
  urlEl.value = entry ? (entry.url||'') : '';
  engineEl.value = entry ? (entry.engine||'') : '';
  apiKeyEl.value = ''; // write-only — never pre-filled, even on edit
  numResultsEl.value = entry ? (entry.num_results||10) : 10;
  if (enabledEl) enabledEl.checked = entry ? (entry.enabled!==false) : true;
  if (editNameEl) editNameEl.value = entry ? (entry.name||'') : '';
  if (errEl) { errEl.textContent = ''; errEl.style.display = 'none'; }
  _webSearchProviderFormTypeChanged();
  wrap.style.display = '';
}

function closeWebSearchProviderForm() {
  const wrap = document.getElementById('webSearchProviderFormWrap');
  if (wrap) wrap.style.display = 'none';
}

function saveWebSearchProvider() {
  const nameEl = document.getElementById('webSearchProviderFormName');
  const typeEl = document.getElementById('webSearchProviderFormType');
  const priorityEl = document.getElementById('webSearchProviderFormPriority');
  const urlEl = document.getElementById('webSearchProviderFormURL');
  const engineEl = document.getElementById('webSearchProviderFormEngine');
  const apiKeyEl = document.getElementById('webSearchProviderFormAPIKey');
  const numResultsEl = document.getElementById('webSearchProviderFormNumResults');
  const enabledEl = document.getElementById('webSearchProviderFormEnabled');
  const editNameEl = document.getElementById('webSearchProviderFormEditName');
  const errEl = document.getElementById('webSearchProviderFormError');
  if (!nameEl || !typeEl) return;
  const name = nameEl.value.trim();
  const editName = editNameEl ? editNameEl.value : '';
  const isEdit = !!editName;
  if (!isEdit && !name) {
    if (errEl) { errEl.textContent = t('websearch_provider_name_required')||'Name is required.'; errEl.style.display = ''; }
    return;
  }
  const body = {
    type: typeEl.value,
    enabled: enabledEl ? enabledEl.checked : true,
    priority: parseInt(priorityEl.value, 10) || 0,
    num_results: parseInt(numResultsEl.value, 10) || 10,
  };
  if (!isEdit) body.name = name;
  if (typeEl.value === 'searxng') {
    body.url = urlEl.value.trim();
    body.engine = engineEl.value.trim() || 'bing';
  } else if (apiKeyEl.value.trim()) {
    body.api_key = apiKeyEl.value.trim();
  }
  const method = isEdit ? 'PATCH' : 'POST';
  const path = isEdit ? `/api/websearch/providers/${encodeURIComponent(editName)}` : '/api/websearch/providers';
  apiFetch(path, { method, headers: {'Content-Type':'application/json'}, body: JSON.stringify(body) })
    .then(() => { closeWebSearchProviderForm(); loadWebSearchProvidersList(); })
    .catch(e => { if (errEl) { errEl.textContent = e.message || (t('save_failed')||'Save failed.'); errEl.style.display = ''; } });
}

function deleteWebSearchProvider(name) {
  if (!confirm((t('websearch_provider_delete_confirm')||'Delete search provider') + ` "${name}"?`)) return;
  apiFetch(`/api/websearch/providers/${encodeURIComponent(name)}`, { method: 'DELETE' })
    .then(() => loadWebSearchProvidersList())
    .catch(e => showToast(e.message || (t('delete_failed')||'Delete failed.'), 'error'));
}

function toggleWebSearchProviderEnabled(name, enabled) {
  apiFetch(`/api/websearch/providers/${encodeURIComponent(name)}/${enabled?'enable':'disable'}`, { method: 'POST' })
    .then(() => loadWebSearchProvidersList())
    .catch(e => showToast(e.message || (t('save_failed')||'Save failed.'), 'error'));
}

function testWebSearchProvider(name, btnEl) {
  const origText = btnEl ? btnEl.textContent : '';
  if (btnEl) { btnEl.disabled = true; btnEl.textContent = t('testing_label')||'Testing…'; }
  apiFetch(`/api/websearch/providers/${encodeURIComponent(name)}/test`, { method: 'POST' })
    .then(d => {
      if (d && d.ok) showToast((t('websearch_provider_test_ok')||'Provider reachable') + ` (${d.result_count||0} ${t('results_label')||'results'})`, 'success');
      else showToast((t('websearch_provider_test_failed')||'Test failed') + ': ' + ((d&&d.error)||'unknown error'), 'error');
    })
    .catch(e => showToast(e.message || (t('websearch_provider_test_failed')||'Test failed.'), 'error'))
    .finally(() => { if (btnEl) { btnEl.disabled = false; btnEl.textContent = origText; } });
}

// loadOpenCodeProvidersCard fetches provider key status and appends the
// Providers sub-section to the OpenCode settings card element.
function loadOpenCodeProvidersCard(parentEl) {
  const PROVIDERS = ['anthropic', 'openai', 'google'];
  const labelKey = { anthropic: 'opencode_provider_anthropic', openai: 'opencode_provider_openai', google: 'opencode_provider_google' };

  fetch('/api/opencode/providers', { headers: tokenHeader() })
    .then(r => r.ok ? r.json() : null)
    .catch(() => null)
    .then(data => {
      const providerData = (data && data.providers) ? data.providers : {};
      let html = `<div style="margin-top:10px;border-top:1px solid var(--border);padding-top:8px;">
        <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:6px;">${escHtml(t('opencode_providers')||'Providers')}</div>`;
      for (const p of PROVIDERS) {
        const info = providerData[p] || {};
        const isSet = !!info.api_key_set;
        const badgeStyle = isSet
          ? 'background:var(--success,#22c55e);color:#fff;'
          : 'background:var(--border);color:var(--text2);';
        const badgeText = isSet
          ? (t('opencode_provider_key_set')||'Configured')
          : (t('opencode_provider_key_not_set')||'Not set');
        const inputId = 'oc_provider_key_' + p;
        const label = t(labelKey[p]) || p.charAt(0).toUpperCase() + p.slice(1);
        html += `<div class="settings-row" style="align-items:center;gap:8px;flex-wrap:wrap;">
          <div class="settings-label" style="min-width:80px;">${escHtml(label)}</div>
          <span style="font-size:10px;padding:2px 6px;border-radius:3px;${badgeStyle}">${escHtml(badgeText)}</span>
          <span style="display:flex;align-items:center;gap:4px;flex:1;justify-content:flex-end;">
            <input id="${escHtml(inputId)}" type="password" class="form-input" placeholder="sk-…"
              style="max-width:220px;" autocomplete="new-password" />
            <button class="btn-secondary" style="font-size:11px;white-space:nowrap;"
              onclick="saveOpenCodeProviderKey('${p}','${inputId}')">
              ${escHtml(t('opencode_provider_save')||'Save key')}
            </button>
          </span>
        </div>`;
      }
      html += '</div>';
      parentEl.insertAdjacentHTML('beforeend', html);
    });
}
window.loadOpenCodeProvidersCard = loadOpenCodeProvidersCard;

// saveOpenCodeProviderKey PUTs the entered API key for a provider and
// refreshes the card to show the updated badge.
function saveOpenCodeProviderKey(provider, inputId) {
  const input = document.getElementById(inputId);
  if (!input) return;
  const key = input.value.trim();
  if (!key) { showToast('Enter an API key first', 'error', 2000); return; }
  fetch('/api/opencode/providers', {
    method: 'PUT',
    headers: Object.assign({ 'Content-Type': 'application/json' }, tokenHeader()),
    body: JSON.stringify({ provider, api_key: key }),
  })
  .then(r => {
    if (!r.ok) return r.text().then(t => Promise.reject(t));
    input.value = '';
    showToast((t('opencode_provider_key_set')||'Configured') + ' — ' + provider, 'success', 2000);
    // Refresh the compute tab config to update the badge.
    loadLLMTabConfig();
  })
  .catch(err => showToast('Save failed: ' + String(err), 'error', 3000));
}
window.saveOpenCodeProviderKey = saveOpenCodeProviderKey;

// Locale label for one option of a select field; an option with no entry in
// optionLabelKeys, or whose key is missing from the bundle, shows its id.
function _selectOptionLabel(f, option) {
  const k = f.optionLabelKeys && f.optionLabelKeys[option];
  if (!k) return option;
  const v = t(k);
  return (v && v !== k) ? v : option;
}

// Hint line under a settings field that carries a hintKey; empty when the
// field has none or the bundle lacks the key. The line takes the full row width
// so it wraps under the control at phone width.
function _fieldHintHTML(f) {
  if (!f.hintKey) return '';
  const v = t(f.hintKey);
  if (!v || v === f.hintKey) return '';
  return `<div style="flex-basis:100%;font-size:10px;color:var(--text2);margin-top:4px;">${escHtml(v)}</div>`;
}

function loadGeneralConfig() {
  // Settings-tab federation pass (2026-10-08): all three were raw,
  // non-proxy-aware fetch()es with a silently-swallowed failure.
  Promise.all([
    apiFetch('/api/config'),
    apiFetch('/api/llms').catch(() => null),
    apiFetch('/api/interfaces').catch(() => [])
  ]).then(([cfg, backendsData, interfaces]) => {
      if (!cfg) return;
      state._interfaces = interfaces || [];
      const enabledBackends = (backendsData?.llms || []).filter(b => !b.disabled).map(b => b.name);
      for (const sec of GENERAL_CONFIG_FIELDS) {
        const el = document.getElementById('gcfg_' + sec.id);
        if (!el) continue;
        let html = '';
        for (const f of sec.fields) {
          const parts = (f.key || '').split('.');
          const val = parts.reduce((o, k) => (o && o[k] !== undefined) ? o[k] : '', cfg);
          // Resolve label at render time so t() runs after locale loads.
          // GENERAL_CONFIG_FIELDS is a static const (init-time), so any t()
          // calls baked into f.label ran before the bundle was fetched and
          // returned the raw key as a truthy string. A labelKey property
          // defers the lookup here where the bundle is ready.
          // When t() can't find a key it returns the key itself (truthy) so
          // the naive (t(k) || fallback) idiom doesn't work — check for
          // t() returning the key unchanged and fall back to f.label instead.
          const _tl = f.labelKey ? t(f.labelKey) : null;
          const fLabel = (_tl && _tl !== f.labelKey) ? _tl : f.label;
          if (f.type === 'group') {
            // Sub-heading row inside a card. Optional hintKey adds a one-line note.
            const _ghint = f.hintKey ? t(f.hintKey) : '';
            html += `<div style="margin:14px 0 6px;padding-top:10px;border-top:1px solid var(--border);">
              <div style="font-weight:700;font-size:12px;color:var(--text);">${escHtml(fLabel)}</div>
              ${_ghint && _ghint !== f.hintKey ? `<div style="font-size:10px;color:var(--text2);margin-top:2px;">${escHtml(_ghint)}</div>` : ''}
            </div>`;
          } else if (f.type === 'llm_select') {
            const opts = enabledBackends.map(n =>
              `<option value="${escHtml(n)}" ${String(val) === n ? 'selected' : ''}>${escHtml(n)}</option>`
            ).join('');
            html += `<div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <select class="form-select general-cfg-input" onchange="saveGeneralField('${f.key}', this.value)">${opts}</select>
            </div>`;
          } else if (f.type === 'toggle') {
            const checked = !!val;
            html += `<div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <label class="toggle-switch">
                <input type="checkbox" ${checked ? 'checked' : ''} onchange="saveGeneralField('${f.key}', this.checked)" />
                <span class="toggle-slider"></span>
              </label>
            </div>`;
          } else if (f.type === 'dir_browse') {
            const fid = 'cfg_dir_' + f.key.replace(/\./g, '_');
            const browserId = fid + '_browser';
            html += `<div class="settings-row" style="flex-direction:column;align-items:stretch;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <div style="display:flex;gap:6px;align-items:center;margin-top:4px;">
                <input type="text" id="${fid}" class="form-input general-cfg-input" value="${escHtml(String(val || ''))}"
                  style="flex:1;" onchange="saveGeneralField('${f.key}', this.value)" />
                <button class="btn-secondary" style="font-size:11px;white-space:nowrap;" onclick="toggleSettingsDirBrowser('${fid}','${browserId}','${f.key}')">Browse</button>
              </div>
              <div id="${browserId}" class="dir-browser" style="display:none;margin-top:4px;"></div>
            </div>`;
          } else if (f.type === 'interface_select') {
            // Multi-select for network interfaces — current value may be comma-separated
            const currentVals = String(val || '0.0.0.0').split(',').map(s => s.trim());
            const ifaces = (interfaces && interfaces.length > 0) ? interfaces : [
              { addr: '0.0.0.0', label: '0.0.0.0 (all interfaces)' },
              { addr: '127.0.0.1', label: '127.0.0.1 (localhost)' },
            ];
            // Detect which interface the browser is connected through
            const connIf = typeof _resolveConnectedInterface === 'function' ? _resolveConnectedInterface() : null;
            const checkboxes = ifaces.map(iface => {
              const checked = currentVals.includes(iface.addr);
              const isConnected = connIf && iface.addr === connIf.addr;
              let badge = '';
              if (f.key === 'server.host' && isConnected) {
                badge = ' <span style="color:var(--success);font-size:10px;">(connected)</span>';
              }
              return `<label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer;padding:3px 0;">
                <input type="checkbox" ${checked ? 'checked' : ''} value="${escHtml(iface.addr)}"
                  onchange="saveInterfaceField('${f.key}', this.closest('.iface-list'), this)" />
                <span style="font-family:monospace;color:var(--text);">${escHtml(iface.label)}${badge}</span>
              </label>`;
            }).join('');
            html += `<div class="settings-row" style="flex-direction:column;align-items:stretch;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <div class="iface-list" style="display:flex;flex-direction:column;gap:2px;margin-top:4px;padding:8px 10px;background:var(--bg);border:1px solid var(--border);border-radius:6px;">
                ${checkboxes}
              </div>
            </div>`;
          } else if (f.type === 'select') {
            const selVal = String(val);
            const opts = (f.options || []).map(o =>
              `<option value="${escHtml(o)}" ${selVal === o || (selVal === '' && f.default !== undefined && String(f.default) === o) ? 'selected' : ''}>${escHtml(_selectOptionLabel(f, o))}</option>`
            ).join('');
            const _selHint = _fieldHintHTML(f);
            html += `<div class="settings-row" style="justify-content:space-between;${_selHint ? 'flex-wrap:wrap;' : ''}">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <select class="form-select general-cfg-input" onchange="saveGeneralField('${f.key}', this.value)">${opts}</select>
              ${_selHint}
            </div>`;
          } else if (f.type === 'button') {
            // v5.19.0 — operator-reported regression: the whisper.test_button
            // (BL289 v5.4.0) rendered as <input type="button"> empty box
            // because loadGeneralConfig fell through to the generic else.
            // Now mirrors the loadCommsConfig button branch.
            html += `<div class="settings-row" style="justify-content:space-between;align-items:center;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <button class="btn-secondary" style="font-size:12px;" onclick="(window['${escHtml(f.action || '')}']||function(){showToast('Action ${escHtml(f.action || '')} not wired','error',2000);})()">Run</button>
            </div>`;
          } else if (f.type === 'llm_backend') {
            // v5.26.16 — same dynamic-dropdown pattern as the New PRD
            // modal: enabled+available backends only, shell excluded.
            // The paired model field below subscribes to changes here.
            const inputId = 'gcfg-llmbk-' + f.key.replace(/\W+/g,'-');
            const modelSelector = f.pairedModelKey ? `'gcfg-llmbk-${f.pairedModelKey.replace(/\W+/g,'-')}-wrap'` : "''";
            const modelInner = f.pairedModelKey ? `'gcfg-llmbk-${f.pairedModelKey.replace(/\W+/g,'-')}-inner'` : "''";
            const opts = ['<option value="">(inherit)</option>'];
            (state._prdBackends || enabledBackends.map(n => ({name:n, disabled:false}))).forEach(b => {
              const name = (typeof b === 'string') ? b : (b && b.name);
              if (!name) return;
              if (NON_LLM_BACKENDS.has(name)) return;
              if (typeof b !== 'string' && b.disabled === true) return;
              opts.push(`<option value="${escHtml(name)}" ${String(val) === name ? 'selected' : ''}>${escHtml(name)}</option>`);
            });
            if (val && !opts.some(o => o.includes(`value="${escHtml(String(val))}"`))) {
              opts.push(`<option value="${escHtml(String(val))}" selected>${escHtml(String(val))} (not configured)</option>`);
            }
            const backendCurrent = JSON.stringify(String(val || ''));
            const onchange = `saveGeneralField('${f.key}', this.value); refreshLLMModelField(${modelSelector}, ${modelInner}, '${inputId}', '');`;
            html += `<div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <select id="${inputId}" class="form-select general-cfg-input" onchange="${onchange}">${opts.join('')}</select>
            </div>`;
          } else if (f.type === 'llm_model') {
            // v5.26.16 — paired model dropdown. Reads from
            // state._availableModels keyed by the sibling backend's
            // value. Hidden when no models known for the backend.
            const wrapId = 'gcfg-llmbk-' + f.key.replace(/\W+/g,'-') + '-wrap';
            const innerId = 'gcfg-llmbk-' + f.key.replace(/\W+/g,'-') + '-inner';
            const backendInputId = f.backendKey ? ('gcfg-llmbk-' + f.backendKey.replace(/\W+/g,'-')) : '';
            const onchange = `saveGeneralField('${f.key}', (this.querySelector('select,input')||{value:''}).value)`;
            html += `<div id="${wrapId}" class="settings-row" style="justify-content:space-between;display:none;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <div id="${innerId}" onchange="${onchange}" style="flex:0 0 200px;"></div>
            </div>`;
            // Defer the populate to after the DOM is in place; ensureLLMModelLists then refreshLLMModelField.
            setTimeout(() => {
              ensureLLMModelLists().then(() => refreshLLMModelField(wrapId, innerId, backendInputId, String(val || '')));
            }, 0);
          } else if (f.type === 'llm_summarizer') {
            // Special LLM select for the summarizer — populated from /api/llms
            // filtered to inference-capable kinds (ollama, openai, openai-api).
            const summarizerId = 'gcfg-summarizer-llm';
            const noLLMsLabel = t('session_summarizer_no_llms') || 'No Ollama/OpenAI LLMs configured';
            const currentVal = String(val || '');
            html += `<div class="settings-row" style="justify-content:space-between;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <select id="${summarizerId}" class="form-select general-cfg-input" onchange="saveGeneralField('${f.key}', this.value); if(window._refreshSummarizerModelSelect) window._refreshSummarizerModelSelect(); if(window._testSummarizerLLM) window._testSummarizerLLM();">
                <option value="">(${t('disabled') || 'disabled'})</option>
              </select>
            </div>
            <div id="sum-test-status" style="display:none;font-size:11px;margin-top:4px;padding:4px 8px;border-radius:4px;"></div>`;
            setTimeout(() => {
              apiFetch('/api/llms').then(d => {
                const el = document.getElementById(summarizerId);
                if (!el) return;
                const llms = (d && d.llms) ? d.llms : [];
                const filtered = llms.filter(l => !l.disabled && !l.tombstoned &&
                  (l.kind === 'ollama' || l.kind === 'openai' || l.kind === 'openai-api'));
                if (filtered.length === 0) {
                  el.innerHTML = `<option value="">${escHtml(noLLMsLabel)}</option>`;
                  return;
                }
                let opts = `<option value="">(${t('disabled') || 'disabled'})</option>`;
                filtered.forEach(l => {
                  const sel = l.name === currentVal ? ' selected' : '';
                  opts += `<option value="${escHtml(l.name)}"${sel}>${escHtml(l.name + ' (' + l.kind + ')')}</option>`;
                });
                el.innerHTML = opts;
                if (window._refreshSummarizerModelSelect) window._refreshSummarizerModelSelect();
              }).catch(() => {});
            }, 0);
          } else if (f.type === 'summarizer_model') {
            // Model override for the summarizer. Hidden until an LLM ref is selected.
            // Uses a text input + datalist so operators can type any model name (including
            // compute-node models not in the local Ollama list) while still getting
            // discovery hints for locally-available models.
            const wrapId = 'sum-model-wrap';
            const listId = 'sum-model-datalist';
            const inputId = 'sum-model-input';
            const savedModel = String(val || '');
            html += `<div id="${wrapId}" class="settings-row" style="justify-content:space-between;display:none;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <div style="flex:0 0 200px;display:flex;flex-direction:column;gap:2px;">
                <input id="${inputId}" list="${listId}" class="form-input" style="font-size:12px;width:100%;"
                  value="${escHtml(savedModel)}" placeholder="(backend default)"
                  onchange="saveGeneralField('${f.key}', this.value); if(window._testSummarizerLLM) window._testSummarizerLLM();" />
                <datalist id="${listId}"></datalist>
                <div id="sum-model-hint" style="font-size:10px;color:var(--text2);"></div>
              </div>
            </div>`;
            setTimeout(() => {
              window._refreshSummarizerModelSelect = function() {
                const wrap = document.getElementById(wrapId);
                if (!wrap) return;
                const llmSel = document.getElementById('gcfg-summarizer-llm');
                const llmRef = llmSel ? llmSel.value : '';
                if (!llmRef) { wrap.style.display = 'none'; return; }
                wrap.style.display = '';
                // Fetch from local Ollama AND all registered compute nodes, then merge.
                const fetchAllOllamaModels = () => {
                  const toNames = d => {
                    const arr = d && Array.isArray(d.models) ? d.models : Array.isArray(d) ? d : [];
                    return arr.map(m => m.name || m).filter(Boolean);
                  };
                  return Promise.all([
                    fetch('/api/ollama/models', { headers: tokenHeader() }).then(r => r.ok ? r.json() : null).catch(() => null),
                    fetch('/api/compute/nodes', { headers: tokenHeader() }).then(r => r.ok ? r.json() : null).catch(() => null),
                  ]).then(([local, cnResp]) => {
                    const seen = new Set();
                    const merged = [];
                    const add = names => names.forEach(n => { if (!seen.has(n)) { seen.add(n); merged.push(n); } });
                    add(toNames(local));
                    const nodes = cnResp && Array.isArray(cnResp.nodes) ? cnResp.nodes : [];
                    return Promise.all(
                      nodes.filter(n => n.kind === 'ollama' && n.name).map(n =>
                        fetch(`/api/ollama/models?node=${encodeURIComponent(n.name)}`, { headers: tokenHeader() })
                          .then(r => r.ok ? r.json() : null).catch(() => null).then(toNames)
                      )
                    ).then(nodeModels => { nodeModels.forEach(add); return merged; });
                  });
                };
                fetchAllOllamaModels()
                  .then(models => {
                    const dl = document.getElementById(listId);
                    if (dl) {
                      dl.innerHTML = models.map(m => {
                        const hint = summarizerModelHint(m);
                        return `<option value="${escHtml(m)}">${escHtml(hint ? m + ' — ' + hint : m)}</option>`;
                      }).join('');
                    }
                    // Update hint label for the currently typed/saved value.
                    const inp = document.getElementById(inputId);
                    const hintEl = document.getElementById('sum-model-hint');
                    if (inp && hintEl) {
                      const h = summarizerModelHint(inp.value);
                      hintEl.textContent = h || (inp.value ? '' : 'Type a model name or pick from suggestions');
                      inp.addEventListener('input', () => {
                        hintEl.textContent = summarizerModelHint(inp.value) || '';
                      }, { once: false });
                    }
                  });
              };
              window._refreshSummarizerModelSelect();
              // Health-check function: POST /api/summarizer/test and show ✓/✗ status.
              window._testSummarizerLLM = function() {
                const llmSel = document.getElementById('gcfg-summarizer-llm');
                if (!llmSel || !llmSel.value) return; // disabled — no test needed
                const statusEl = document.getElementById('sum-test-status');
                if (!statusEl) return;
                statusEl.style.display = '';
                statusEl.style.background = 'var(--bg3,#1f2937)';
                statusEl.style.color = 'var(--text2)';
                statusEl.textContent = '⏳ Testing LLM…';
                apiFetch('/api/summarizer/test', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
                  .then(d => {
                    if (d && d.ok) {
                      statusEl.style.background = 'rgba(34,197,94,0.12)';
                      statusEl.style.color = '#22c55e';
                      statusEl.textContent = `✓ LLM responding (${d.latency_ms} ms)`;
                    } else {
                      statusEl.style.background = 'rgba(239,68,68,0.12)';
                      statusEl.style.color = '#ef4444';
                      statusEl.textContent = `✗ ${(d && d.error) || 'LLM not responding'}`;
                    }
                  })
                  .catch(e => {
                    statusEl.style.background = 'rgba(239,68,68,0.12)';
                    statusEl.style.color = '#ef4444';
                    statusEl.textContent = `✗ ${e.message || 'request failed'}`;
                  });
              };
            }, 0);
          } else if (f.type === 'failure_escalation_steps') {
            // The config GET returns the steps as a JSON array; the field edits
            // the compact text form, which the server parses on save.
            const _hint = f.hintKey ? t(f.hintKey) : '';
            html += `<div class="settings-row" style="flex-direction:column;align-items:stretch;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <input type="text" class="form-input general-cfg-input" value="${escHtml(_failureEscalationStepsText(val))}"
                ${f.placeholder ? 'placeholder="' + escHtml(f.placeholder) + '"' : ''}
                onchange="saveGeneralField('${f.key}', this.value)" />
              ${_hint && _hint !== f.hintKey ? `<div style="font-size:10px;color:var(--text2);margin-top:4px;">${escHtml(_hint)}</div>` : ''}
            </div>`;
          } else if (f.type === 'textarea') {
            html += `<div class="settings-row" style="flex-direction:column;align-items:stretch;">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <textarea class="form-input general-cfg-input" rows="4" style="margin-top:4px;resize:vertical;font-size:11px;"
                onchange="saveGeneralField('${f.key}', this.value)">${escHtml(String(val || ''))}</textarea>
            </div>`;
          } else {
            const defVal = (val !== '' && val !== undefined) ? String(val) : (f.default !== undefined ? String(f.default) : '');
            const _inHint = _fieldHintHTML(f);
            html += `<div class="settings-row" style="justify-content:space-between;${_inHint ? 'flex-wrap:wrap;' : ''}">
              <div class="settings-label">${escHtml(fLabel)}</div>
              <input type="${f.type}" class="form-input general-cfg-input" value="${escHtml(defVal)}"
                ${f.placeholder ? 'placeholder="' + escHtml(f.placeholder) + '"' : ''}
                ${f.min !== undefined ? 'min="' + f.min + '"' : ''}
                ${f.max !== undefined ? 'max="' + f.max + '"' : ''}
                ${f.step !== undefined ? 'step="' + f.step + '"' : ''}
                onchange="saveGeneralField('${f.key}', ${f.type === 'number' ? 'Number(this.value)' : 'this.value'})" />
              ${_inHint}
            </div>`;
          }
        }
        // PWA-only preferences appended to the dw section. Stored in
        // localStorage; not in the YAML config (per-browser choice).
        if (sec.id === 'dw') {
          const linksOn = localStorage.getItem('cs_show_docs_links') !== '0';
          html += `<div class="settings-row" style="justify-content:space-between;">
            <div class="settings-label">Show inline doc links</div>
            <label class="toggle-switch">
              <input type="checkbox" ${linksOn ? 'checked' : ''} onchange="toggleDocsLinksPref(this.checked)" />
              <span class="toggle-slider"></span>
            </label>
          </div>`;
        }
        el.innerHTML = html;
      }
    })
    .catch(e => {
      const msg = _fedMsg(e, null);
      if (!msg) return; // a local failure here was already silent before this pass -- preserve that
      for (const sec of GENERAL_CONFIG_FIELDS) {
        const el = document.getElementById('gcfg_' + sec.id);
        if (el) el.innerHTML = `<span style="color:var(--error);font-size:12px;">${escHtml(msg)}</span>`;
      }
    });
}

window.toggleDocsLinksPref = function(on) {
  localStorage.setItem('cs_show_docs_links', on ? '1' : '0');
  // Re-render Settings so the inline links appear/disappear immediately.
  if (state.activeView === 'settings') renderSettingsView();
};

function _resolveConnectedInterface() {
  const browserHost = location.hostname;
  const ifaces = state._interfaces || [];
  // Match hostname to interface: direct IP match, label match, name match, or Tailscale MagicDNS
  return ifaces.find(i =>
    i.addr === browserHost ||
    i.label?.includes(browserHost) ||
    i.name === browserHost ||
    (browserHost.match(/^[a-zA-Z]/) && i.name?.includes('tailscale') && !['0.0.0.0','127.0.0.1'].includes(i.addr))
  ) || null;
}

function saveInterfaceField(key, listEl, changedEl) {
  const allBoxes = Array.from(listEl.querySelectorAll('input[type="checkbox"]'));
  const allBox = allBoxes.find(cb => cb.value === '0.0.0.0');
  const localhostBox = allBoxes.find(cb => cb.value === '127.0.0.1');
  const otherBoxes = allBoxes.filter(cb => cb.value !== '0.0.0.0');

  const connIface = _resolveConnectedInterface();
  const connectedIP = connIface?.addr || null;
  const browserHost = location.hostname;

  _dbg('IFACE', `save key=${key} changed=${changedEl?.value} checked=${changedEl?.checked} browser=${browserHost} connIP=${connectedIP}`);

  // Rule 1: Selecting "all" deselects everything else
  if (changedEl?.value === '0.0.0.0' && changedEl.checked) {
    otherBoxes.forEach(cb => { cb.checked = false; });
    _dbg('IFACE', 'All selected → unchecked others');
  }
  // Rule 2: Selecting any specific deselects "all", forces localhost on
  else if (changedEl?.value !== '0.0.0.0' && changedEl?.checked && allBox) {
    allBox.checked = false;
    // Force localhost always available when switching from all to specific
    if (localhostBox && !localhostBox.checked) {
      localhostBox.checked = true;
      _dbg('IFACE', 'Forced localhost on (always required for specific binding)');
    }
    _dbg('IFACE', `Specific ${changedEl.value} selected → unchecked all, ensured localhost`);
  }
  // Rule 3: Unchecking localhost when not on all — block it
  else if (changedEl?.value === '127.0.0.1' && !changedEl.checked && !(allBox?.checked)) {
    changedEl.checked = true;
    showToast('Localhost must remain enabled when binding to specific interfaces', 'warning', 3000);
    _dbg('IFACE', 'Blocked localhost uncheck — required for specific binding');
    return;
  }

  const finalChecked = allBoxes.filter(cb => cb.checked).map(cb => cb.value);
  _dbg('IFACE', `finalChecked=${JSON.stringify(finalChecked)}`);

  if (finalChecked.length === 0) {
    showToast('Select at least one interface', 'warning', 2000);
    if (allBox) allBox.checked = true;
    return;
  }

  // For web server: warn if connected interface is not covered
  if (key === 'server.host') {
    const isAllSelected = finalChecked.includes('0.0.0.0');
    const isConnectedSelected = connectedIP && finalChecked.includes(connectedIP);
    const isLocalhostSelected = finalChecked.includes('127.0.0.1');
    const isOnLocalhost = browserHost === 'localhost' || browserHost === '127.0.0.1';
    _dbg('IFACE', `safety: isAll=${isAllSelected} isConn=${isConnectedSelected} isLH=${isLocalhostSelected} isOnLH=${isOnLocalhost}`);

    if (!isAllSelected && !isConnectedSelected && !(isOnLocalhost && isLocalhostSelected)) {
      showToast(`Warning: your connection (${browserHost}${connectedIP ? ' → ' + connectedIP : ''}) is not selected. You may lose access after restart.`, 'warning', 5000);
    }
  }

  const val = finalChecked.join(',');
  fetch('/api/config', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify({ [key]: val }),
  }).then(r => {
    if (r.ok) {
      showToast('Saved: ' + val + '. Restart required.', 'success', 3000);
      const hint = document.getElementById('restartHint');
      if (hint) hint.style.display = 'inline';
      if (state.autoRestartOnConfig) triggerAutoRestart();
      setTimeout(() => loadGeneralConfig(), 1000);
    } else {
      r.text().then(t => { _dbg('IFACE', `save failed: ${r.status} ${t}`); });
      showToast('Save failed', 'error');
    }
  }).catch(e => { _dbg('IFACE', `save error: ${e}`); showToast('Save failed', 'error'); });
}

// Returns a quality/speed hint string for a model name based on parameter count.
// Used in the summarizer model dropdown to help operators pick the right model.
function summarizerModelHint(modelName) {
  const m = (modelName || '').toLowerCase();
  if (/[:\-_]1(\.[0-9])?b/.test(m))                return '⚡ basic / very fast';
  if (/[:\-_]3b/.test(m))                           return '⚡ light / fast';
  if (/[:\-_](7b|8b)/.test(m))                      return '★ good / fast';
  if (/[:\-_](10b|11b|12b|13b|14b)/.test(m))        return '★★ very good / medium';
  if (/[:\-_](20b|24b|27b|30b|32b)/.test(m))        return '★★★ excellent / slower';
  if (/[:\-_](70b|72b|90b)/.test(m))                return '★★★ best / slow';
  return '';
}

// Fields that require a daemon restart to take effect
const RESTART_FIELDS = new Set([
  'pin_check_seconds', // pin keepers are started once at daemon boot
  'server.host', 'server.port', 'server.tls', 'server.tls_auto_generate', 'server.tls_cert', 'server.tls_key',
  'acme.enabled', 'acme.endpoint', 'acme.domains', 'acme.method', 'acme.dns01.provider', 'acme.dns01.token_secret', 'acme.dns01.zone_id', // BL397 — Manager starts/stops only at daemon boot
  'mcp.enabled', 'mcp.sse_enabled', 'mcp.sse_host', 'mcp.sse_port', 'mcp.public_url', 'mcp.tls_enabled',
  'dns_channel.enabled', 'dns_channel.listen', 'dns_channel.domain',
]);

// ── Failure escalation: policy codec, override editor and held-task review ──
// The server stores a step ladder as a JSON array; the operator edits the
// compact text form backend:model[@attempts], comma separated. A "-" item is a
// step on the normally resolved worker. The parser below mirrors the server's
// so a value typed here reads back as the same policy.

// _failureEscalationStepsText renders a steps array in the compact text form.
// Effort has no text form and is not shown.
function _failureEscalationStepsText(steps) {
  if (!Array.isArray(steps)) return '';
  return steps.map(s => {
    let item = s && s.backend ? s.backend + ':' + (s.model || '') : '-';
    if (s && s.attempts > 0) item += '@' + s.attempts;
    return item;
  }).join(',');
}

// _parseFailureEscalationSteps reads the compact text form into a steps array.
// Empty text yields []. It throws on an item the server would refuse.
function _parseFailureEscalationSteps(text) {
  const src = String(text || '').trim();
  if (!src) return [];
  return src.split(',').map((raw, i) => {
    let item = raw.trim();
    if (!item) throw new Error('step ' + (i + 1) + ' is empty');
    let attempts = 0;
    const at = item.lastIndexOf('@');
    if (at >= 0) {
      const n = Number(item.slice(at + 1));
      if (!Number.isInteger(n) || n < 1) throw new Error('step ' + (i + 1) + ' has an invalid @attempts suffix');
      attempts = n;
      item = item.slice(0, at).trim();
    }
    const step = {};
    if (item !== '-') {
      const colon = item.indexOf(':');
      if (colon < 0) throw new Error('step ' + (i + 1) + ' needs the form backend:model, or - for the normal worker');
      step.backend = item.slice(0, colon).trim();
      if (!step.backend) throw new Error('step ' + (i + 1) + ' has no backend');
      const model = item.slice(colon + 1).trim();
      if (model) step.model = model;
    }
    if (attempts) step.attempts = attempts;
    return step;
  });
}

// _fmtDurationSeconds renders an attempt or review duration as 45s or 3m 5s.
function _fmtDurationSeconds(s) {
  const n = Math.max(0, Math.round(Number(s) || 0));
  if (n < 60) return n + 's';
  return Math.floor(n / 60) + 'm ' + (n % 60) + 's';
}

// _prdHeldTaskCount counts the tasks of an Automaton held for operator review.
// A summary row carries only the task_status_counts map, so it is read from there.
function _prdHeldTaskCount(prd) {
  const stories = prd.stories || prd.Story || [];
  if (!stories.length) return (prd.task_status_counts || {}).review_needed || 0;
  let n = 0;
  stories.forEach(st => (st.tasks || st.Tasks || []).forEach(tk => {
    if ((tk.status || tk.Status) === 'review_needed') n++;
  }));
  return n;
}

// _prdHeldBadgeHTML is the held-task badge for an Automaton header or list row.
// It is empty when no task is held.
function _prdHeldBadgeHTML(prd) {
  const n = _prdHeldTaskCount(prd);
  if (!n) return '';
  return `<span class="prd-held-badge" title="${escHtml(t('review_held_help'))}">&#9873; ${escHtml(n)} ${escHtml(t('review_held_badge'))}</span>`;
}

// _findPRDTask returns the cached Automaton's task with taskID, or null.
function _findPRDTask(prdID, taskID) {
  const prd = _automataDetailPRD;
  if (!prd || prd.id !== prdID) return null;
  let found = null;
  (prd.stories || prd.Story || []).forEach(st => (st.tasks || st.Tasks || []).forEach(tk => {
    if (!found && tk.id === taskID) found = tk;
  }));
  return found;
}

// _failureEscalationScope names the form fields of one override editor. The
// Automaton has the scope "prd"; a task has "task-<id>" with unsafe characters
// replaced, so the id is safe to use in an element id.
function _failureEscalationScope(taskID) {
  return taskID ? 'task-' + String(taskID).replace(/[^A-Za-z0-9_-]/g, '_') : 'prd';
}

// _failureEscalationEditorHTML draws the override editor for the Automaton
// (taskID empty) or one task. policy is the stored override, if any; an empty
// field inherits the next level up.
function _failureEscalationEditorHTML(prdID, taskID, policy) {
  const scope = _failureEscalationScope(taskID);
  const p = policy || {};
  const enabledVal = p.enabled === true ? 'on' : p.enabled === false ? 'off' : '';
  const opt = (v, label) => `<option value="${v}" ${enabledVal === v ? 'selected' : ''}>${escHtml(label)}</option>`;
  const pid = escHtml(JSON.stringify(prdID || ''));
  const tid = escHtml(JSON.stringify(taskID || ''));
  return `<div class="prd-fe-editor" style="margin-top:8px;padding-top:8px;border-top:1px dashed var(--border,#333);">
    <div style="font-size:11px;font-weight:600;color:var(--text2);">${escHtml(t('review_override_title'))}</div>
    <div style="font-size:10px;color:var(--text2);margin-bottom:4px;">${escHtml(t('review_override_hint'))}</div>
    <div style="display:flex;flex-wrap:wrap;gap:8px;align-items:flex-end;">
      <label style="font-size:11px;color:var(--text2);">${escHtml(t('review_override_enabled'))}<br>
        <select id="feEnabled-${scope}" class="form-input" style="font-size:12px;width:auto;">${opt('', t('review_override_inherit'))}${opt('on', t('review_override_on'))}${opt('off', t('review_override_off'))}</select></label>
      <label style="font-size:11px;color:var(--text2);">${escHtml(t('review_override_max_failures'))}<br>
        <input id="feMax-${scope}" type="number" min="1" step="1" class="form-input" style="width:90px;font-size:12px;" value="${p.max_failures ? escHtml(String(p.max_failures)) : ''}" /></label>
      <label style="font-size:11px;color:var(--text2);flex:1;min-width:220px;">${escHtml(t('review_override_steps'))}<br>
        <input id="feSteps-${scope}" type="text" class="form-input" style="font-size:12px;width:100%;" value="${escHtml(_failureEscalationStepsText(p.steps))}" placeholder="${escHtml('ollama:qwen3.8:27b@2,claude-code:claude-sonnet-5-5')}" /></label>
    </div>
    <div style="display:flex;gap:6px;margin-top:6px;">
      <button type="button" class="btn-secondary" onclick="event.stopPropagation();prdSaveFailureEscalation(${pid},${tid},'${scope}',false)">${escHtml(t('review_override_save'))}</button>
      <button type="button" class="btn-secondary" onclick="event.stopPropagation();prdSaveFailureEscalation(${pid},${tid},'${scope}',true)">${escHtml(t('review_override_clear'))}</button>
    </div>
  </div>`;
}

// _readFailureEscalationPolicy builds the policy from one editor. Empty fields
// are left out, so an editor with nothing set reads as null (clear).
function _readFailureEscalationPolicy(scope) {
  const field = name => {
    const el = document.getElementById(name + '-' + scope);
    return el ? String(el.value || '').trim() : '';
  };
  const policy = {};
  const enabled = field('feEnabled');
  if (enabled === 'on') policy.enabled = true;
  else if (enabled === 'off') policy.enabled = false;
  const max = field('feMax');
  if (max !== '') {
    const n = Number(max);
    if (!Number.isInteger(n) || n < 1) throw new Error('max_failures');
    policy.max_failures = n;
  }
  const steps = field('feSteps');
  if (steps !== '') policy.steps = _parseFailureEscalationSteps(steps);
  return Object.keys(policy).length ? policy : null;
}

// setFailureEscalationPolicy posts the override for the Automaton (taskID
// empty) or one task. A null policy clears it.
function setFailureEscalationPolicy(prdID, taskID, policy) {
  return apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/set_failure_escalation', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ task_id: taskID || '', policy: policy, actor: 'operator' }),
  });
}

// prdSaveFailureEscalation saves one override editor, or clears it.
function prdSaveFailureEscalation(prdID, taskID, scope, clear) {
  let policy = null;
  if (!clear) {
    try { policy = _readFailureEscalationPolicy(scope); } catch (e) {
      showToast(t('review_override_invalid'), 'error', 3000);
      return Promise.resolve(null);
    }
  }
  return setFailureEscalationPolicy(prdID, taskID, policy)
    .then(() => { showToast(t('review_override_saved'), 'success', 1500); _refreshAutomataOrPRD(); })
    .catch(err => showToast(String(err), 'error', 3000));
}
window.prdSaveFailureEscalation = prdSaveFailureEscalation;

// prdResolveTaskReview posts an operator decision on a task held for review.
// review is {action, ...} with the fields the chosen action carries.
function prdResolveTaskReview(prdID, taskID, review) {
  const body = Object.assign({ task_id: taskID, actor: 'operator' }, review);
  return apiFetch('/api/autonomous/prds/' + encodeURIComponent(prdID) + '/resolve_task_review', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
    .then(() => { showToast(t('review_done'), 'success', 1500); _refreshAutomataOrPRD(); })
    .catch(err => showToast(t('review_failed') + ': ' + String(err), 'error', 3000));
}
window.prdResolveTaskReview = prdResolveTaskReview;

// prdReviewRetry sends a held task back to its normally resolved worker.
function prdReviewRetry(prdID, taskID) {
  return prdResolveTaskReview(prdID, taskID, { action: 'retry' });
}

// prdReviewCancel cancels a held task after the operator confirms.
function prdReviewCancel(prdID, taskID) {
  if (!confirm(t('review_cancel_confirm'))) return Promise.resolve();
  return prdResolveTaskReview(prdID, taskID, { action: 'cancel' });
}
window.prdReviewRetry = prdReviewRetry;
window.prdReviewCancel = prdReviewCancel;

// _prdReviewBody builds the retry body for one of the three retry forms. A
// field the form does not change is left out, so the server keeps it.
function _prdReviewBody(mode, v) {
  const body = { action: 'retry' };
  if (mode === 'spec') body.spec = v.spec || '';
  if (mode === 'worker') {
    if (v.backend) body.backend = v.backend;
    if (v.model) body.model = v.model;
    if (v.effort) body.effort = v.effort;
  }
  if (mode === 'scope') body.files = (v.files || '').split(/[\n,]/).map(s => s.trim()).filter(Boolean);
  if (v.note) body.note = v.note;
  return body;
}

// openPRDTaskReviewModal opens the form for one retry mode: spec, worker or
// scope. The form is prefilled from the cached Automaton's task.
function openPRDTaskReviewModal(prdID, taskID, mode) {
  const task = _findPRDTask(prdID, taskID) || {};
  const titleKey = { spec: 'review_action_edit_retry', worker: 'review_action_change_worker', scope: 'review_action_narrow_scope' }[mode];
  const head = `<div class="response-modal-header">
      <strong>${escHtml(t(titleKey))} · ${escHtml(taskID)}</strong>
      <button class="btn-icon" onclick="_prdCloseModal()" title="${t('btn_close') || 'Close'}">&#10005;</button>
    </div>`;
  const note = `<label style="font-size:11px;color:var(--text2);">${escHtml(t('review_form_note'))}
      <input id="prdReviewNote" type="text" class="form-input" style="width:100%;" /></label>`;
  const actions = `<div style="display:flex;gap:6px;justify-content:flex-end;">
      <button type="button" class="btn-secondary" onclick="_prdCloseModal()">${t('btn_cancel') || 'Cancel'}</button>
      <button type="submit" class="btn-secondary" style="background:var(--accent2);color:#fff;">${escHtml(t('review_form_retry_submit'))}</button>
    </div>`;
  const val = id => { const el = document.getElementById(id); return el ? String(el.value || '') : ''; };
  const submit = fields => () => {
    const body = _prdReviewBody(mode, Object.assign({ note: val('prdReviewNote').trim() }, fields()));
    if ((mode === 'spec' && !body.spec.trim()) || (mode === 'scope' && !(body.files || []).length)) {
      showToast(t('review_failed'), 'error', 3000);
      return;
    }
    _prdCloseModal();
    return prdResolveTaskReview(prdID, taskID, body);
  };
  if (mode === 'worker') {
    ensureLLMModelLists().then(() => {
      _prdMountModal(`${head}
        <form id="prdModalForm" class="response-modal-body" style="display:flex;flex-direction:column;gap:8px;">
          <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;">
            <div><label style="font-size:11px;color:var(--text2);">${escHtml(t('prd_new_backend_label'))}</label>${renderBackendSelect('prdReviewBackend', task.backend || '', `refreshLLMModelField('prdReviewModelWrap','prdReviewModelInner','prdReviewBackend','')`)}</div>
            <div><label style="font-size:11px;color:var(--text2);">${escHtml(t('prd_new_effort_label'))}</label>${renderEffortSelect('prdReviewEffort', String(task.effort || ''), '')}</div>
            <div id="prdReviewModelWrap" style="display:none;"><label style="font-size:11px;color:var(--text2);">${escHtml(t('prd_new_model_label'))}</label><div id="prdReviewModelInner"></div></div>
          </div>
          ${note}
          ${actions}
        </form>`, submit(() => {
        const modelEl = document.getElementById('prdReviewModelInner')?.querySelector('input,select');
        return { backend: val('prdReviewBackend'), model: modelEl ? modelEl.value.trim() : '', effort: val('prdReviewEffort') };
      }));
      refreshLLMModelField('prdReviewModelWrap', 'prdReviewModelInner', 'prdReviewBackend', task.model || '');
    });
    return;
  }
  const field = mode === 'spec'
    ? `<label style="font-size:11px;color:var(--text2);">${escHtml(t('review_form_spec'))}
         <textarea id="prdReviewSpec" class="form-input" rows="6" style="resize:vertical;width:100%;">${escHtml(task.spec || '')}</textarea></label>`
    : `<label style="font-size:11px;color:var(--text2);">${escHtml(t('review_form_files'))}
         <textarea id="prdReviewFiles" class="form-input" rows="6" style="resize:vertical;width:100%;">${escHtml((task.files || []).join('\n'))}</textarea></label>`;
  _prdMountModal(`${head}
    <form id="prdModalForm" class="response-modal-body" style="display:flex;flex-direction:column;gap:8px;">
      ${field}
      ${note}
      ${actions}
    </form>`, submit(() => (mode === 'spec' ? { spec: val('prdReviewSpec') } : { files: val('prdReviewFiles') })));
}
window.openPRDTaskReviewModal = openPRDTaskReviewModal;

// _taskAttemptsHTML draws the per-attempt summary of a task: the worker, the
// time spent, the outcome, the files changed and the verifier report, plus the
// review report text when the task is held.
function _taskAttemptsHTML(task) {
  const attempts = Array.isArray(task.attempts) ? task.attempts : [];
  const summary = task.review_summary || null;
  if (!attempts.length && !summary) return '';
  const total = summary && summary.total_seconds
    ? summary.total_seconds
    : attempts.reduce((n, a) => n + (a.duration_seconds || 0), 0);
  const rows = attempts.map(a => {
    const worker = a.backend ? a.backend + (a.model ? ' / ' + a.model : '') : '—';
    const esc = a.escalated ? ` <span class="prd-task-llm-badge">${escHtml(t('review_attempt_escalated'))}</span>` : '';
    const files = (a.changed_files || []).map(f => `<li><code>${escHtml(f)}</code></li>`).join('');
    const issues = (a.verifier_issues || []).map(i => `<li>${escHtml(i)}</li>`).join('');
    const verifier = a.verifier_summary || issues
      ? `<div>${escHtml(t('review_attempt_verifier'))}: ${escHtml(a.verifier_summary || '')}</div>${issues ? `<ul>${issues}</ul>` : ''}`
      : '';
    return `<div class="prd-task-attempt" style="margin-top:6px;">
      <div><strong>#${escHtml(String(a.number || ''))}</strong> ${escHtml(worker)}${esc}
        <span style="color:var(--text2);font-size:11px;"> · ${escHtml(_fmtDurationSeconds(a.duration_seconds))}</span></div>
      <div style="font-size:11px;color:var(--text2);">${escHtml(t('review_attempt_outcome'))}: ${escHtml(a.outcome || '—')}${a.failure_category ? ' (' + escHtml(a.failure_category) + ')' : ''}</div>
      ${a.failure_summary ? `<div style="font-size:11px;">${escHtml(a.failure_summary)}</div>` : ''}
      ${files ? `<div style="font-size:11px;">${escHtml(t('review_attempt_files'))}:</div><ul class="prd-task-attempt-files">${files}</ul>` : ''}
      ${verifier ? `<div style="font-size:11px;">${verifier}</div>` : ''}
    </div>`;
  }).join('');
  const body = rows || `<em style="color:var(--text2);font-size:11px;">${escHtml(t('review_attempt_none'))}</em>`;
  const report = summary && summary.text
    ? `<details style="margin-top:6px;"><summary style="cursor:pointer;font-size:11px;">${escHtml(t('review_report_title'))}</summary><pre style="white-space:pre-wrap;font-size:11px;">${escHtml(summary.text)}</pre></details>`
    : '';
  return `<details class="prd-task-attempts" style="margin-top:6px;">
    <summary style="cursor:pointer;font-size:11px;font-weight:600;color:var(--text2);">${escHtml(t('review_attempts_title'))} (${attempts.length}) · ${escHtml(t('review_attempts_total'))}: ${escHtml(_fmtDurationSeconds(total))}</summary>
    ${body}${report}
  </details>`;
}

// _taskReviewPanelHTML is the expanded body for a task's review state: the
// operator actions when the task is held, the attempt summary, and the task's
// own failure escalation override.
function _taskReviewPanelHTML(prd, task) {
  const pid = escHtml(JSON.stringify(prd.id || ''));
  const tid = escHtml(JSON.stringify(task.id || ''));
  const actions = task.status === 'review_needed'
    ? `<div class="prd-task-review-actions" onclick="event.stopPropagation()" style="display:flex;flex-wrap:wrap;gap:6px;margin:6px 0;">
        <button class="prd-task-retry-btn" onclick="event.stopPropagation();prdReviewRetry(${pid},${tid})">&#8635; ${escHtml(t('review_action_retry'))}</button>
        <button class="prd-task-retry-btn" onclick="event.stopPropagation();openPRDTaskReviewModal(${pid},${tid},'spec')">${escHtml(t('review_action_edit_retry'))}</button>
        <button class="prd-task-retry-btn" onclick="event.stopPropagation();openPRDTaskReviewModal(${pid},${tid},'worker')">${escHtml(t('review_action_change_worker'))}</button>
        <button class="prd-task-retry-btn" onclick="event.stopPropagation();openPRDTaskReviewModal(${pid},${tid},'scope')">${escHtml(t('review_action_narrow_scope'))}</button>
        <button class="prd-task-cancel-btn" onclick="event.stopPropagation();prdReviewCancel(${pid},${tid})">${escHtml(t('review_action_cancel'))}</button>
      </div>`
    : '';
  return actions + _taskAttemptsHTML(task) + _failureEscalationEditorHTML(prd.id, task.id, task.failure_escalation);
}

function saveGeneralField(key, value) {
  fetch('/api/config', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify({ [key]: value }),
  })
    .then(r => {
      if (r.ok) {
        showToast('Saved', 'success', 1500);
        // Update cached state for settings that affect UI behavior
        if (key === 'server.suppress_active_toasts') state.suppressActiveToasts = !!value;
        if (key === 'server.auto_restart_on_config') state.autoRestartOnConfig = !!value;
        if (key === 'session.summarizer.enabled') state._summarizerEnabled = !!value;
        // Show restart hint if this field requires a restart
        if (RESTART_FIELDS.has(key)) {
          const hint = document.getElementById('restartHint');
          if (hint) hint.style.display = 'inline';
        }
        // Auto-restart if configured
        if (state.autoRestartOnConfig && RESTART_FIELDS.has(key)) {
          triggerAutoRestart();
        }
      } else {
        showToast('Save failed', 'error');
      }
    })
    .catch(() => showToast('Save failed', 'error'));
}

// plan tier inflight caps — collects the four per-tier inputs into a
// JSON object and PUTs it as autonomous.plan_tier_max_inflight (the
// daemon accepts object, JSON-string, or compact "tier=N,tier=N" forms;
// unknown tiers are rejected with an actionable error).
function savePlanTierTable() {
  const table = {};
  document.querySelectorAll('input[data-plan-tier]').forEach(inp => {
    let v = parseInt(inp.value || '0', 10) || 0;
    if (v < 0) v = 0;
    table[inp.dataset.planTier] = v;
  });
  fetch('/api/config', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify({ 'autonomous.plan_tier_max_inflight': table }),
  })
    .then(r => {
      if (r.ok) {
        showToast('Saved', 'success', 1500);
        loadCommsConfig();
      } else {
        showToast('Save failed', 'error');
      }
    })
    .catch(() => showToast('Save failed', 'error'));
}

// plan tier allocation — collects the per-tier dollar inputs into a JSON
// object and PUTs it as autonomous.plan_tier_allocation_usd (a blank tier
// is 0, meaning not declared).
function savePlanTierAllocationTable() {
  const table = {};
  document.querySelectorAll('input[data-plan-tier-allocation]').forEach(inp => {
    let v = parseFloat(inp.value || '0') || 0;
    if (v < 0) v = 0;
    table[inp.dataset.planTierAllocation] = v;
  });
  fetch('/api/config', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify({ 'autonomous.plan_tier_allocation_usd': table }),
  })
    .then(r => {
      if (r.ok) {
        showToast('Saved', 'success', 1500);
        loadCommsConfig();
      } else {
        showToast('Save failed', 'error');
      }
    })
    .catch(() => showToast('Save failed', 'error'));
}

function triggerAutoRestart() {
  // Check if encrypted without env password — warn instead of restarting
  apiFetch('/api/health').then(data => {
    if (data.encrypted && !data.has_env_password) {
      showToast('Restart skipped: encrypted config requires DATAWATCH_SECURE_PASSWORD env variable for auto-restart', 'warning', 6000);
      return;
    }
    setTimeout(() => {
      showToast('Restarting daemon to apply changes…', 'info', 3000);
      restartDaemon();
    }, 500);
  }).catch(() => {
    // Can't check — restart anyway
    setTimeout(() => {
      showToast('Restarting daemon to apply changes…', 'info', 3000);
      restartDaemon();
    }, 500);
  });
}

function toggleSettingsDirBrowser(inputId, browserId, cfgKey) {
  const browser = document.getElementById(browserId);
  if (!browser) return;
  if (browser.style.display !== 'none') {
    browser.style.display = 'none';
    return;
  }
  browser.style.display = 'block';
  const input = document.getElementById(inputId);
  const startPath = (input && input.value) ? input.value : '~';
  loadSettingsDirContents(startPath, inputId, browserId, cfgKey);
}

function loadSettingsDirContents(path, inputId, browserId, cfgKey) {
  const browser = document.getElementById(browserId);
  if (!browser) return;
  browser.innerHTML = loadingEyeBlock();
  fetch('/api/files?path=' + encodeURIComponent(path || '~'), { headers: tokenHeader() })
    .then(r => r.json())
    .then(data => {
      const currentPath = data.path || path;
      const entries = (data.entries || []).filter(e => e.is_dir).map(e =>
        `<div class="dir-entry" data-path="${escHtml(e.path)}">
          <span class="dir-icon">${e.is_link ? '🔗' : (e.name === '..' ? '⬆' : '📁')}</span>
          <span>${escHtml(e.name)}</span>
        </div>`
      ).join('');
      browser.innerHTML = `<div class="dir-current">${escHtml(currentPath)}</div>` +
        `<button class="btn-secondary dir-select-btn" data-select="${escHtml(currentPath)}">&#10003; Use This Folder</button>` +
        (entries || '<div style="color:var(--text2);padding:8px;font-size:12px;">No subdirectories</div>');
      browser.onclick = function(ev) {
        const entry = ev.target.closest('.dir-entry');
        const selBtn = ev.target.closest('[data-select]');
        if (entry && entry.dataset.path) {
          loadSettingsDirContents(entry.dataset.path, inputId, browserId, cfgKey);
        } else if (selBtn && selBtn.dataset.select) {
          const input = document.getElementById(inputId);
          if (input) input.value = selBtn.dataset.select;
          saveGeneralField(cfgKey, selBtn.dataset.select);
          browser.style.display = 'none';
          showToast('Directory set', 'success', 1500);
        }
      };
    })
    .catch(() => {
      browser.innerHTML = '<div class="dir-error">Cannot read directory</div>';
    });
}

// v5.26.56 — Operator-asked: "the test whisper i expected it would
// open a dialog with a mic button to test, not just backend test."
// Replaces the old silent-WAV health check (kept under the hood as
// a fallback) with an interactive recording dialog. Operator clicks
// 🎤 → speaks → transcript appears in the dialog. Fails closed
// (forces whisper.enabled=false) only when no transcript at all
// comes back from a non-empty recording.
function testWhisperBackend() {
  const overlay = document.createElement('div');
  overlay.id = 'whisperTestOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:1000;display:flex;align-items:center;justify-content:center;padding:16px;';
  overlay.innerHTML = `
    <div style="background:var(--bg);border:1px solid var(--border);border-radius:10px;padding:18px;max-width:480px;width:100%;display:flex;flex-direction:column;gap:12px;">
      <div style="display:flex;align-items:center;justify-content:space-between;">
        <strong style="font-size:14px;">Test transcription</strong>
        <button class="btn-icon" onclick="document.getElementById('whisperTestOverlay').remove()" title="Close">&#10005;</button>
      </div>
      <div style="font-size:12px;color:var(--text2);">
        Click 🎤 to start recording, click again to stop. The transcribed text appears below.
        Verifies the configured Whisper backend end-to-end (mic → /api/voice/transcribe → text).
      </div>
      <div style="display:flex;gap:8px;align-items:center;">
        <button id="whisperTestMicBtn" class="btn-secondary" style="font-size:24px;width:64px;height:64px;border-radius:50%;" onclick="_whisperTestToggle(this)" title="Click to start / stop">&#127908;</button>
        <div id="whisperTestStatus" style="font-size:12px;color:var(--text2);">idle</div>
      </div>
      <textarea id="whisperTestTranscript" class="form-input" rows="4" placeholder="(transcript will appear here)" style="resize:vertical;font-family:inherit;" readonly></textarea>
      <div style="display:flex;gap:6px;justify-content:flex-end;">
        <button class="btn-secondary" onclick="testWhisperBackendQuick()">Run silent-WAV health check</button>
        <button class="btn-secondary" onclick="document.getElementById('whisperTestOverlay').remove()">Done</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
}
window.testWhisperBackend = testWhisperBackend;

// Reuses the same recorder + /api/voice/transcribe path as the
// inline mic buttons. Writes into the readonly textarea inside the
// modal.
window._whisperTestToggle = async function(btn) {
  const status = document.getElementById('whisperTestStatus');
  const target = document.getElementById('whisperTestTranscript');
  if (!target || !status) return;
  if (state.voice && state.voice.recorder && state.voice.recorder.state === 'recording' &&
      state.voice._genericTarget === 'whisperTestTranscript') {
    state.voice.recorder.stop();
    status.textContent = 'transcribing…';
    return;
  }
  if (!navigator.mediaDevices || typeof MediaRecorder === 'undefined') {
    status.textContent = 'browser does not support MediaRecorder';
    return;
  }
  let stream;
  try { stream = await navigator.mediaDevices.getUserMedia({ audio: true }); }
  catch (err) { status.textContent = 'mic permission denied'; return; }
  let mime = '';
  for (const cand of ['audio/webm;codecs=opus', 'audio/webm', 'audio/ogg;codecs=opus', 'audio/mp4']) {
    if (MediaRecorder.isTypeSupported && MediaRecorder.isTypeSupported(cand)) { mime = cand; break; }
  }
  const rec = new MediaRecorder(stream, mime ? { mimeType: mime } : undefined);
  state.voice = { recorder: rec, chunks: [], _genericTarget: 'whisperTestTranscript' };
  rec.ondataavailable = e => { if (e.data && e.data.size > 0) state.voice.chunks.push(e.data); };
  rec.onstop = async () => {
    stream.getTracks().forEach(t => t.stop());
    btn.classList.remove('recording');
    btn.innerHTML = '&#127908;';
    const blob = new Blob(state.voice.chunks, { type: mime || 'audio/webm' });
    state.voice = { recorder: null, chunks: [], sessionId: null };
    if (blob.size === 0) { status.textContent = 'no audio captured'; return; }
    try {
      const ext = mime.includes('mp4') ? '.m4a' : mime.includes('ogg') ? '.ogg' : '.webm';
      const showTranscript = (transcript, ms) => {
        target.value = transcript || '(empty transcript — backend returned no text)';
        const timing = ms === null ? '' : `${ms}ms, `;
        status.textContent = transcript
          ? `ok (${timing}${transcript.length} chars)`
          : 'transcribed empty — backend may be misconfigured';
      };
      const t0 = performance.now();
      const result = await _voiceTranscribeBlob(blob, { filename: 'voice' + ext, targetId: 'whisperTestTranscript' });
      if (!result.ok) {
        // One status line can only describe one failure; a newer test
        // supersedes an earlier failed test recording.
        document.querySelectorAll('#whisperTestOverlay .voice-failure-notice-inline').forEach((old) => {
          _voiceDiscardFailed(Number(old.id.replace('voiceFailureNotice_', '')));
          old.remove();
        });
        _voiceShowFailure(result, {
          statusEl: status,
          place: (el) => status.insertAdjacentElement('afterend', el),
          onTranscript: (text) => showTranscript(text, null),
        });
        return;
      }
      showTranscript(result.transcript, Math.round(performance.now() - t0));
      // Don't auto-disable whisper here — the operator opened this
      // dialog deliberately. They can disable manually if it really
      // is broken.
    } catch (err) {
      status.textContent = 'transcribe error: ' + err.message;
    }
  };
  btn.classList.add('recording');
  btn.innerHTML = '&#9632;';
  status.textContent = t('voice_recording_status')||'recording — click again to stop';
  rec.start();
};

// The pre-v5.26.56 silent-WAV health check, kept reachable for
// quick "does the backend respond at all" verification. Differs
// from the new flow: doesn't need a real microphone, doesn't
// produce a transcript, but does fail-disable on error.
window.testWhisperBackendQuick = function() {
  showToast('Testing transcription endpoint…', 'info', 1500);
  apiFetch('/api/voice/test', { method: 'POST' })
    .then(data => {
      if (data && data.ok) {
        showToast('Voice backend OK (' + (data.latency_ms || 0) + 'ms)', 'success', 3000);
      } else {
        showToast('Voice backend failed: ' + ((data && data.error) || 'unknown'), 'error', 6000);
        saveGeneralField('whisper.enabled', false);
      }
    })
    .catch(err => {
      showToast('Voice backend failed: ' + String(err), 'error', 6000);
      saveGeneralField('whisper.enabled', false);
    });
};

// localFetch always targets the local daemon regardless of which remote
// server is selected in the server picker. Used for update/restart operations
// that must act on the local node only.
function localFetch(path, opts = {}) {
  const token = localStorage.getItem('cs_token') || '';
  const headers = Object.assign({ 'Content-Type': 'application/json' }, opts.headers || {});
  if (token) headers['Authorization'] = 'Bearer ' + token;
  return fetch(path, Object.assign({}, opts, { headers }))
    .then(r => r.ok ? r.json() : r.text().then(t => Promise.reject(new Error(t || r.statusText))));
}

function checkForUpdate() {
  const el = document.getElementById('aboutUpdate');
  if (el) el.innerHTML = `<span style="color:var(--text2);font-size:12px;">${t('settings_checking')||'Checking…'}</span>`;
  // Always check the LOCAL daemon — update/restart ops must not route through
  // the remote-server proxy even when a remote node is selected in the picker.
  localFetch('/api/update/check')
    .then(data => {
      if (!data) { if (el) el.innerHTML = `<span style="color:var(--error);">${t('settings_check_failed')||'Check failed'}</span>`; return; }
      const current = data.current_version || '';
      const latest = data.latest_version || '';
      if (!el) return;
      if (data.status === 'update_available') {
        el.innerHTML = `<span style="color:var(--warning,#f59e0b);font-size:12px;">Update available: v${latest} (current: v${current})</span>` +
          ` <button class="btn-secondary" style="font-size:11px;margin-left:6px;" onclick="runUpdate()">Update</button>`;
      } else {
        el.innerHTML = '<span style="color:var(--success,#22c55e);font-size:12px;">Up to date (v' + current + ')</span>';
      }
    })
    .catch(() => { if (el) el.innerHTML = '<span style="color:var(--error);">Check failed</span>'; });
}

function runUpdate() {
  const el = document.getElementById('aboutUpdate');
  if (el) el.innerHTML = '<span style="color:var(--text2);font-size:12px;">Downloading update… daemon will restart automatically.</span>';
  localFetch('/api/update', { method: 'POST' })
    .then(data => {
      if (data.status === 'up_to_date') {
        if (el) el.innerHTML = '<span style="color:var(--success,#22c55e);font-size:12px;">Already up to date (v' + (data.version || '') + ')</span>';
      } else {
        showToast('Installing v' + (data.version || 'latest') + '… daemon will restart.', 'info', 8000);
      }
    })
    .catch(err => {
      if (el) el.innerHTML = '<span style="color:var(--error);font-size:12px;">Update failed: ' + err.message + '</span>';
    });
}

// ── Config / Backend Status ────────────────────────────────────────────────────

function tokenHeader() {
  const t = localStorage.getItem('cs_token') || '';
  return t ? { 'Authorization': 'Bearer ' + t } : {};
}

// BL302 S1/S2 — MCP Resources panel helpers.
// S2 update: resources are grouped by category with count per category.

// Category definitions for BL302 S2 categorized resource panel.
var _mcpResourceCategories = [
  {key: 'system',  label: 'System',           prefixes: ['datawatch://version','datawatch://config','datawatch://channel/info']},
  {key: 'docs',    label: 'Docs',             prefixes: ['datawatch://docs']},
  {key: 'sessions',label: 'Sessions',         prefixes: ['datawatch://sessions']},
  {key: 'stats',   label: 'Stats & Alerts',   prefixes: ['datawatch://stats','datawatch://alerts']},
  {key: 'memory',  label: 'Memory',           prefixes: ['datawatch://memory']},
  {key: 'automata',label: 'Automata',         prefixes: ['datawatch://automata']},
  {key: 'council', label: 'Council',          prefixes: ['datawatch://council']},
  {key: 'kg',      label: 'Knowledge Graph',  prefixes: ['datawatch://kg']},
];

function _mcpCategoryForURI(uri) {
  for (var i = 0; i < _mcpResourceCategories.length; i++) {
    var cat = _mcpResourceCategories[i];
    for (var j = 0; j < cat.prefixes.length; j++) {
      if (uri === cat.prefixes[j] || uri.startsWith(cat.prefixes[j] + '/') || uri.startsWith(cat.prefixes[j] + '{')) {
        return cat;
      }
    }
  }
  return {key: 'other', label: 'Other'};
}

function loadMCPResources() {
  const listEl = document.getElementById('mcpResourcesList');
  const tmplEl = document.getElementById('mcpTemplatesList');
  if (listEl) listEl.innerHTML = loadingEyeBlock();
  if (tmplEl) tmplEl.innerHTML = '';
  fetch('/api/mcp/resources', {headers: tokenHeader()})
    .then(r => r.json())
    .then(d => {
      const resources = d.resources || [];
      if (!listEl) return;
      if (resources.length === 0) {
        listEl.innerHTML = '<span style="color:var(--text2)">' + (window._t && window._t('mcp.resources.empty') || 'No resources registered') + '</span>';
        return;
      }
      // Group resources by category (BL302 S2).
      const byCategory = {};
      resources.forEach(function(r) {
        const cat = _mcpCategoryForURI(r.uri);
        if (!byCategory[cat.key]) byCategory[cat.key] = {label: cat.label, items: []};
        byCategory[cat.key].items.push(r);
      });
      let html = '';
      _mcpResourceCategories.forEach(function(cat) {
        if (!byCategory[cat.key]) return;
        const group = byCategory[cat.key];
        html += '<div style="margin-bottom:6px;">';
        html += '<div style="font-size:10px;font-weight:600;color:var(--text2);margin-bottom:2px;">' +
          escHtml(group.label) +
          ' <span style="color:var(--accent2);font-weight:400;">(' + group.items.length + ')</span></div>';
        html += group.items.map(function(r) {
          return '<div style="margin:2px 0 2px 8px;display:flex;align-items:center;gap:6px;">' +
            '<code style="color:var(--accent2);font-size:10px;">' + escHtml(r.uri) + '</code>' +
            '<span style="color:var(--text2);font-size:10px;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escHtml(r.description||'') + '</span>' +
            '<button onclick="readMCPResource('+JSON.stringify(r.uri)+')" style="background:var(--bg);border:1px solid var(--border);padding:2px 6px;border-radius:3px;cursor:pointer;font-size:10px;flex-shrink:0;">' +
            (window._t && window._t('mcp.resources.read') || 'Read') + '</button></div>';
        }).join('');
        html += '</div>';
      });
      // Anything in "other" category.
      if (byCategory['other']) {
        const group = byCategory['other'];
        html += '<div style="margin-bottom:6px;"><div style="font-size:10px;font-weight:600;color:var(--text2);margin-bottom:2px;">Other (' + group.items.length + ')</div>';
        html += group.items.map(function(r) {
          return '<div style="margin:2px 0 2px 8px;display:flex;align-items:center;gap:6px;">' +
            '<code style="color:var(--accent2);font-size:10px;">' + escHtml(r.uri) + '</code>' +
            '<span style="color:var(--text2);font-size:10px;flex:1;">' + escHtml(r.description||'') + '</span>' +
            '<button onclick="readMCPResource('+JSON.stringify(r.uri)+')" style="background:var(--bg);border:1px solid var(--border);padding:2px 6px;border-radius:3px;cursor:pointer;font-size:10px;flex-shrink:0;">' +
            (window._t && window._t('mcp.resources.read') || 'Read') + '</button></div>';
        }).join('');
        html += '</div>';
      }
      listEl.innerHTML = html;
    })
    .catch(e => { if (listEl) listEl.innerHTML = '<span style="color:var(--error)">' + escHtml(String(e)) + '</span>'; });
  fetch('/api/mcp/resources/templates', {headers: tokenHeader()})
    .then(r => r.json())
    .then(d => {
      const templates = d.templates || [];
      if (!tmplEl) return;
      if (templates.length === 0) { tmplEl.innerHTML = ''; return; }
      tmplEl.innerHTML = templates.map(t =>
        '<div style="margin:2px 0;color:var(--text2);font-size:10px;">' +
        '<code style="color:var(--accent);">' + escHtml(t.uri_template) + '</code>' +
        ' — ' + escHtml(t.description||'') + '</div>'
      ).join('');
    })
    .catch(() => {});
}

function readMCPResource(uri) {
  const contentEl = document.getElementById('mcpResourceContent');
  const labelEl = document.getElementById('mcpResourceContentLabel');
  const bodyEl = document.getElementById('mcpResourceContentBody');
  if (!contentEl || !labelEl || !bodyEl) return;
  contentEl.style.display = 'block';
  labelEl.textContent = uri;
  bodyEl.innerHTML = loadingEyeBlock();
  fetch('/api/mcp/resources/read?uri=' + encodeURIComponent(uri), {headers: tokenHeader()})
    .then(r => r.json())
    .then(d => {
      const contents = d.contents || [];
      if (contents.length > 0) {
        bodyEl.textContent = contents[0].text || JSON.stringify(d, null, 2);
      } else {
        bodyEl.textContent = JSON.stringify(d, null, 2);
      }
    })
    .catch(e => { bodyEl.textContent = String(e); });
}

// BL302 S3 — MCP Sampling log panel (read-only, last 50 entries, auto-refresh 30s).
var _mcpSamplingRefreshTimer = null;
function loadMCPSamplingLog() {
  const listEl = document.getElementById('mcpSamplingList');
  if (!listEl) return;
  listEl.innerHTML = loadingEyeBlock();
  // The sampling log is embedded in the datawatch://stats/mcp resource.
  fetch('/api/mcp/resources/read?uri=' + encodeURIComponent('datawatch://stats/mcp'), {headers: tokenHeader()})
    .then(function(r) { return r.json(); })
    .then(function(d) {
      const contents = d.contents || [];
      if (!contents.length) {
        listEl.innerHTML = '<span style="color:var(--text2);font-size:11px;">' +
          (window._t && window._t('mcp.sampling.empty') || 'No sampling requests recorded') + '</span>';
        return;
      }
      let data = {};
      try { data = JSON.parse(contents[0].text || '{}'); } catch(e) {}
      const log = data.sampling_log || [];
      if (!log.length) {
        listEl.innerHTML = '<span style="color:var(--text2);font-size:11px;">' +
          (window._t && window._t('mcp.sampling.empty') || 'No sampling requests recorded') + '</span>';
        return;
      }
      // Reverse to show newest first.
      const rows = log.slice().reverse().map(function(e) {
        const ts = e.timestamp ? new Date(e.timestamp).toLocaleTimeString() : '';
        const trigger = escHtml(e.trigger || '');
        const preview = escHtml((e.request_preview || '').slice(0, 80));
        const result = escHtml((e.content || e.error || '').slice(0, 80));
        const latency = e.latency_ms != null ? e.latency_ms + 'ms' : '';
        const errStyle = e.error ? 'color:var(--error);' : '';
        return '<div style="margin:3px 0;padding:4px 6px;background:var(--bg);border-radius:4px;font-size:10px;' + errStyle + '">' +
          '<span style="color:var(--text2);margin-right:6px;">' + ts + '</span>' +
          '<span style="font-weight:600;color:var(--accent2);margin-right:6px;">' + trigger + '</span>' +
          '<span style="color:var(--text2);margin-right:4px;">' + (window._t && window._t('mcp.sampling.latency') || 'latency') + ':' + latency + '</span>' +
          '<div style="margin-top:2px;color:var(--text);">' + preview + '</div>' +
          (result ? '<div style="margin-top:1px;color:var(--text2);">→ ' + result + '</div>' : '') +
          '</div>';
      });
      listEl.innerHTML = rows.join('');
    })
    .catch(function(e) {
      if (listEl) listEl.innerHTML = '<span style="color:var(--error);font-size:11px;">' + escHtml(String(e)) + '</span>';
    });
  // Schedule next refresh.
  if (_mcpSamplingRefreshTimer) clearTimeout(_mcpSamplingRefreshTimer);
  _mcpSamplingRefreshTimer = setTimeout(function() { loadMCPSamplingLog(); }, 30000);
}

// BL302 S4 — MCP Prompts panel: list + get + copy-to-clipboard.
function loadMCPPrompts() {
  var listEl = document.getElementById('mcpPromptsList');
  if (!listEl) return;
  listEl.innerHTML = loadingEyeBlock();
  fetch('/api/mcp/prompts', {headers: tokenHeader()})
    .then(function(r) { return r.json(); })
    .then(function(d) {
      var prompts = d.prompts || [];
      if (!prompts.length) {
        listEl.innerHTML = '<span style="color:var(--text2);font-size:11px;">' +
          (window._t && window._t('mcp.prompts.empty') || 'No prompts registered') + '</span>';
        return;
      }
      var rows = prompts.map(function(p) {
        var argHtml = '';
        if (p.arguments && p.arguments.length) {
          var inputs = p.arguments.map(function(a) {
            return '<label style="font-size:10px;color:var(--text2);display:flex;align-items:center;gap:4px;margin-top:3px;">' +
              escHtml(a.name) + (a.required ? '*' : '') + ': ' +
              '<input type="text" data-arg="' + escHtml(a.name) + '" placeholder="' + escHtml(a.description || '') + '" ' +
              'style="flex:1;background:var(--bg);color:var(--text);border:1px solid var(--border);border-radius:3px;padding:2px 4px;font-size:10px;" /></label>';
          }).join('');
          argHtml = '<div class="mcp-prompt-args" style="margin-top:4px;">' + inputs + '</div>';
        }
        var safeId = escHtml(p.name).replace(/[^a-zA-Z0-9-]/g, '_');
        return '<div id="mcp-prompt-' + safeId + '" style="margin:4px 0;padding:6px 8px;background:var(--bg);border-radius:4px;">' +
          '<div style="display:flex;align-items:center;gap:6px;">' +
          '<span style="font-weight:600;font-size:11px;color:var(--accent2);">' + escHtml(p.name) + '</span>' +
          '<span style="font-size:10px;color:var(--text2);flex:1;">' + escHtml(p.description || '') + '</span>' +
          '<button onclick="getMCPPrompt(\'' + escHtml(p.name) + '\', this)" ' +
          'style="background:var(--accent2);color:#fff;border:none;padding:2px 8px;border-radius:3px;cursor:pointer;font-size:10px;">' +
          (window._t && window._t('mcp.prompts.get') || 'Get') + '</button>' +
          '</div>' + argHtml + '</div>';
      });
      listEl.innerHTML = rows.join('');
    })
    .catch(function(e) {
      if (listEl) listEl.innerHTML = '<span style="color:var(--error);font-size:11px;">' + escHtml(String(e)) + '</span>';
    });
}

function getMCPPrompt(name, btn) {
  // Collect args from sibling inputs in the same prompt row.
  var row = btn.closest ? btn.closest('[id^="mcp-prompt-"]') : btn.parentNode;
  var args = {};
  if (row) {
    var inputs = row.querySelectorAll ? row.querySelectorAll('[data-arg]') : [];
    for (var i = 0; i < inputs.length; i++) {
      var val = inputs[i].value;
      if (val) args[inputs[i].getAttribute('data-arg')] = val;
    }
  }
  var resultEl = document.getElementById('mcpPromptResult');
  var labelEl = document.getElementById('mcpPromptResultLabel');
  var bodyEl = document.getElementById('mcpPromptResultBody');
  if (resultEl) resultEl.style.display = 'none';
  fetch('/api/mcp/prompts/get', {
    method: 'POST',
    headers: Object.assign({'Content-Type': 'application/json'}, tokenHeader()),
    body: JSON.stringify({name: name, arguments: args})
  })
    .then(function(r) { return r.json(); })
    .then(function(d) {
      if (!resultEl || !bodyEl) return;
      resultEl.style.display = '';
      if (labelEl) labelEl.textContent = (window._t && window._t('mcp.prompts.name') || 'Prompt') + ': ' + name;
      if (d.error) {
        bodyEl.textContent = 'Error: ' + d.error;
        return;
      }
      var text = (d.messages || []).map(function(m) {
        return '[' + m.role + ']\n' + m.content;
      }).join('\n\n---\n\n');
      bodyEl.textContent = text;
    })
    .catch(function(e) {
      if (resultEl) resultEl.style.display = '';
      if (bodyEl) bodyEl.textContent = String(e);
    });
}

function copyMCPPromptResult() {
  var bodyEl = document.getElementById('mcpPromptResultBody');
  if (!bodyEl) return;
  var text = bodyEl.textContent || '';
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(function() {
      showToast((window._t && window._t('mcp.prompts.copy') || 'Copy') + ' ✔', 'success', 1500);
    });
  } else {
    var ta = document.createElement('textarea');
    ta.value = text;
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    showToast((window._t && window._t('mcp.prompts.copy') || 'Copy') + ' ✔', 'success', 1500);
  }
}

// Detect whether a backend has been configured (has any non-empty credential/url field)
function isBackendConfigured(svc, s) {
  const credFields = {
    telegram: ['token'], discord: ['token'], slack: ['token'],
    matrix: ['access_token'], ntfy: ['topic'], email: ['host', 'username'],
    twilio: ['account_sid', 'from_number'], github_webhook: ['secret'],
    webhook: ['addr'], dns_channel: ['domain', 'secret'],
    imap_mcp: ['url'],
  };
  const fields = credFields[svc] || [];
  if (fields.length === 0) return true; // always considered configured
  return fields.some(f => s[f] && s[f] !== '' && s[f] !== '***');
}

function loadConfigStatus() {
  const el = document.getElementById('configStatus');
  if (!el) return;
  // Settings-tab federation pass (2026-10-08): raw fetch -- never
  // reflected a selected remote server's own comm-backend config.
  apiFetch('/api/config')
    .then(cfg => {
      const services = ['telegram', 'discord', 'slack', 'matrix', 'ntfy', 'email', 'twilio', 'github_webhook', 'webhook', 'dns_channel', 'imap_mcp'];
      el.innerHTML = services.map(svc => {
        const s = cfg[svc] || {};
        const on = s.enabled;
        const configured = isBackendConfigured(svc, s);
        const label = svc.replace(/_/g, ' ');
        if (!configured) {
          return `<div class="settings-row backend-row" style="justify-content:space-between;">
            <div class="settings-label backend-label" style="text-transform:capitalize;">${escHtml(label)}</div>
            <span style="font-size:11px;color:var(--text2);">not configured</span>
            <button class="btn-secondary backend-btn" onclick="openBackendSetup('${svc}')" title="Configure">⚙ Configure</button>
          </div>`;
        }
        return `<div class="settings-row backend-row" style="justify-content:space-between;">
          <div class="settings-label backend-label" style="text-transform:capitalize;flex:1;">${escHtml(label)}</div>
          <div style="display:flex;align-items:center;gap:8px;">
            <button class="btn-icon" style="font-size:12px;opacity:0.6;" onclick="openBackendSetup('${svc}')" title="Edit configuration">✎</button>
            <label class="toggle-switch" title="${on ? 'Enabled — click to disable' : 'Disabled — click to enable'}">
              <input type="checkbox" ${on ? 'checked' : ''} onchange="toggleBackend('${svc}', this.checked)" />
              <span class="toggle-slider"></span>
            </label>
          </div>
        </div>`;
      }).join('') + `<div style="font-size:11px;color:var(--text2);padding:8px 12px;">
        <span id="backendRestartHint" style="display:none;color:var(--warning);">Restart required to apply changes.
          <button class="btn-link" style="font-size:11px;" onclick="confirmRestartDaemon()">Restart now</button>
        </span>
      </div>`;
    })
    .catch(e => { const el2 = document.getElementById('configStatus'); if (el2) el2.textContent = _fedMsg(e, t('state_config_unavailable') || 'Config unavailable'); });
}

function toggleBackend(service, enable) {
  fetch('/api/config', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify({ [service + '.enabled']: enable }),
  })
    .then(r => {
      if (r.ok) {
        const label = service.replace(/_/g, ' ');
        showToast(label + (enable ? ' enabled' : ' disabled'), 'success', 2000);
        loadConfigStatus();
        const hint = document.getElementById('backendRestartHint');
        if (hint) hint.style.display = 'inline';
        if (state.autoRestartOnConfig) triggerAutoRestart();
      } else showToast('Save failed', 'error');
    })
    .catch(() => showToast('Save failed', 'error'));
}

