  const isObj = typeof nm === 'object';
  const text = isObj ? String(nm.readable || '') : String(nm);
  const short = isObj
    ? (nm.short_id ? String(nm.short_id) : (nm.id ? String(nm.id).slice(0, 8) : String(rawId || '').slice(0, 8)))
    : String(rawId || '').slice(0, 8);
