  const nameText = task.readable
    || ((task.prd_title || task.task_title) ? [task.prd_title, task.task_title].filter(Boolean).join(' / ') : '');
  const name = nameText
    ? ` ${window.capacityNameHtml(nameText, task.short_id || task.id || task.task_id || '')}`
    : '';
