function loadAlertRuleFirings() {
  const el = document.getElementById('alertRuleFiringsList');
  if (!el) return;
  // Settings-tab federation pass (2026-10-08): was raw, non-proxy-aware.
  apiFetch('/api/alert-rules/firings')
    .then(data => {
      const firings = (data && Array.isArray(data.firings)) ? data.firings : [];
      if (firings.length === 0) {
        el.innerHTML = `<div style="color:var(--text2);font-size:13px;">${escHtml(t('alert_rules_no_firings')||'No firings yet.')}</div>`;
        return;
      }
      el.innerHTML = firings.slice(0, 20).map(f => {
        const when = f.fired_at ? new Date(f.fired_at).toLocaleString('en-GB', { hour12: false }) : '';
        return `<div style="padding:4px 0;border-bottom:1px solid var(--border);font-size:11px;display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
          <strong>${escHtml(f.rule_name||'')}</strong>
          <span style="color:var(--text2);">${escHtml(f.source||'')} = ${escHtml(String(f.value!=null?f.value:''))}</span>
          <span style="color:var(--text2);margin-left:auto;">${escHtml(when)}</span>
        </div>`;
      }).join('');
    })
    .catch(e => { el.innerHTML = `<div style="color:var(--error);font-size:13px;">${escHtml(_fedMsg(e, t('alert_rules_firings_failed')||'Failed to load recent firings.'))}</div>`; });
}

function toggleAlertRule(name, enable) {
  const action = enable ? 'enable' : 'disable';
  fetch('/api/alert-rules/' + encodeURIComponent(name) + '/' + action, {
    method: 'POST',
    headers: tokenHeader(),
  })
    .then(r => r.ok ? loadAlertRules() : showToast('Toggle failed', 'error'))
    .catch(() => showToast('Toggle failed', 'error'));
}

function deleteAlertRule(name) {
  fetch('/api/alert-rules/' + encodeURIComponent(name), {
    method: 'DELETE',
    headers: tokenHeader(),
  })
    .then(r => r.ok ? loadAlertRules() : showToast('Delete failed', 'error'))
    .catch(() => showToast('Delete failed', 'error'));
}

function createAlertRule() {
  const name = (document.getElementById('newAlertRuleName') || {}).value || '';
  const description = (document.getElementById('newAlertRuleDesc') || {}).value || '';
  const metric = (document.getElementById('newAlertRuleMetric') || {}).value || 'cpu_pct';
  const operator = (document.getElementById('newAlertRuleOperator') || {}).value || '>';
  const threshold = parseFloat((document.getElementById('newAlertRuleThreshold') || {}).value || '0');
  const source_filter = (document.getElementById('newAlertRuleSourceFilter') || {}).value || '';
  const window_seconds = parseInt((document.getElementById('newAlertRuleWindow') || {}).value || '60', 10);
  const action_kind = (document.getElementById('newAlertRuleAction') || {}).value || 'alert';
  const cooldown_seconds = parseInt((document.getElementById('newAlertRuleCooldown') || {}).value || '300', 10);
  if (!name) { showToast('Name required', 'error'); return; }
  const body = {
    name,
    condition: { metric, operator, threshold },
    action: { kind: action_kind },
    window_seconds,
    cooldown_seconds,
    enabled: true,
  };
  if (description) body.description = description;
  if (source_filter) body.source_filter = source_filter;
  fetch('/api/alert-rules', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify(body),
  })
    .then(r => {
      if (r.ok) {
        document.getElementById('newAlertRuleName').value = '';
        document.getElementById('newAlertRuleDesc').value = '';
        document.getElementById('newAlertRuleThreshold').value = '';
        document.getElementById('newAlertRuleSourceFilter').value = '';
        document.getElementById('newAlertRuleWindow').value = '60';
        document.getElementById('newAlertRuleCooldown').value = '300';
        loadAlertRules();
        showToast('Alert rule saved', 'success', 2000);
      } else {
        r.text().then(t => showToast(t || 'Save failed', 'error'));
      }
    })
    .catch(() => showToast('Save failed', 'error'));
}

// ── BL356 Exit Hooks ─────────────────────────────────────────────────────────
function loadExitHooks() {
  const el = document.getElementById('exitHooksList');
  if (!el) return;
  // Settings-tab federation pass (2026-10-08): was raw, non-proxy-aware.
  apiFetch('/api/exit-hooks')
    .then(hooks => {
      if (!hooks || hooks.length === 0) {
        el.innerHTML = '<div style="color:var(--text2);font-size:13px;padding:0 16px;">No exit hooks configured.</div>';
        return;
      }
      el.innerHTML = '<div>' + hooks.map(h => {
        const hid = 'eh-' + h.id;
        const lastFired = h.last_fired_at && h.last_fired_at !== '0001-01-01T00:00:00Z'
          ? new Date(h.last_fired_at).toLocaleString() : 'never';
        const detail = h.action === 'notify' && h.notify_session ? ` → ${escHtml(h.notify_session)}` : '';
        return `<div class="settings-list-row">
          <div class="settings-list-view" id="${hid}-view">
            <div class="settings-list-info">
              <span class="state state-${h.enabled ? 'running' : 'failed'}" style="font-size:10px;margin-right:6px;">${h.enabled ? 'on' : 'off'}</span>
              <strong>${escHtml(h.name)}</strong>
              <span class="settings-list-detail">${escHtml(h.action)}${detail}  cooldown:${h.cooldown_seconds}s</span>
              <span class="settings-list-tag">last: ${escHtml(lastFired)}</span>
            </div>
            <div class="settings-list-actions">
              <button class="btn-icon" title="${h.enabled ? 'Disable' : 'Enable'}" onclick="toggleExitHook('${escHtml(h.id)}',${!h.enabled})">${h.enabled ? '⏸' : '▶'}</button>
              <button class="btn-icon btn-icon-del" title="Delete" onclick="deleteExitHook('${escHtml(h.id)}')">✕</button>
            </div>
          </div>
        </div>`;
      }).join('') + '</div>';
    })
    .catch(e => { el.innerHTML = `<div style="color:var(--error);font-size:13px;padding:0 16px;">${escHtml(_fedMsg(e, 'Failed to load exit hooks.'))}</div>`; });
}

function exitHookActionChange() {
  const action = (document.getElementById('newExitHookAction') || {}).value || 'restart';
  const notifyFields = document.getElementById('exitHookNotifyFields');
  if (notifyFields) notifyFields.style.display = action === 'notify' ? '' : 'none';
}

function createExitHook() {
  const name = (document.getElementById('newExitHookName') || {}).value || '';
  const action = (document.getElementById('newExitHookAction') || {}).value || 'restart';
  const notifySession = (document.getElementById('newExitHookNotifySession') || {}).value || '';
  const notifyMessage = (document.getElementById('newExitHookNotifyMessage') || {}).value || '';
  const cooldown = parseInt((document.getElementById('newExitHookCooldown') || {}).value || '300', 10);
  if (!name) { showToast('Session name required', 'error'); return; }
  const body = { name, action, cooldown_seconds: cooldown };
  if (action === 'notify' && notifySession) {
    body.notify_session = notifySession;
    if (notifyMessage) body.notify_message = notifyMessage;
  }
  fetch('/api/exit-hooks', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify(body),
  })
    .then(r => {
      if (r.ok) {
        if (document.getElementById('newExitHookName')) document.getElementById('newExitHookName').value = '';
        if (document.getElementById('newExitHookNotifySession')) document.getElementById('newExitHookNotifySession').value = '';
        if (document.getElementById('newExitHookNotifyMessage')) document.getElementById('newExitHookNotifyMessage').value = '';
        if (document.getElementById('newExitHookCooldown')) document.getElementById('newExitHookCooldown').value = '300';
        loadExitHooks();
        showToast('Exit hook added', 'success', 2000);
      } else {
        r.text().then(t => showToast(t || 'Save failed', 'error'));
      }
    })
    .catch(() => showToast('Save failed', 'error'));
}

function toggleExitHook(id, enable) {
  const updates = { enabled: enable };
  fetch('/api/exit-hooks/' + encodeURIComponent(id), {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...tokenHeader() },
    body: JSON.stringify(updates),
  })
    .then(r => r.ok ? loadExitHooks() : showToast('Toggle failed', 'error'))
    .catch(() => showToast('Toggle failed', 'error'));
}

function deleteExitHook(id) {
  fetch('/api/exit-hooks/' + encodeURIComponent(id), {
    method: 'DELETE',
    headers: tokenHeader(),
  })
    .then(r => r.ok ? loadExitHooks() : showToast('Delete failed', 'error'))
    .catch(() => showToast('Delete failed', 'error'));
}

// ── Visual viewport height tracking (mobile keyboard) ────────────────────────
// Two CSS variables kept in sync with visualViewport:
//   --app-h      → drives .app height (flex layout collapses with keyboard)
//   --keyboard-h → drives .view bottom offset (.view is position:fixed and
//                  ignores --app-h; this shifts it up above the keyboard)
// 100dvh does NOT shrink on iOS when the software keyboard is up.
if (window.visualViewport) {
  const _setAppH = () => {
    const vvh = window.visualViewport.height;
    const offsetTop = window.visualViewport.offsetTop || 0;
    // keyboard height = layout viewport height minus visual viewport (minus any
    // top offset from scroll/pinch — normally 0 on a standard session view).
    const keyboardH = Math.max(0, window.innerHeight - vvh - offsetTop);
    document.documentElement.style.setProperty('--app-h', vvh + 'px');
    document.documentElement.style.setProperty('--keyboard-h', keyboardH + 'px');
  };
  _setAppH(); // set immediately so variables exist before first render
  window.visualViewport.addEventListener('resize', _setAppH);
}

// GH#192 D65a — three-finger swipe opens a real server-picker overlay,
// matching the apps (operator decision 2026-10-07, reversing the
// scroll+highlight approach below: the PWA's always-visible toolbar bar
// stays as the primary picker for mouse/trackpad use -- this is a
// phone-specific shortcut to the same action set, now in a real overlay
// instead of a scroll+pulse, and it no longer no-ops with zero
// configured servers). Reuses the same selectServer()/state.servers
// source _serverPickerBar() already uses -- no duplicate fetch, no
// duplicate server-list logic.
function openServerPickerModal() {
  const existing = document.getElementById('serverPickerModal');
  if (existing) existing.remove();
  const modal = document.createElement('div');
  modal.id = 'serverPickerModal';
  modal.className = 'confirm-modal-overlay';
  modal.innerHTML = `<div class="confirm-modal" style="max-width:320px;">
    <div style="font-size:13px;font-weight:600;color:var(--text);margin-bottom:10px;">${escHtml(t('server_picker_modal_title') || 'Servers')}</div>
    <div id="serverPickerModalList" style="display:flex;flex-direction:column;gap:6px;">${loadingEyeBlock()}</div>
    <div style="display:flex;justify-content:space-between;margin-top:12px;">
      <button class="btn-secondary" style="font-size:12px;padding:4px 12px;" onclick="_openAddServerFromPicker()">+ ${escHtml(t('server_picker_add') || 'Add server')}</button>
      <button class="btn-secondary" style="font-size:12px;padding:4px 12px;" onclick="document.getElementById('serverPickerModal').remove()">${escHtml(t('action_close') || 'Close')}</button>
    </div>
  </div>`;
  modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });
  document.body.appendChild(modal);
  _loadServerPickerModalList();
}
window.openServerPickerModal = openServerPickerModal;

function _loadServerPickerModalList() {
  const listEl = document.getElementById('serverPickerModalList');
  if (!listEl) return;
  const render = () => {
    const el = document.getElementById('serverPickerModalList');
    if (!el) return; // modal was closed before the fetch resolved
    const servers = (state.servers && Array.isArray(state.servers.servers)
      ? state.servers.servers
      : Array.isArray(state.servers) ? state.servers : []).filter(s => s.enabled !== false);
    const active = state.activeServer || null;
    // Always offers All + this server, even with zero remote servers
    // configured -- the one thing the old scroll+highlight approach
    // could never do. GH#194 -- never literally "Local"; real hostname
    // once _ensureLocalHostname resolves (kicked off below).
    const chips = [
      { name: 'all', label: t('server_all_label') || 'All' },
      { name: null, label: _localHostname || t('server_local_label') || 'This server' },
      ...servers.map(s => ({ name: s.name, label: s.label || s.name })),
    ];
    el.innerHTML = chips.map(c => {
      const isActive = c.name === active;
      return `<button data-server-name="${escHtml(c.name || '')}" onclick="${escHtml(`selectServer(${c.name ? JSON.stringify(c.name) : 'null'});document.getElementById('serverPickerModal').remove();`)}" style="text-align:left;padding:8px 10px;border-radius:6px;border:1px solid var(--border);background:${isActive ? 'var(--accent2,#4f8)' : 'var(--bg3,#2d3148)'};color:${isActive ? '#fff' : 'var(--text)'};font-weight:${isActive ? '600' : '400'};cursor:pointer;">${isActive ? '● ' : '○ '}${escHtml(c.label)}</button>`;
    }).join('');
    // GH#194 -- re-render (not a text-patch) once the real hostname
    // resolves, so the "● "/"○ " active-marker prefix this modal's
    // markup carries is rebuilt correctly rather than clobbered by a
    // blind textContent overwrite. Only registers a waiter while the
    // hostname is still unknown -- once known, render() already used
    // it above, so there's nothing to wait for.
    if (!_localHostname) _ensureLocalHostname(render);
  };
  if (state.servers === undefined) {
    listEl.innerHTML = `<div style="font-size:12px;color:var(--text-dim,#888);padding:8px 10px;">${escHtml(t('server_picker_loading') || 'Loading servers…')}</div>`;
    _onServerListReady(render);
    loadServerListEager();
  } else {
    render();
  }
}

// "+ Add server" reuses the existing Settings -> Comms -> Remote Servers
// add-server form (showServerForm/#serverFormWrap) via navigation,
// rather than rebuilding a second copy of that form inside this modal --
// that form's DOM only exists on the Settings page, so it can't be
// reused in place from an arbitrary other view.
function _openAddServerFromPicker() {
  const modal = document.getElementById('serverPickerModal');
  if (modal) modal.remove();
  _settingsTab = 'comms';
  localStorage.setItem('cs_settings_tab', 'comms');
  navigate('settings');
  setTimeout(() => {
    showServerForm(null);
    const wrap = document.getElementById('serverFormWrap');
    if (wrap) wrap.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, 150);
}
window._openAddServerFromPicker = _openAddServerFromPicker;

// ── GH#172 D65 — three-finger swipe-up gesture ──────────────────────────────
// Android: gesture/ThreeFingerSwipe.kt (64dp, 500ms debounce) -> opens the
// server/profile picker. iOS: ServerSwitchGesture.swift (3-touch swipe up ->
// picker dialog). Confirmed via the datawatch-app repo's own parity audit
// (docs/parity/sections/02-sessions-list.md row 91) before building, since
// the issue thread alone didn't say what the gesture does.
(function initThreeFingerSwipeGesture() {
  let startY = null;
  let lastTriggerAt = 0;
  const THRESHOLD_PX = 64;
  const DEBOUNCE_MS = 500;

  function avgTouchY(touches) {
    let sum = 0;
    for (let i = 0; i < 3; i++) sum += touches[i].clientY;
    return sum / 3;
  }

  document.addEventListener('touchstart', (e) => {
    startY = e.touches.length === 3 ? avgTouchY(e.touches) : null;
  }, { passive: true });

  document.addEventListener('touchmove', (e) => {
    if (startY === null || e.touches.length !== 3) return;
    const deltaY = startY - avgTouchY(e.touches); // positive = moved up
    if (deltaY >= THRESHOLD_PX) {
      const now = Date.now();
      if (now - lastTriggerAt >= DEBOUNCE_MS) {
        lastTriggerAt = now;
        openServerPickerModal();
      }
      startY = null; // require a fresh 3-touch start for the next trigger
    }
  }, { passive: true });

  document.addEventListener('touchend', (e) => {
    if (e.touches.length < 3) startY = null;
  }, { passive: true });
})();

// ── Back button ──────────────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  const backBtn = document.getElementById('backBtn');
  if (backBtn) {
    backBtn.addEventListener('click', () => {
      navigate('sessions');
    });
  }

  registerServiceWorker();
  // Load i18n bundle before rendering — non-blocking on the WS connect.
  // navigate() reads from t() so the bundle must be present before the
  // first render. Falls through to English on fetch failure.
  initI18n().finally(() => {
    document.documentElement.setAttribute('lang', window._i18n.current);
    // A tag selection restored from storage counts from the first paint, in the loaded language.
    _tagsMenuRefresh();
    // If no token is stored, probe health to see if auth is required before
    // spinning up the WS. When it is, replace the splash with a token-entry
    // prompt so visitors without credentials don't see an endless loading
    // animation that reveals what's running.
    const _storedTok = localStorage.getItem('cs_token') || '';
    if (!_storedTok) {
      fetch('/api/health').then(r => r.ok ? r.json() : null).then(h => {
        if (h && h.auth_required) {
          const splash = document.getElementById('splash');
          if (splash) {
            if (window._splashStopFn) window._splashStopFn();
            splash.innerHTML = `<div class="splash-content" style="gap:20px;">
              <div class="splash-title" style="font-size:15px;">Access token required</div>
              <div style="display:flex;flex-direction:column;gap:8px;width:240px;">
                <input id="splashTokenInput" type="password" class="form-input"
                  placeholder="Paste your access token"
                  style="font-size:12px;"
                  onkeydown="if(event.key==='Enter')window.splashSaveToken()" />
                <button class="btn-primary" onclick="window.splashSaveToken()" style="font-size:12px;">Connect</button>
              </div>
            </div>`;
            splash.style.visibility = 'visible';
            setTimeout(() => document.getElementById('splashTokenInput')?.focus(), 50);
          }
        } else {
          const splash = document.getElementById('splash');
          if (splash) splash.style.visibility = 'visible';
          connect();
        }
      }).catch(() => {
        const splash = document.getElementById('splash');
        if (splash) splash.style.visibility = 'visible';
        connect();
      });
    } else {
      const splash = document.getElementById('splash');
      if (splash) splash.style.visibility = 'visible';
      connect();
    }
    let _initView = localStorage.getItem('cs_active_view');
    const _initSession = localStorage.getItem('cs_active_session');
    // BL247-followup v6.7.3 — Monitor sub-tab dropped; its content + a
    // Federated Peers card live in the top-level Observer view.
    // Operators with cs_settings_tab='monitor' (or those who briefly
    // landed on the v6.7.2 redirect) get bounced to the Observer view.
    const _initSettingsTab = localStorage.getItem('cs_settings_tab');
    if (_initSettingsTab === 'monitor') {
      _initView = 'observer';
      localStorage.setItem('cs_active_view', 'observer');
      localStorage.removeItem('cs_settings_tab');
    }
    // Automation used to be a top-level view; it is now a sub-tab of
    // Automata, so a stored 'automation' view restores into that sub-tab.
    if (_initView === 'automation') {
      _automataState.tab = 'automation';
      _initView = state._autonomousEnabled === false ? 'sessions' : 'autonomous';
    }
    navigate(_initView || 'sessions', _initSession || undefined);

    // A saved link to the Automation list or one Automation lands on the
    // Automata tab's Automation sub-tab (and opens the item) once the
    // subsystem is known to be on.
    const _deepLinkAutomation = _automationRouteFromLocation(window.location);
    if (_deepLinkAutomation !== null && state._autonomousEnabled !== false) {
      setTimeout(() => { if (state._autonomousEnabled !== false) openAutomationLink(_deepLinkAutomation); }, 300);
    }

    // GH#182 — alert deep link. A browser rewrites a registered
    // web+datawatch://alert/<id> link into start_url?alert=<id> per the
    // Web App Manifest protocol_handlers spec (see manifest.json); the
    // same ?alert= param also works from a plain link (e.g. a push
    // notification's click-action), installed or not.
    const _deepLinkAlertRaw = new URLSearchParams(window.location.search).get('alert');
    if (_deepLinkAlertRaw) {
      const _deepLinkAlertId = parseAlertDeepLinkId(_deepLinkAlertRaw);
      if (_deepLinkAlertId) setTimeout(() => openAlertDeepLink(_deepLinkAlertId), 300);
    }
  });

  // Operator-reported (2026-10-07): the server/host list must be available
  // before the operator ever tries to pick one, and independent of whether
  // any individual host is actually reachable — otherwise a slow/broken
  // host can make it look like the picker itself is stuck. Kick this off
  // eagerly at boot, in parallel with the other init fetches below, rather
  // than waiting for the first view that happens to need it.
  loadServerListEager();

  // Load initial unread alert count. unread=1 returns only the unread alerts
  // (plus unread_count), which is all the badge and the watched-only seed read.
  fetch('/api/alerts?unread=1', { headers: tokenHeader() })
    .then(r => r.ok ? r.json() : null)
    .then(data => {
      if (!data) return;
      state.alertUnread = data.unread_count || 0;
      // GH#192 D61a — the plain unread_count field has no per-session
      // breakdown; derive the watched-only seed from the unread alerts
      // array the same endpoint already returns.
      state.alertWatchedUnread = (data.alerts || []).filter(a =>
        !a.read && a.session_id && state.watchedSessions.has(a.session_id)
      ).length;
      updateAlertBadge();
    })
    .catch(() => {});

  // v5.26.8 — cache whisper-enabled so mic-button affordances on
  // textareas + CSV-expand modals only render when transcription is
  // actually wired. Operator-reported: mic should only show if
  // whisper is configured.
  fetch('/api/config', { headers: tokenHeader() })
    .then(r => r.ok ? r.json() : null)
    .then(cfg => {
      state._whisperEnabled = !!(cfg && cfg.whisper && cfg.whisper.enabled);
    })
    .catch(() => { state._whisperEnabled = false; });

  // v5.26.8 — hide the Autonomous tab when autonomous.enabled=false.
  // Operator-reported: tabs for disabled subsystems shouldn't render
  // at all. The button starts display:none in index.html; JS unhides
  // when /api/autonomous/config returns enabled:true. If the request
  // fails (auth issue, daemon down) we leave it hidden — better to
  // be invisible than to show a tab that 503s on click.
  fetch('/api/autonomous/config', { headers: tokenHeader() })
    .then(r => r.ok ? r.json() : null)
    .then(cfg => {
      const btn = document.getElementById('navBtnAutonomous');
      if (btn && cfg && cfg.enabled === true) btn.style.display = '';
      // The Automation sub-tab needs the subsystem enabled: when it is
      // disabled, a stored 'automation' sub-tab falls back to 'automata'.
      state._autonomousEnabled = !!(cfg && cfg.enabled === true);
      _automataFallbackFromAutomation();
      // BL313 — Dashboard is part of the autonomous subsystem; gate it on the same flag.
      const dashBtn = document.getElementById('navBtnDashboard');
      if (dashBtn && cfg && cfg.enabled === true) dashBtn.style.display = '';
    })
    .catch(() => {
      // Config unreachable: no Automation sub-tab, so do not stay on it.
      state._autonomousEnabled = false;
      _automataFallbackFromAutomation();
    });

  // BL247-followup v6.7.2 — Observer view folded into Settings → Monitor
  // (Federated Peers card). The standalone nav button + view path were
  // removed; the BL220-G1 visibility check that previously revealed the
  // nav button is no longer needed because the Monitor card is always
  // present in Settings, and its loader degrades gracefully when
  // /api/observer/stats is unreachable.

  // BL238 — Plugins, Routing, Orchestrator moved to Settings sub-tabs; nav visibility checks removed.

  // Periodically refresh time-ago labels while on sessions view
  setInterval(() => {
    if (state.activeView === 'sessions') {
      renderSessionsView();
    }
  }, 30000);
});

