// ── BL220-G1 Observer panel ───────────────────────────────────────────────────

// ── /dashboard Mission Control (BL303 S4) ────────────────────────────────────

function _dashNodeColor(stateStr) {
  const s = stateStr || 'unknown';
  if (s === 'running' || s === 'generating') return 'var(--accent)';
  if (s === 'waiting_input' || s === 'waiting') return 'var(--warning)';
  if (s === 'completed' || s === 'done') return '#22c55e';
  if (s === 'failed' || s === 'blocked' || s === 'error') return 'var(--error)';
  return 'var(--text2)';
}

function _dashInitNodes() {
  _dash.nodes = {};
  _dash.edges = [];
  const svgEl = document.getElementById('constellationSvg');
  const W = (svgEl && svgEl.clientWidth) || 320;
  const H = (svgEl && svgEl.clientHeight) || 220;
  const sessions = state.sessions;
  if (!sessions.length) return;
  const cx = W / 2, cy = H / 2;
  sessions.forEach((s, i) => {
    if (_dash.nodes[s.full_id]) return;
    const angle = (2 * Math.PI * i) / sessions.length;
    const r = Math.min(cx, cy) * 0.55;
    _dash.nodes[s.full_id] = {
      x: cx + Math.cos(angle) * r,
      y: cy + Math.sin(angle) * r,
      vx: 0, vy: 0,
      color: _dashNodeColor(s.state),
      label: (s.name || s.task || s.id || '?').slice(0, 18),
      hookHealth: (_dash._boards[s.full_id] && _dash._boards[s.full_id].hook_health) || 'missing',
      state: s.state || 'unknown',
      threats: 0,
      prd: false,
    };
  });
  // Add Automata nodes (slightly larger radius)
  for (const p of (_dash._prds || [])) {
    if (!_dash.nodes[p.id]) {
      _dash.nodes[p.id] = {
        x: cx + (Math.random() - 0.5) * W * 0.4,
        y: cy + (Math.random() - 0.5) * H * 0.4,
        vx: 0, vy: 0,
        color: _dashNodeColor(p.status),
        label: (p.title || p.name || p.id || '?').slice(0, 18),
        hookHealth: 'missing',
        state: p.status || 'unknown',
        threats: 0,
        prd: true,
      };
    }
  }
  // Edges: session parent_id relationships
  for (const s of sessions) {
    if (s.parent_id && _dash.nodes[s.parent_id] && _dash.nodes[s.full_id]) {
      _dash.edges.push({ from: s.parent_id, to: s.full_id });
    }
  }
}

function _dashReconcileNodes() {
  const sessions = state.sessions || [];
  const svgEl = document.getElementById('constellationSvg');
  const W = (svgEl && svgEl.clientWidth) || 320;
  const H = (svgEl && svgEl.clientHeight) || 220;
  const cx = W / 2, cy = H / 2;

  // Build live ID sets
  const liveSessIds = new Set(sessions.map(s => s.full_id).filter(Boolean));
  const livePrdIds = new Set((_dash._prds || []).map(p => p.id).filter(Boolean));

  // Remove nodes whose session/prd no longer exists
  for (const id of Object.keys(_dash.nodes)) {
    if (!liveSessIds.has(id) && !livePrdIds.has(id)) {
      delete _dash.nodes[id];
      // Clean up stale board cache too
      delete _dash._boards[id];
    }
  }

  // Add newly appeared sessions
  sessions.forEach((s, i) => {
    if (!s.full_id || _dash.nodes[s.full_id]) return;
    // Spawn near center with small random offset so it drifts outward
    _dash.nodes[s.full_id] = {
      x: cx + (Math.random() - 0.5) * 60,
      y: cy + (Math.random() - 0.5) * 60,
      vx: (Math.random() - 0.5) * 2,
      vy: (Math.random() - 0.5) * 2,
      color: _dashNodeColor(s.state),
      label: (s.name || s.task || s.id || '?').slice(0, 18),
      hookHealth: (_dash._boards[s.full_id] && _dash._boards[s.full_id].hook_health) || 'missing',
      state: s.state || 'unknown',
      threats: 0,
      prd: false,
    };
  });

  // Add newly appeared automata
  for (const p of (_dash._prds || [])) {
    if (!p.id || _dash.nodes[p.id]) continue;
    _dash.nodes[p.id] = {
      x: cx + (Math.random() - 0.5) * W * 0.3,
      y: cy + (Math.random() - 0.5) * H * 0.3,
      vx: 0, vy: 0,
      color: _dashNodeColor(p.status),
      label: (p.title || p.name || p.id || '?').slice(0, 18),
      hookHealth: 'missing',
      state: p.status || 'unknown',
      threats: 0,
      prd: true,
    };
  }

  // Rebuild edges to match current live nodes
  _dash.edges = [];
  for (const s of sessions) {
    if (s.parent_id && _dash.nodes[s.parent_id] && _dash.nodes[s.full_id]) {
      _dash.edges.push({ from: s.parent_id, to: s.full_id });
    }
  }

  // Update state/color for still-alive session nodes from current state.sessions
  for (const s of sessions) {
    const n = _dash.nodes[s.full_id];
    if (!n) continue;
    n.state = s.state || n.state;
    n.color = _dashNodeColor(n.state);
    n.label = (s.name || s.task || s.id || '?').slice(0, 18);
  }
}

function _dashForceStep() {
  const ids = Object.keys(_dash.nodes);
  if (ids.length < 2) return;
  const svgEl = document.getElementById('constellationSvg');
  if (!svgEl) return;
  const W = svgEl.clientWidth || 320, H = svgEl.clientHeight || 220;
  const cx = W / 2, cy = H / 2;

  // Repulsion
  for (let i = 0; i < ids.length; i++) {
    for (let j = i + 1; j < ids.length; j++) {
      const a = _dash.nodes[ids[i]], b = _dash.nodes[ids[j]];
      const dx = b.x - a.x, dy = b.y - a.y;
      const d2 = dx*dx + dy*dy + 1;
      const f = Math.min(2500 / d2, 3);
      const fx = (dx / Math.sqrt(d2)) * f;
      const fy = (dy / Math.sqrt(d2)) * f;
      a.vx -= fx; a.vy -= fy;
      b.vx += fx; b.vy += fy;
    }
    // Gravity toward center
    const n = _dash.nodes[ids[i]];
    n.vx += (cx - n.x) * 0.008;
    n.vy += (cy - n.y) * 0.008;
  }

  // Edge attraction
  for (const e of _dash.edges) {
    const a = _dash.nodes[e.from], b = _dash.nodes[e.to];
    if (!a || !b) continue;
    const dx = b.x - a.x, dy = b.y - a.y;
    const d = Math.sqrt(dx*dx + dy*dy) + 0.01;
    const target = Math.min(W, H) * 0.22;
    const f = (d - target) * 0.015;
    const fx = (dx / d) * f, fy = (dy / d) * f;
    a.vx += fx; a.vy += fy;
    b.vx -= fx; b.vy -= fy;
  }

  // Integrate + clamp
  for (const id of ids) {
    const n = _dash.nodes[id];
    const r = n.prd ? 20 : 14;
    n.vx *= 0.72; n.vy *= 0.72;
    n.x = Math.max(r + 2, Math.min(W - r - 2, n.x + n.vx));
    n.y = Math.max(r + 14, Math.min(H - r - 2, n.y + n.vy));
  }
}

function _drawConstellation() {
  const svgEl = document.getElementById('constellationSvg');
  if (!svgEl) return;
  const W = svgEl.clientWidth || 320, H = svgEl.clientHeight || 220;
  svgEl.setAttribute('viewBox', `0 0 ${W} ${H}`);

  // Issue #98 — narrow fallback: width < 400px → compact text list
  if (W < 400) {
    const sessions = state.sessions || [];
    if (sessions.length === 0) {
      svgEl.innerHTML = `<text x="${W/2}" y="${H/2}" text-anchor="middle" font-size="13" fill="var(--text2)">${escHtml(t('dash_no_sessions') || 'No active sessions')}</text>`;
      return;
    }
    const stateColors = { running: '#7c3aed', generating: '#7c3aed', waiting_input: '#f59e0b', completed: '#10b981', failed: '#ef4444', blocked: '#ef4444', idle: '#64748b' };
    const stateBadges = { running: '▶', generating: '▶', waiting_input: '⏸', completed: '✓', failed: '✗', blocked: '!', idle: '○' };
    let html = '';
    const ROW_H = 20, PAD = 8;
    for (let i = 0; i < sessions.length && i < Math.floor((H - PAD) / ROW_H); i++) {
      const s = sessions[i];
      const col = stateColors[s.state] || '#64748b';
      const badge = stateBadges[s.state] || '·';
      const name = (s.name || s.task || s.id || '').slice(0, 18);
      const age = s.created_at ? timeAgo(s.created_at) : '';
      const y = PAD + i * ROW_H + 13;
      html += `<text x="${PAD}" y="${y}" font-size="11" fill="${col}" style="pointer-events:none">• ${escHtml(name)}</text>`;
      html += `<text x="${W - PAD - (age ? 36 : 18)}" y="${y}" font-size="10" fill="${col}" font-weight="700" style="pointer-events:none">${escHtml(badge)}</text>`;
      if (age) html += `<text x="${W - PAD}" y="${y}" font-size="9" fill="var(--text2)" text-anchor="end" style="pointer-events:none">${escHtml(age)}</text>`;
    }
    svgEl.innerHTML = html;
    return;
  }

  const ids = Object.keys(_dash.nodes);
  if (ids.length === 0) {
    svgEl.innerHTML = `<text x="${W/2}" y="${H/2}" text-anchor="middle" font-size="13" fill="var(--text2)">${escHtml(t('dash_no_sessions') || 'No active sessions')}</text>`;
    return;
  }

  const now = Date.now();
  let html = `<defs>
    <style>
      .dbn { cursor:pointer; transition:opacity 0.1s; }
      .dbn:hover { opacity:1 !important; filter:brightness(1.25); }
    </style>
  </defs>`;

  // Hint text bottom-left
  html += `<text x="8" y="${H-6}" font-size="10" fill="var(--text2)" opacity="0.5" style="pointer-events:none">Click a node to inspect</text>`;

  // Edges
  for (const e of _dash.edges) {
    const a = _dash.nodes[e.from], b = _dash.nodes[e.to];
    if (!a || !b) continue;
    html += `<line x1="${a.x.toFixed(1)}" y1="${a.y.toFixed(1)}" x2="${b.x.toFixed(1)}" y2="${b.y.toFixed(1)}" stroke="var(--border)" stroke-width="1.5" stroke-dasharray="4,3"/>`;
  }

  // Nodes
  for (const id of ids) {
    const n = _dash.nodes[id];
    const r = n.prd ? 22 : 16;
    const active = n.state === 'running' || n.state === 'generating' || n.state === 'waiting_input';
    const pulseR = active ? (r + 6 + Math.sin(now / 500) * 4) : 0;
    const opacity = n.hookHealth === 'missing' && !n.prd ? '0.4' : '0.9';

    if (active && pulseR > 0) {
      const pulseAlpha = (0.25 + Math.sin(now / 400) * 0.15).toFixed(2);
      html += `<circle cx="${n.x.toFixed(1)}" cy="${n.y.toFixed(1)}" r="${pulseR.toFixed(1)}" fill="none" stroke="${n.color}" stroke-width="2" opacity="${pulseAlpha}"/>`;
    }
    if (n.hookHealth === 'alive') {
      html += `<circle cx="${n.x.toFixed(1)}" cy="${n.y.toFixed(1)}" r="${(r+4).toFixed(1)}" fill="none" stroke="${n.color}" stroke-width="1" opacity="0.4"/>`;
    } else if (n.hookHealth === 'stale') {
      html += `<circle cx="${n.x.toFixed(1)}" cy="${n.y.toFixed(1)}" r="${(r+4).toFixed(1)}" fill="none" stroke="var(--warning)" stroke-width="1" opacity="0.4"/>`;
    }

    // Filled node + invisible larger hit target for easier clicking
    html += `<circle cx="${n.x.toFixed(1)}" cy="${n.y.toFixed(1)}" r="${(r+6).toFixed(1)}" fill="transparent" style="cursor:pointer;" onclick="${escHtml(`window._dashNodeClick(${JSON.stringify(id)})`)}"/>`;
    html += `<circle class="dbn" cx="${n.x.toFixed(1)}" cy="${n.y.toFixed(1)}" r="${r}" fill="${n.color}" opacity="${opacity}" stroke="rgba(255,255,255,0.15)" stroke-width="1.5" onclick="${escHtml(`window._dashNodeClick(${JSON.stringify(id)})`)}">`;
    html += `<title>${escHtml(n.label)} · ${escHtml(n.state)} — click to open</title></circle>`;

    // State initial inside node
    const stateInitial = ({running:'▶', generating:'▶', waiting_input:'⏸', completed:'✓', failed:'✗', blocked:'!', idle:'○'})[n.state] || '·';
    html += `<text x="${n.x.toFixed(1)}" y="${(n.y+4).toFixed(1)}" text-anchor="middle" font-size="${n.prd ? 11 : 9}" fill="rgba(255,255,255,0.85)" style="pointer-events:none;font-weight:700;">${stateInitial}</text>`;

    if (n.threats > 0) {
      html += `<circle cx="${(n.x+r-4).toFixed(1)}" cy="${(n.y-r+4).toFixed(1)}" r="6" fill="var(--error)" opacity="0.95"/>`;
      html += `<text x="${(n.x+r-4).toFixed(1)}" y="${(n.y-r+8).toFixed(1)}" text-anchor="middle" font-size="8" fill="#fff" style="pointer-events:none;font-weight:700;">${n.threats}</text>`;
    }

    const label = n.label.length > 16 ? n.label.slice(0, 15) + '…' : n.label;
    html += `<text x="${n.x.toFixed(1)}" y="${(n.y+r+14).toFixed(1)}" text-anchor="middle" font-size="10" fill="var(--text)" opacity="0.75" style="pointer-events:none">${escHtml(label)}</text>`;
    html += `<text x="${n.x.toFixed(1)}" y="${(n.y+r+24).toFixed(1)}" text-anchor="middle" font-size="9" fill="var(--text2)" opacity="0.55" style="pointer-events:none">${escHtml(n.state)}</text>`;
  }

  svgEl.innerHTML = html;
}

function _drawMultiEKG() {
  const canvas = document.getElementById('ekgCanvas');
  if (!canvas) return;

  // Issue #99 — EKG narrow mode: hide canvas, show burn-rate panel only
  const ekgCardW = canvas.closest('[data-card-id="ekg"]') ? (canvas.closest('[data-card-id="ekg"]').clientWidth || 0) : (canvas.clientWidth || 0);
  const ekgNarrow = ekgCardW < 280 && ekgCardW > 0;
  canvas.style.display = ekgNarrow ? 'none' : '';
  const burnRateEl = document.getElementById('dashBurnRate');
  if (burnRateEl) {
    if (ekgNarrow) {
      burnRateEl.style.width = '100%';
      burnRateEl.style.borderLeft = 'none';
      burnRateEl.style.alignItems = 'center';
    } else {
      burnRateEl.style.width = '';
      burnRateEl.style.borderLeft = '';
      burnRateEl.style.alignItems = '';
    }
  }
  if (ekgNarrow) return;

  const W = canvas.clientWidth || canvas.width;
  const H = canvas.clientHeight || canvas.height;
  if (canvas.width !== W) canvas.width = W;
  if (canvas.height !== H) canvas.height = H;
  const ctx = canvas.getContext('2d');
  const css = getComputedStyle(document.documentElement);
  const bgColor = css.getPropertyValue('--bg').trim() || '#0f1117';
  const borderColor = css.getPropertyValue('--border').trim() || '#2d3148';
  const accentColor = css.getPropertyValue('--accent').trim() || '#7c3aed';
  const text2Color = css.getPropertyValue('--text2').trim() || '#64748b';
  ctx.fillStyle = bgColor;
  ctx.fillRect(0, 0, W, H);
  const activeSessions = (state.sessions || [])
    .filter(s => s.state === 'running' || s.state === 'generating' || s.state === 'waiting_input' || s.state === 'idle')
    .slice(0, 6);
  const LABEL_W = 72;
  if (activeSessions.length === 0) {
    if (_dash.ekg.length >= 2) {
      const pts = _dash.ekg.slice(-W);
      ctx.beginPath(); ctx.strokeStyle = accentColor; ctx.lineWidth = 1.5;
      let fp = true;
      for (let i = 0; i < pts.length; i++) {
        const x = W - pts.length + i;
        const dec = Math.exp(-(pts.length - i) / 60);
        const y = H / 2 - pts[i].dy * dec * (H * 0.38);
        if (fp) { ctx.moveTo(x, y); fp = false; } else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    return;
  }
  const channelH = H / activeSessions.length;
  for (let ci = 0; ci < activeSessions.length; ci++) {
    const sess = activeSessions[ci];
    const sid = sess.full_id || sess.id;
    const color = _dashNodeColor(sess.state);
    const chanY = ci * channelH;
    if (ci % 2 === 1) { ctx.fillStyle = 'rgba(255,255,255,0.015)'; ctx.fillRect(0, chanY, W, channelH); }
    ctx.fillStyle = color; ctx.font = `bold 9px monospace`;
    ctx.fillText((sess.name || sess.id || '?').slice(0, 9), 3, chanY + channelH * 0.5 + 3);
    const board = _dash._boards[sid];
    const hDot = !board ? '○' : board.hook_health === 'alive' ? '●' : '◐';
    const hColor = !board ? text2Color : board.hook_health === 'alive' ? '#10b981' : '#f59e0b';
    ctx.fillStyle = hColor; ctx.font = '8px monospace';
    ctx.fillText(hDot, 3, chanY + channelH * 0.85);
    const sessEvents = _dash.ekg.filter(e => !e.sid || e.sid === sid);
    const barW = W - LABEL_W;
    const pts = sessEvents.slice(-barW);
    if (pts.length >= 2) {
      ctx.beginPath(); ctx.strokeStyle = color; ctx.lineWidth = 1.2;
      let fp = true;
      for (let i = 0; i < pts.length; i++) {
        const x = LABEL_W + barW - pts.length + i;
        const dec = Math.exp(-(pts.length - i) / 50);
        const mid = chanY + channelH / 2;
        const y = mid - pts[i].dy * dec * (channelH * 0.38);
        if (fp) { ctx.moveTo(x, y); fp = false; } else ctx.lineTo(x, y);
      }
      ctx.stroke();
    } else {
      ctx.beginPath(); ctx.strokeStyle = color; ctx.lineWidth = 0.5; ctx.globalAlpha = 0.25;
      ctx.moveTo(LABEL_W, chanY + channelH / 2); ctx.lineTo(W, chanY + channelH / 2); ctx.stroke();
      ctx.globalAlpha = 1;
    }
    if (ci < activeSessions.length - 1) {
      ctx.strokeStyle = borderColor; ctx.lineWidth = 0.5; ctx.setLineDash([2, 4]);
      ctx.beginPath(); ctx.moveTo(0, chanY + channelH); ctx.lineTo(W, chanY + channelH); ctx.stroke();
      ctx.setLineDash([]);
    }
  }
  const grad = ctx.createLinearGradient(LABEL_W, 0, LABEL_W + 16, 0);
  grad.addColorStop(0, bgColor); grad.addColorStop(1, 'transparent');
  ctx.fillStyle = grad; ctx.fillRect(LABEL_W, 0, 16, H);
  ctx.strokeStyle = accentColor; ctx.lineWidth = 0.5; ctx.setLineDash([2, 3]);
  ctx.beginPath(); ctx.moveTo(W - 1, 0); ctx.lineTo(W - 1, H); ctx.stroke();
  ctx.setLineDash([]);
}

function _renderSprintPipeline() {
  const pipeEl = document.getElementById('sprintPipeline');
  if (!pipeEl) return;
  const activePrds = (_dash._prds || []).filter(p => p.status === 'running' || p.status === 'blocked');
  if (activePrds.length === 0) {
    pipeEl.classList.remove('visible');
    return;
  }
  pipeEl.classList.add('visible');
  let html = `<div style="font-size:10px;color:var(--text2);margin-bottom:4px;">${escHtml(t('dash_sprint_pipeline') || 'Sprint Pipeline')}</div>`;
  for (const prd of activePrds.slice(0, 3)) {
    const stories = prd.stories || [];
    html += `<div style="margin-bottom:6px;"><div style="font-size:10px;color:var(--text2);margin-bottom:3px;">${escHtml((prd.title || prd.name || prd.id).slice(0, 32))}</div>`;
    html += `<div class="dboard-pipe-stages">`;
    stories.forEach((st, i) => {
      if (i > 0) {
        const edgeClass = (stories[i-1] && (stories[i-1].status === 'completed')) ? 'active' : '';
        const ringClass = (stories[i-1] && stories[i-1].verdicts && stories[i-1].verdicts.some(v => v.outcome === 'block')) ? 'fail' : (stories[i-1] && stories[i-1].status === 'completed' ? 'pass' : '');
        html += `<div class="dboard-pipe-edge ${edgeClass}"></div>`;
        html += `<div class="dboard-pipe-ring ${ringClass}"></div>`;
        html += `<div class="dboard-pipe-edge ${edgeClass}"></div>`;
      }
      const nodeClass = st.status || 'draft';
      const stLabel = (st.title || `Story ${i+1}`).slice(0, 14);
      html += `<div class="dboard-pipe-node ${nodeClass}" title="${escHtml(st.title || '')}" onclick="${escHtml(`window._dashNodeClick(${JSON.stringify(prd.id)})`)}">${escHtml(stLabel)}</div>`;
    });
    html += `</div></div>`;
  }
  pipeEl.innerHTML = html;
}

function _dashUpdateExpand(sid) {
  const sess = state.sessions.find(s => s.full_id === sid || s.id === sid);
  const board = _dash._boards[sid];

  const titleEl = document.getElementById('dashExpandTitle');
  if (titleEl) {
    const name = sess ? (sess.name || sess.task || '') : '';
    titleEl.textContent = (name || sid || '').slice(0, 40);
  }

  // Sidebar: live task tree
  const treeEl = document.getElementById('dashExpandTree');
  if (treeEl) {
    const tel = board && board.telemetry;
    const sessType = detectSessionType(board);
    treeEl.innerHTML = `<div style="font-weight:600;font-size:11px;color:var(--text);margin-bottom:8px;">${escHtml(t('dash_task_tree') || 'Task Tree')}</div>`;
    if (tel) {
      treeEl.innerHTML += renderLiveTaskTree(tel, sessType);
    } else {
      treeEl.innerHTML += `<div style="color:var(--text2);font-size:11px;">${escHtml(t('dash_no_telemetry') || 'No telemetry yet')}</div>`;
    }
  }

  // Main: status board
  const mainEl = document.getElementById('dashExpandMain');
  if (mainEl) {
    if (board) {
      renderSessionStatusBoardInner(mainEl, board, sid);
    } else {
      mainEl.innerHTML = `<div style="color:var(--text2);padding:12px;font-size:12px;">${escHtml(t('dash_expand_no_status') || 'No status data yet — hook events will populate this view.')}</div>`;
      apiFetch('/api/sessions/' + encodeURIComponent(sid) + '/status')
        .then(b => { _dash._boards[sid] = b; if (_dash.expandSid === sid) _dashUpdateExpand(sid); })
        .catch(() => {});
    }
  }

  // Verdicts rail
  const verdEl = document.getElementById('dashExpandVerdicts');
  if (verdEl) {
    const verdicts = (board && board.telemetry && board.telemetry.guardrail_verdicts) || [];
    verdEl.innerHTML = `<div style="font-weight:600;font-size:11px;color:var(--text);margin-bottom:8px;">${escHtml(t('dash_verdicts') || 'Verdicts')}</div>`;
    if (verdicts.length > 0) {
      verdEl.innerHTML += renderSessionGuardrailVerdicts(verdicts);
    } else {
      verdEl.innerHTML += `<div style="color:var(--text2);font-size:11px;">${escHtml(t('dash_no_verdicts') || 'No verdicts yet')}</div>`;
    }
  }
}

window.openDashExpand = function(sid) {
  if (state.activeView !== 'dashboard') {
    navigate('dashboard');
    setTimeout(() => window.openDashExpand(sid), 80);
    return;
  }
  _dash.expandSid = sid;
  const expand = document.getElementById('dashExpand');
  if (expand) {
    expand.classList.remove('hidden');
    _dashUpdateExpand(sid);
  }
};

window.closeDashExpand = function() {
  _dash.expandSid = null;
  const expand = document.getElementById('dashExpand');
  if (expand) expand.classList.add('hidden');
};

// Coordinator-flagged (2026-10-08), extending the prior round's
// initial-load-only Dashboard banner: the periodic re-fetches in
// _dashLoop below (PRDs, cost, heatmap, compute nodes) are just as
// federation-aware as the initial load, but were still swallowing
// every failure silently (.catch(() => {})) -- a federated denial that
// surfaced on first entering the view would silently go quiet again a
// few seconds later on the first periodic re-fetch. #dashFedErrorBanner
// is a PERSISTENT sibling of #dashCardGrid (not a child -- _dashBuildGrid
// does a full grid.innerHTML replace on every layout load, which would
// have wiped a banner nested inside it, as the previous single-source
// version silently risked). Keyed by source so multiple cards failing
// at once don't clobber each other's message, and each source clears
// independently the next time ITS OWN fetch succeeds.
function _dashSetFedError(source, err) {
  if (!(state.activeServer && state.activeServer !== 'local' && state.activeServer !== 'all')) return;
  state._dashFedErrors = state._dashFedErrors || {};
  state._dashFedErrors[source] = (err && err.message) || 'Failed to load';
  _dashRenderFedErrorBanner();
}
function _dashClearFedError(source) {
  if (state._dashFedErrors && state._dashFedErrors[source]) {
    delete state._dashFedErrors[source];
    _dashRenderFedErrorBanner();
  }
}
function _dashRenderFedErrorBanner() {
  const el = document.getElementById('dashFedErrorBanner');
  if (!el) return;
  const errs = state._dashFedErrors || {};
  const keys = Object.keys(errs);
  if (!keys.length) { el.innerHTML = ''; return; }
  const combined = keys.map(k => errs[k]).join('; ');
  el.innerHTML = `<div class="dash-fed-error-banner" style="background:rgba(239,68,68,0.12);color:var(--error,#ef4444);border-radius:6px;padding:8px 12px;font-size:12px;margin:0 0 8px;">${escHtml(t('dash_fed_error', [state.activeServer, combined]) || `${state.activeServer}: ${combined}`)}</div>`;
}

function _dashLoop(ts) {
  if (state.activeView !== 'dashboard') { _dash.rafId = null; return; }
  _dash._frameCount++;

  // Canvas renders at full rate
  _drawMultiEKG();
  _dashForceStep();

  // Orbital + Gantt at ~10fps
  if (_dash._frameCount % 6 === 0) {
    _drawConstellation();
    _drawGantt();
  }

  // Sparklines + heatmap at ~5fps
  if (_dash._frameCount % 12 === 0) {
    _drawSparklines();
    _drawHeatmap();
  }

  // Stat bar + tree + event feed + burn rate + guardrails + smoke at ~5fps
  if (_dash._frameCount % 12 === 0) {
    _dashUpdateStatBar();
    _dashRenderTree();
    _dashRenderEventFeed();
    _dashRenderBurnRate();
    _dashRenderGuardrails();
    _dashRenderMemoryScope();
    _dashRenderWebSearchUsage();
    _dashRenderIntegrationStatus();
    _dashRenderPluginWidgets();
    _dashRenderSmoke();
  }

  // Node reconcile at ~2fps
  if (_dash._frameCount % 30 === 0) {
    _dashReconcileNodes();
  }

  // Re-fetch automata every ~5s
  if (_dash._frameCount % 150 === 0 && !_dash._prdsFetching) {
    _dash._prdsFetching = true;
    _dashFetchPRDs().then(() => { _dash._prdsLastFetch = Date.now(); _dashClearFedError('prds'); }).catch(e => _dashSetFedError('prds', e)).finally(() => { _dash._prdsFetching = false; });
  }

  // Fetch cost every ~30s
  if (_dash._frameCount % 900 === 0 && !_dash._costFetching) {
    _dash._costFetching = true;
    _dashFetchCost().then(() => _dashClearFedError('cost')).catch(e => _dashSetFedError('cost', e)).finally(() => { _dash._costFetching = false; });
  }

  // Fetch heatmap data every ~60s
  if ((_dash._frameCount === 1 || _dash._frameCount % 1800 === 0) && !_dash._heatmapFetching) {
    _dash._heatmapFetching = true;
    apiFetch('/api/analytics?range=30d').then(d => {
      _dash._heatmapData = (d && d.buckets) || [];
      _dashClearFedError('heatmap');
    }).catch(e => _dashSetFedError('heatmap', e)).finally(() => { _dash._heatmapFetching = false; });
  }

  // Fetch compute nodes every ~60s for runtime badges
  if ((_dash._frameCount === 1 || _dash._frameCount % 1800 === 0) && !_dash._computeNodesFetching) {
    _dash._computeNodesFetching = true;
    apiFetch('/api/compute/nodes').then(d => {
      _dash._computeNodes = (d && (d.nodes || d)) || [];
      if (!Array.isArray(_dash._computeNodes)) _dash._computeNodes = [];
      _dashClearFedError('compute');
    }).catch(e => _dashSetFedError('compute', e)).finally(() => { _dash._computeNodesFetching = false; });
  }

  // Poll smoke envelopes — fast (2.5s) if any run is active, slow (30s) otherwise
  const hasActiveSmoke = Array.isArray(_dash._smokeEnvelopes) && _dash._smokeEnvelopes.some(e => e.active);
  const smokeInterval = hasActiveSmoke ? 75 : 900;
  if ((_dash._frameCount === 1 || _dash._frameCount % smokeInterval === 0) && !_dash._smokeFetching) {
    _dash._smokeFetching = true;
    fetch('/api/smoke/progress').then(r => {
      if (!r.ok) throw new Error('smoke ' + r.status);
      return r.json();
    }).then(d => {
      if (Array.isArray(d)) {
        _dash._smokeEnvelopes = d;
        // If expanded envelope is still in list, refresh its detail
        if (_dash._smokeExpandedId) {
          const env = d.find(e => e.id === _dash._smokeExpandedId);
          if (!env) { _dash._smokeExpandedId = null; _dash._smokeExpandedData = null; }
        }
        // Auto-select latest active run for detail view
        if (!_dash._smokeExpandedId) {
          const active = d.find(e => e.active);
          if (active) _dash._smokeExpandedId = active.id;
        }
      }
    }).catch(() => {}).finally(() => {
      _dash._smokeFetching = false;
      _dashRenderSmoke();
    });
    // If an envelope is expanded, also refresh its section detail
    if (_dash._smokeExpandedId && !_dash._smokeDetailFetching) {
      _dash._smokeDetailFetching = true;
      fetch('/api/smoke/progress/' + encodeURIComponent(_dash._smokeExpandedId)).then(r => {
        if (r.status === 404) {
          _dash._smokeExpandedId = null;
          _dash._smokeExpandedData = null;
          throw new Error('run not found');
        }
        if (!r.ok) throw new Error(r.status);
        return r.json();
      }).then(d => {
        if (d) _dash._smokeExpandedData = d;
      }).catch(() => {}).finally(() => { _dash._smokeDetailFetching = false; _dashRenderSmoke(); });
    }
  }

  _dash.rafId = requestAnimationFrame(_dashLoop);
}

// ── BL403 Phase 4 — Plugin widget renderers ─────────────────────────────────
// Pure HTML-string renderers for plugin-declared widgets (manifest
// `widgets:` block, v9.0.40 backend: internal/plugins/widgets.go and
// internal/server/plugin_widgets.go). A widget value arrives as a
// pluginWidgetView from GET /api/plugins/{name}/widgets[/{widget_id}]:
//   {id, surface, kind, data_mode, pull_path, interval_seconds,
//    value: null | {plugin, widget_id, data, updated_at, source, error?}}
// `value.data` is free-form JSON written by a third-party plugin, so it is
// UNTRUSTED: every string goes through escHtml, every number through
// Number()/isFinite, colors/icons come from fixed whitelists only, and
// every renderer catches its own errors and falls back to the quiet
// empty state instead of throwing into the dashboard loop.
//
// Per-kind data contract (value.data):
//   stat_tile    {value: number|string, label?, unit?, detail?}
//   table        {columns: [string], rows: [[cell...]] | [{col: cell}]}
//                cells: string|number|boolean|null
//   list         {items: [string | {text, detail?}]}
//   sparkline    {points: [number], label?, value?: number|string}
//   status_badge {status: 'ok'|'warn'|'error'|'unknown', label?, detail?}
//   markdown     {text: string} or a bare JSON string
//
// Nothing here is wired into the dashboard or session view yet; callers
// use _pwRenderInto(el, view) as the single entry point. Card ids for
// the dashboard grid use the form 'plugin:<plugin-name>:<widget-id>'
// (_pwCardId / _pwParseCardId).

const _PW_MAX_ROWS = 50;
const _PW_MAX_COLS = 20;
const _PW_MAX_ITEMS = 50;
const _PW_MAX_POINTS = 500;
const _PW_MAX_TITLE = 500;

// _pwCell coerces a scalar to display text; anything else becomes ''.
function _pwCell(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number') return isFinite(v) ? String(v) : '';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  return '';
}

// _pwTrunc returns escaped text cut to max chars, with the (capped) full
// text in a title attribute when cut — same idiom as the guardrails card.
function _pwTrunc(s, max) {
  s = _pwCell(s);
  if (s.length <= max) return escHtml(s);
  return `<span title="${escHtml(s.slice(0, _PW_MAX_TITLE))}">${escHtml(s.slice(0, max - 1) + '…')}</span>`;
}

function _pwEmptyState(kind) {
  let msg;
  if (kind === 'loading') msg = t('plugin_widget_loading') || 'Loading…';
  else if (kind === 'unavailable') msg = t('plugin_widget_unavailable') || 'Widget unavailable';
  else msg = t('plugin_widget_no_data') || 'No data yet';
  return `<div style="color:var(--text2);font-size:10px;padding:4px 0;">${escHtml(msg)}</div>`;
}

function _pwRenderStatTile(data) {
  try {
    if (!data || typeof data !== 'object' || Array.isArray(data)) return _pwEmptyState('nodata');
    const v = data.value;
    let shown;
    if (typeof v === 'number') {
      if (!isFinite(v)) return _pwEmptyState('nodata');
      shown = String(Number(v));
    } else if (typeof v === 'string' && v !== '') {
      shown = v;
    } else {
      return _pwEmptyState('nodata');
    }
    let html = `<div style="display:flex;align-items:baseline;gap:6px;margin-bottom:2px;">
    <span style="font-size:16px;font-weight:700;color:var(--text);">${_pwTrunc(shown, 24)}</span>`;
    if (typeof data.unit === 'string' && data.unit) html += `<span style="font-size:9px;color:var(--text2);">${_pwTrunc(data.unit, 16)}</span>`;
    html += `</div>`;
    if (typeof data.label === 'string' && data.label) {
      html += `<div style="font-size:9px;color:var(--text2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${_pwTrunc(data.label, 40)}</div>`;
    }
    if (typeof data.detail === 'string' && data.detail) {
      html += `<div style="font-size:9px;color:var(--text2);margin-top:2px;">${_pwTrunc(data.detail, 120)}</div>`;
    }
    return html;
  } catch (_) {
    return _pwEmptyState('nodata');
  }
}

function _pwRenderTable(data) {
  try {
    if (!data || typeof data !== 'object' || !Array.isArray(data.columns) || !Array.isArray(data.rows)) return _pwEmptyState('nodata');
    const cols = data.columns.slice(0, _PW_MAX_COLS).map(c => _pwCell(c));
    if (!cols.length) return _pwEmptyState('nodata');
    const rows = [];
    for (const r of data.rows.slice(0, _PW_MAX_ROWS)) {
      if (Array.isArray(r)) rows.push(cols.map((_, i) => _pwCell(r[i])));
      else if (r && typeof r === 'object') rows.push(cols.map(c => (Object.prototype.hasOwnProperty.call(r, c) ? _pwCell(r[c]) : '')));
    }
    if (!rows.length) return _pwEmptyState('nodata');
    const cellStyle = 'padding:2px 6px 2px 0;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
    let html = `<div style="overflow-x:auto;"><table style="border-collapse:collapse;width:100%;font-size:10px;color:var(--text);">
    <thead><tr>`;
    for (const c of cols) html += `<th style="${cellStyle}text-align:left;font-size:9px;font-weight:600;color:var(--text2);border-bottom:1px solid var(--border);">${_pwTrunc(c, 28)}</th>`;
    html += `</tr></thead><tbody>`;
    for (const r of rows) {
      html += `<tr>`;
      for (const cell of r) html += `<td style="${cellStyle}border-bottom:1px solid var(--border);">${_pwTrunc(cell, 40)}</td>`;
      html += `</tr>`;
    }
    html += `</tbody></table></div>`;
    if (data.rows.length > _PW_MAX_ROWS) {
      html += `<div style="font-size:9px;color:var(--text2);margin-top:2px;">+${Number(data.rows.length - _PW_MAX_ROWS)}</div>`;
    }
    return html;
  } catch (_) {
    return _pwEmptyState('nodata');
  }
}

function _pwRenderList(data) {
  try {
    if (!data || typeof data !== 'object' || !Array.isArray(data.items)) return _pwEmptyState('nodata');
    let html = '';
    let n = 0;
    for (const it of data.items.slice(0, _PW_MAX_ITEMS)) {
      let text = '', detail = '';
      if (typeof it === 'string' || typeof it === 'number') text = _pwCell(it);
      else if (it && typeof it === 'object') { text = _pwCell(it.text); detail = _pwCell(it.detail); }
      if (!text) continue;
      n++;
      html += `<div style="margin-bottom:4px;">
      <div style="font-size:10px;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${_pwTrunc(text, 60)}</div>`;
      if (detail) html += `<div style="font-size:9px;color:var(--text2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${_pwTrunc(detail, 80)}</div>`;
      html += `</div>`;
    }
    if (!n) return _pwEmptyState('nodata');
    if (data.items.length > _PW_MAX_ITEMS) {
      html += `<div style="font-size:9px;color:var(--text2);">+${Number(data.items.length - _PW_MAX_ITEMS)}</div>`;
    }
    return html;
  } catch (_) {
    return _pwEmptyState('nodata');
  }
}

// Inline-SVG polyline. Only finite numbers reach the markup, and every
// coordinate is a toFixed() number, so nothing plugin-supplied lands in
// an SVG attribute. Keeps the most recent _PW_MAX_POINTS points.
function _pwRenderSparkline(data) {
  try {
    if (!data || typeof data !== 'object' || !Array.isArray(data.points)) return _pwEmptyState('nodata');
    let pts = data.points.filter(p => typeof p === 'number' && isFinite(p));
    if (pts.length > _PW_MAX_POINTS) pts = pts.slice(pts.length - _PW_MAX_POINTS);
    if (!pts.length) return _pwEmptyState('nodata');
    if (pts.length === 1) pts = [pts[0], pts[0]];
    const W = 140, H = 28, PAD = 2;
    let min = Math.min(...pts), max = Math.max(...pts);
    if (max === min) { min -= 1; max += 1; }
    const xs = (W - PAD * 2) / (pts.length - 1);
    const coords = pts.map((p, i) => {
      const x = PAD + i * xs;
      const y = PAD + (H - PAD * 2) * (1 - (p - min) / (max - min));
      return `${x.toFixed(2)},${y.toFixed(2)}`;
    }).join(' ');
    let html = '';
    const hasValue = (typeof data.value === 'number' && isFinite(data.value)) || (typeof data.value === 'string' && data.value !== '');
    const hasLabel = typeof data.label === 'string' && data.label !== '';
    if (hasValue || hasLabel) {
      html += `<div style="display:flex;align-items:baseline;gap:6px;margin-bottom:2px;">`;
      if (hasValue) html += `<span style="font-size:16px;font-weight:700;color:var(--text);">${_pwTrunc(typeof data.value === 'number' ? String(Number(data.value)) : data.value, 24)}</span>`;
      if (hasLabel) html += `<span style="font-size:9px;color:var(--text2);">${_pwTrunc(data.label, 40)}</span>`;
      html += `</div>`;
    }
    html += `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:${H}px;display:block;"><polyline fill="none" stroke="var(--accent,#6366f1)" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round" points="${coords}"/></svg>`;
    return html;
  } catch (_) {
    return _pwEmptyState('nodata');
  }
}

// Status → presentation. The plugin's status string is only ever used
// as a lookup key here; it is never interpolated into style/class.
const _PW_STATUS = {
  ok:      { color: 'var(--success,#10b981)', icon: '✓', fb: 'OK' },
  warn:    { color: 'var(--warning,#f59e0b)', icon: '⚠', fb: 'Warning' },
  error:   { color: 'var(--error,#ef4444)',   icon: '⛔', fb: 'Error' },
  unknown: { color: 'var(--text2)',           icon: '?', fb: 'Unknown' },
};

function _pwRenderStatusBadge(data) {
  try {
    if (!data || typeof data !== 'object' || Array.isArray(data)) return _pwEmptyState('nodata');
    const key = (typeof data.status === 'string' && Object.prototype.hasOwnProperty.call(_PW_STATUS, data.status)) ? data.status : 'unknown';
    const s = _PW_STATUS[key];
    const label = (typeof data.label === 'string' && data.label) ? data.label : s.fb;
    let html = `<div style="display:flex;align-items:center;gap:6px;">
    <span style="color:${s.color};font-size:14px;font-weight:700;">${s.icon}</span>
    <span style="color:${s.color};font-size:11px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${_pwTrunc(label, 40)}</span>
  </div>`;
    if (typeof data.detail === 'string' && data.detail) {
      html += `<div style="font-size:9px;color:var(--text2);margin-top:2px;">${_pwTrunc(data.detail, 120)}</div>`;
    }
    return html;
  } catch (_) {
    return _pwEmptyState('nodata');
  }
}

const _PW_TEMPLATED = {
  stat_tile: _pwRenderStatTile,
  table: _pwRenderTable,
  list: _pwRenderList,
  sparkline: _pwRenderSparkline,
  status_badge: _pwRenderStatusBadge,
};

// _pwRenderInto is the single dispatcher: render a pluginWidgetView into
// el. Markdown goes through the existing sanitizing _renderMarkdownFileInto
// (marked + DOMPurify), lazy-loading those libs first if needed; a
// per-element sequence number drops a stale async markdown render that
// finishes after a newer value was already rendered into the same el.
function _pwRenderInto(el, view) {
  if (!el) return;
  try {
    const seq = (el._pwSeq = (el._pwSeq || 0) + 1);
    const value = view && view.value;
    if (!value || typeof value !== 'object' || value.data === undefined || value.data === null) {
      el.innerHTML = _pwEmptyState('nodata');
      return;
    }
    const errHint = (value.error && typeof value.error === 'string')
      ? `<div style="text-align:right;font-size:9px;line-height:1;margin-top:2px;"><span style="color:var(--warning,#f59e0b);cursor:help;" title="${escHtml(value.error.slice(0, _PW_MAX_TITLE))}">⚠</span></div>`
      : '';
    const kind = view.kind;
    if (kind === 'markdown') {
      const d = value.data;
      const text = typeof d === 'string' ? d : (d && typeof d === 'object' && typeof d.text === 'string' ? d.text : '');
      if (!text) { el.innerHTML = _pwEmptyState('nodata') + errHint; return; }
      const render = () => {
        if (el._pwSeq !== seq) return;
        _renderMarkdownFileInto(el, text);
        // insertAdjacentHTML, not innerHTML +=, so pending mermaid slots stay attached.
        if (errHint && typeof el.insertAdjacentHTML === 'function') el.insertAdjacentHTML('beforeend', errHint);
      };
      if (typeof marked !== 'undefined' && typeof DOMPurify !== 'undefined') {
        render();
      } else {
        el.innerHTML = _pwEmptyState('loading');
        window._ensureMarkdownLibs().then(render).catch(e => {
          console.debug('plugin widget markdown render failed', e);
          if (el._pwSeq === seq) el.innerHTML = _pwEmptyState('unavailable');
        });
      }
      return;
    }
    const fn = Object.prototype.hasOwnProperty.call(_PW_TEMPLATED, kind) ? _PW_TEMPLATED[kind] : null;
    if (!fn) { el.innerHTML = _pwEmptyState('unavailable'); return; }
    el.innerHTML = fn(value.data) + errHint;
  } catch (e) {
    console.debug('plugin widget render failed', e);
    try { el.innerHTML = _pwEmptyState('unavailable'); } catch (_) {}
  }
}

// Dashboard card id for a plugin widget: 'plugin:<plugin-name>:<widget-id>'.
// The plugin name cannot contain ':', the widget id may.
function _pwCardId(plugin, widget) {
  return 'plugin:' + String(plugin) + ':' + String(widget);
}

function _pwParseCardId(id) {
  if (typeof id !== 'string' || id.indexOf('plugin:') !== 0) return null;
  const rest = id.slice('plugin:'.length);
  const i = rest.indexOf(':');
  if (i <= 0 || i === rest.length - 1) return null;
  return { plugin: rest.slice(0, i), widget: rest.slice(i + 1) };
}

// ── BL303 S5 — Dashboard Card Grid ───────────────────────────────────────────

// Card labels: a card with a labelKey resolves it through t() at render time
// so the Add-Card picker and the card header pick up the operator's locale;
// the static `label` doubles as the English fallback (same as before, just now
// optional per-card).
function _dashDefLabel(def) {
  if (!def) return '';
  if (def.labelKey) {
    const s = t(def.labelKey);
    if (s && s !== def.labelKey) return s;
  }
  return def.label || '';
}

const DASH_CARD_DEFS = [
  // GH#204 phase 4 — opt-in "Integration status" card: latest posted
  // scheduled-job results, one row per schedule. Listed FIRST in
  // DASH_CARD_DEFS so it sits at the very top of the Add-Card picker
  // (prominent, not buried); deliberately NOT part of DASH_DEFAULT_LAYOUT —
  // most installs have no named schedules and don't need it by default.
  { id: 'integration-status', label: 'Integration status', labelKey: 'dash_integ_status', icon: '🔌', defaultCs: 6,
    body: () => '<div id="dashIntegrationStatusCard" style="height:100%;overflow-y:auto;padding:6px 8px;font-size:11px;"></div>' },
  { id: 'tree',       label: 'Automata',       icon: '⣿',  defaultCs: 2,
    body: () => '<div id="dashTree" style="height:100%;overflow-y:auto;"></div>' },
  { id: 'orbital',    label: 'Network',         icon: '◎',  defaultCs: 6,
    body: () => '<svg id="constellationSvg" style="width:100%;height:100%;display:block;"></svg>' },
  { id: 'events',     label: 'Live Events',     icon: '⚡', defaultCs: 2,
    body: () => '<div id="dashEventFeed" style="height:100%;overflow-y:auto;font-family:monospace;font-size:10px;"></div>' },
  { id: 'sparklines', label: 'Sessions',        icon: '▬',  defaultCs: 2,
    body: () => '<canvas id="dashSparkCanvas" style="width:100%;height:100%;display:block;"></canvas>' },
  { id: 'gantt',      label: 'Timeline · 6h',  icon: '≡',  defaultCs: 12,
    body: () => '<div style="height:100%;overflow-y:auto;overflow-x:hidden;"><svg id="dashGanttSvg" style="display:block;width:100%;"></svg></div>' },
  { id: 'heatmap',    label: '30-Day Activity', icon: '🔥', defaultCs: 3,
    body: () => `<div style="position:relative;width:100%;height:100%;">
      <canvas id="dashHeatmapCanvas" style="width:100%;height:100%;display:block;"></canvas>
      <div id="dashHeatmapLoading" style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:var(--bg2);">${loadingEyeBlock()}</div>
    </div>` },
  { id: 'guardrails', label: 'Guardrails',      icon: '🛡',  defaultCs: 3,
    body: () => '<div id="dashGuardrailsCard" style="height:100%;overflow-y:auto;padding:6px 8px;"></div>' },
  { id: 'ekg',        label: 'Multi-EKG',       icon: '♡',  defaultCs: 6,
    body: () => '<div style="height:100%;display:flex;"><canvas id="ekgCanvas" style="flex:1;min-width:0;height:100%;display:block;"></canvas><div id="dashBurnRate" style="width:72px;flex-shrink:0;border-left:1px solid var(--border);display:flex;flex-direction:column;justify-content:center;align-items:flex-end;padding:0 6px;font-size:10px;font-family:monospace;color:var(--text2);"></div></div>' },
  { id: 'smoke',      label: 'Smoke Run',       icon: '🔬', defaultCs: 6,
    body: () => '<div id="dashSmokeCard" style="height:100%;display:flex;flex-direction:column;font-size:11px;user-select:none;"></div>' },
  // BL387 Phase 3 — memory scope stats tile.
  { id: 'memory-scope', label: 'Memory Scopes', icon: '🧠', defaultCs: 3,
    body: () => '<div id="dashMemoryScopeCard" style="height:100%;overflow-y:auto;padding:6px 8px;font-size:11px;"></div>' },
  // BL391 — multi-provider web search usage tile.
  { id: 'websearch-usage', label: 'Search Usage', icon: '🔎', defaultCs: 3,
    body: () => '<div id="dashWebSearchUsageCard" style="height:100%;overflow-y:auto;padding:6px 8px;font-size:11px;"></div>' },
];

const DASH_DEFAULT_LAYOUT = [
  { id: 'tree',         cs: 2,  rs: 2 },
  { id: 'orbital',      cs: 6,  rs: 2 },
  { id: 'events',       cs: 2,  rs: 2 },
  { id: 'sparklines',   cs: 2,  rs: 1 },
  { id: 'gantt',        cs: 12, rs: 1 },
  { id: 'heatmap',      cs: 3,  rs: 1 },
  { id: 'guardrails',   cs: 3,  rs: 1 },
  { id: 'memory-scope', cs: 3,  rs: 1 },
  { id: 'websearch-usage', cs: 3, rs: 1 },
  { id: 'ekg',          cs: 6,  rs: 2 },
  { id: 'smoke',        cs: 6,  rs: 2 },
];

function _dashLoadLayout() {
  if (_dash._layoutLoading) return;
  _dash._layoutLoading = true;
  apiFetch('/api/dashboard/layout').then(d => {
    if (d && Array.isArray(d.cards) && d.cards.length > 0) {
      _dash._layout = d.cards;
    } else {
      _dash._layout = DASH_DEFAULT_LAYOUT.map(c => ({ id: c.id, cs: c.cs }));
    }
    _dashBuildGrid(_dash._layout);
  }).catch(() => {
    _dash._layout = DASH_DEFAULT_LAYOUT.map(c => ({ id: c.id, cs: c.cs }));
    _dashBuildGrid(_dash._layout);
  }).finally(() => { _dash._layoutLoading = false; });
}

function _dashSaveLayout() {
  if (_dash._layoutSaving) return;
  _dash._layoutSaving = true;
  apiFetch('/api/dashboard/layout', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ cards: _dash._layout }),
  }).catch(() => {}).finally(() => { _dash._layoutSaving = false; });
}

const SPAN_CYCLE = [2, 3, 4, 6, 8, 12];
const ROW_CYCLE  = [1, 2];

function _dashCardHTML(entry) {
  // BL403 Phase 4 — plugin widget card. Plugin/widget ids are plugin-author
  // controlled, so every interpolation is escaped (escJsAttr inside the
  // single-quoted JS strings of the inline handlers).
  const pw = _pwParseCardId(entry.id);
  if (pw) {
    const cs = Math.floor(Number(entry.cs)) || 3;
    const rs = Math.floor(Number(entry.rs)) || 1;
    const jsId = escJsAttr(entry.id);
    return `<div class="dboard-card" data-cs="${cs}" data-rs="${rs}" data-card-id="${escHtml(entry.id)}" draggable="true"
    ondragstart="window._dashDragStart(event)" ondragover="window._dashDragOver(event)"
    ondrop="window._dashDrop(event)" ondragleave="window._dashDragLeave(event)"
    ondragend="window._dashDragEnd(event)">
    <div class="dboard-card-hdr">
      <span class="dboard-card-drag">⣿</span>
      <span class="dboard-card-title">🧩 ${escHtml(pw.widget)} <span style="color:var(--text2);font-weight:400;">${escHtml(pw.plugin)}</span></span>
      <span class="dboard-card-span" onclick="window._dashCycleSpan('${jsId}')" title="Width (click to cycle)">${cs}w</span>
      <span class="dboard-card-span" onclick="window._dashCycleRows('${jsId}')" title="Height (click to toggle 1/2 rows)">${rs}h</span>
      <button class="dboard-card-rm" onclick="window._dashRemoveCard('${jsId}')" title="Remove">×</button>
    </div>
    <div class="dboard-card-body"><div class="dboard-plugin-widget" data-plugin-card="${escHtml(entry.id)}" style="height:100%;overflow-y:auto;padding:6px 8px;font-size:11px;">${_pwEmptyState('loading')}</div></div>
  </div>`;
  }
  const def = DASH_CARD_DEFS.find(d => d.id === entry.id);
  if (!def) return '';
  const cs = entry.cs || def.defaultCs;
  const rs = entry.rs || 1;
  return `<div class="dboard-card" data-cs="${cs}" data-rs="${rs}" data-card-id="${entry.id}" draggable="true"
    ondragstart="window._dashDragStart(event)" ondragover="window._dashDragOver(event)"
    ondrop="window._dashDrop(event)" ondragleave="window._dashDragLeave(event)"
    ondragend="window._dashDragEnd(event)">
    <div class="dboard-card-hdr">
      <span class="dboard-card-drag">⣿</span>
      <span class="dboard-card-title">${def.icon} ${escHtml(_dashDefLabel(def))}</span>
      <span class="dboard-card-span" onclick="window._dashCycleSpan('${entry.id}')" title="Width (click to cycle)">${cs}w</span>
      <span class="dboard-card-span" onclick="window._dashCycleRows('${entry.id}')" title="Height (click to toggle 1/2 rows)">${rs}h</span>
      <button class="dboard-card-rm" onclick="window._dashRemoveCard('${entry.id}')" title="Remove">×</button>
    </div>
    <div class="dboard-card-body">${def.body()}</div>
  </div>`;
}

window._dashCycleSpan = function(cardId) {
  if (!_dash._editing) return;
  const entry = (_dash._layout || []).find(c => c.id === cardId);
  if (!entry) return;
  const idx = SPAN_CYCLE.indexOf(entry.cs);
  entry.cs = SPAN_CYCLE[(idx + 1) % SPAN_CYCLE.length];
  _dashBuildGrid(_dash._layout);
};

window._dashCycleRows = function(cardId) {
  if (!_dash._editing) return;
  const entry = (_dash._layout || []).find(c => c.id === cardId);
  if (!entry) return;
  const idx = ROW_CYCLE.indexOf(entry.rs || 1);
  entry.rs = ROW_CYCLE[(idx + 1) % ROW_CYCLE.length];
  _dashBuildGrid(_dash._layout);
};

function _dashBuildGrid(layout) {
  const grid = document.getElementById('dashCardGrid');
  if (!grid) return;
  // Issue #98 — at narrow viewports (<600px), override all cards to full width
  const narrowViewport = window.innerWidth < 600;
  const effectiveLayout = narrowViewport
    ? (layout || []).map(entry => Object.assign({}, entry, { cs: 12 }))
    : (layout || []);
  grid.innerHTML = effectiveLayout.map(_dashCardHTML).join('');
  _dashUpdateStatBar();
  _dashRenderTree();
  _dashRenderEventFeed();
  _dashRenderBurnRate();
  _dashRenderGuardrails();
  _dashRenderMemoryScope();
  _dashRenderWebSearchUsage();
  _dashRenderIntegrationStatus();
  _dashRenderPluginWidgets();
  _drawGantt();
  _dashForceStep();
  _drawConstellation();
}

window._dashStartEdit = function() {
  _dash._editing = true;
  const wrap = document.getElementById('dashboardWrap');
  if (wrap) wrap.classList.add('dboard-editing');
  const btn = document.getElementById('dashEditBtn');
  if (btn) { btn.textContent = '✓ Done'; btn.onclick = window._dashStopEdit; }
  const addBtn = document.getElementById('dashAddCardBtn');
  if (addBtn) addBtn.style.display = '';
};

window._dashStopEdit = function() {
  _dash._editing = false;
  const wrap = document.getElementById('dashboardWrap');
  if (wrap) wrap.classList.remove('dboard-editing');
  const btn = document.getElementById('dashEditBtn');
  if (btn) { btn.textContent = '✎ Edit'; btn.onclick = window._dashStartEdit; }
  const addBtn = document.getElementById('dashAddCardBtn');
  if (addBtn) addBtn.style.display = 'none';
  _dashSaveLayout();
};

window._dashRemoveCard = function(cardId) {
  if (!_dash._editing) return;
  _dash._layout = (_dash._layout || []).filter(c => c.id !== cardId);
  _dashBuildGrid(_dash._layout);
};

window._dashShowAddPanel = function() {
  const existing = (_dash._layout || []).map(c => c.id);
  let html = `<div class="dboard-add-panel" id="dashAddPanel">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
      <span style="font-weight:700;font-size:13px;color:var(--text);">Add Card</span>
      <button onclick="document.getElementById('dashAddPanel').remove()" style="background:none;border:none;color:var(--text2);cursor:pointer;font-size:18px;line-height:1;">×</button>
    </div>
    <div class="dboard-add-grid">`;
  for (const def of DASH_CARD_DEFS) {
    const used = existing.includes(def.id);
    html += `<div class="dboard-add-item${used ? ' dboard-add-used' : ''}"${used ? '' : ` onclick="window._dashAddCard('${def.id}');document.getElementById('dashAddPanel').remove();"`}>
      <span>${def.icon}</span><span>${escHtml(_dashDefLabel(def))}</span>
    </div>`;
  }
  html += `</div><div id="dashAddPluginSection"></div></div>`;
  const old = document.getElementById('dashAddPanel');
  if (old) old.remove();
  document.body.insertAdjacentHTML('beforeend', html);
  // BL403 Phase 4 — plugin widgets are appended once /api/plugins resolves;
  // on failure, or with none, the panel just keeps the built-in cards.
  apiFetch('/api/plugins').then(d => {
    const sec = document.getElementById('dashAddPluginSection');
    if (!sec) return;
    sec.innerHTML = _dashAddPanelPluginHTML(d && d.plugins, existing);
  }).catch(e => { console.debug('plugin list for add-card panel failed', e); });
};

// _dashAddPanelPluginHTML renders the Add Card panel's plugin widget
// section: every enabled plugin's dashboard-surface widgets. '' when none.
function _dashAddPanelPluginHTML(plugins, existing) {
  if (!Array.isArray(plugins)) return '';
  let items = '';
  for (const p of plugins) {
    if (!p || typeof p !== 'object' || p.enabled !== true || typeof p.name !== 'string' || !p.name) continue;
    if (!Array.isArray(p.widgets)) continue;
    for (const w of p.widgets) {
      if (!w || typeof w !== 'object' || w.surface !== 'dashboard' || typeof w.id !== 'string' || !w.id) continue;
      const cardId = _pwCardId(p.name, w.id);
      if (!_pwParseCardId(cardId)) continue;
      const used = (existing || []).includes(cardId);
      const jsId = escJsAttr(cardId);
      items += `<div class="dboard-add-item${used ? ' dboard-add-used' : ''}"${used ? '' : ` onclick="window._dashAddCard('${jsId}');document.getElementById('dashAddPanel').remove();"`}>
      <span>🧩</span><span>${escHtml(p.name)} · ${escHtml(w.id)}</span>
    </div>`;
    }
  }
  if (!items) return '';
  return `<div style="font-weight:700;font-size:12px;color:var(--text);margin:10px 0 6px;">${escHtml(t('dash_plugin_widgets_heading') || 'Plugin widgets')}</div>
    <div class="dboard-add-grid">${items}</div>`;
}

window._dashAddCard = function(cardId) {
  if (!_dash._editing) return;
  if (_pwParseCardId(cardId)) {
    _dash._layout = _dash._layout || [];
    if (_dash._layout.some(c => c.id === cardId)) return;
    _dash._layout.push({ id: cardId, cs: 3 });
    _dashBuildGrid(_dash._layout);
    return;
  }
  const def = DASH_CARD_DEFS.find(d => d.id === cardId);
  if (!def) return;
  _dash._layout = _dash._layout || [];
  _dash._layout.push({ id: cardId, cs: def.defaultCs });
  _dashBuildGrid(_dash._layout);
};

// ── BL403 Phase 4 — plugin widget cards: fetch + render ─────────────────────
// Each [data-plugin-card] element in the grid renders from a per-card cache
// (keyed by active server + card id) refreshed every max(10s, interval_seconds
// || 30s). The widget read endpoints don't check enabled, so a cached
// /api/plugins list (≤30s old) decides availability. Every failure path
// lands on the 'unavailable' empty state; nothing here may throw into the
// render tick.

const _DASH_PW_MIN_REFRESH_MS = 10000;
const _DASH_PW_DEFAULT_REFRESH_MS = 30000;
const _DASH_PW_LIST_TTL_MS = 30000;

function _dashPluginServerKey() {
  return String((typeof state !== 'undefined' && state && state.activeServer) || '');
}

function _dashRefreshPluginList() {
  const srv = _dashPluginServerKey();
  const pl = _dash._pluginList;
  if (_dash._pluginListInFlight) return;
  if (pl && pl.server === srv && Date.now() - pl.fetchedAt < _DASH_PW_LIST_TTL_MS) return;
  _dash._pluginListInFlight = true;
  let p;
  try {
    p = apiFetch('/api/plugins');
  } catch (e) {
    p = Promise.reject(e);
  }
  Promise.resolve(p).then(d => {
    _dash._pluginList = { server: srv, plugins: (d && Array.isArray(d.plugins)) ? d.plugins : [], fetchedAt: Date.now(), err: null };
  }, e => {
    _dash._pluginList = { server: srv, plugins: [], fetchedAt: Date.now(), err: String((e && e.message) || e || 'error') };
  }).finally(() => { _dash._pluginListInFlight = false; });
}

function _dashFetchPluginWidget(key, ref) {
  const cache = _dash._pluginWidgets;
  const entry = cache[key] || (cache[key] = { view: null, fetchedAt: 0, err: null, inFlight: false });
  if (entry.inFlight) return;
  entry.inFlight = true;
  let p;
  try {
    p = apiFetch('/api/plugins/' + encodeURIComponent(ref.plugin) + '/widgets/' + encodeURIComponent(ref.widget));
  } catch (e) {
    p = Promise.reject(e);
  }
  Promise.resolve(p).then(view => {
    entry.view = (view && typeof view === 'object') ? view : null;
    entry.err = entry.view ? null : 'empty response';
  }, e => {
    entry.err = String((e && e.message) || e || 'error');
  }).finally(() => {
    entry.fetchedAt = Date.now();
    entry.inFlight = false;
  });
}

function _dashPluginWidgetStale(entry) {
  if (!entry) return true;
  const secs = entry.view && Number(entry.view.interval_seconds);
  const ms = Math.max(_DASH_PW_MIN_REFRESH_MS, (secs > 0 ? secs * 1000 : _DASH_PW_DEFAULT_REFRESH_MS));
  return Date.now() - entry.fetchedAt >= ms;
}

// _dashPluginWidgetPaint writes html/view into el only when its render key
// changed (or the element is fresh from a grid rebuild).
function _dashPluginWidgetPaint(el, renderKey, view, emptyKind) {
  if (el._dashPwKey === renderKey) return;
  el._dashPwKey = renderKey;
  if (view) _pwRenderInto(el, view);
  else el.innerHTML = _pwEmptyState(emptyKind);
}

function _dashRenderPluginWidgetCard(el) {
  const id = el.getAttribute('data-plugin-card');
  const ref = _pwParseCardId(id);
  if (!ref) { _dashPluginWidgetPaint(el, 'unavailable', null, 'unavailable'); return; }
  const srv = _dashPluginServerKey();
  const pl = _dash._pluginList;
  const listReady = pl && pl.server === srv;
  if (listReady) {
    const plugin = pl.err ? null : pl.plugins.find(p => p && p.name === ref.plugin);
    if (!plugin || plugin.enabled === false) {
      _dashPluginWidgetPaint(el, 'unavailable', null, 'unavailable');
      return;
    }
  }
  const key = srv + '|' + id;
  const entry = _dash._pluginWidgets[key];
  if (_dashPluginWidgetStale(entry)) _dashFetchPluginWidget(key, ref);
  if (!listReady || !entry || (!entry.view && !entry.err)) {
    _dashPluginWidgetPaint(el, 'loading', null, 'loading');
    return;
  }
  const view = entry.view;
  if (entry.err || !view || view.surface !== 'dashboard') {
    _dashPluginWidgetPaint(el, 'unavailable', null, 'unavailable');
    return;
  }
  const v = view.value;
  const renderKey = 'v|' + String(view.kind) + '|' +
    (v && typeof v === 'object' ? String(v.updated_at) + '|' + String(v.error || '') : 'null');
  _dashPluginWidgetPaint(el, renderKey, view, null);
}

function _dashRenderPluginWidgets() {
  try {
    const grid = document.getElementById('dashCardGrid');
    if (!grid || typeof grid.querySelectorAll !== 'function') return;
    const els = grid.querySelectorAll('[data-plugin-card]');
    if (!els || !els.length) return;
    if (!_dash._pluginWidgets) _dash._pluginWidgets = {};
    _dashRefreshPluginList();
    for (const el of Array.from(els)) {
      try {
        _dashRenderPluginWidgetCard(el);
      } catch (e) {
        console.debug('plugin widget card render failed', e);
        try { el._dashPwKey = 'unavailable'; el.innerHTML = _pwEmptyState('unavailable'); } catch (_) {}
      }
    }
  } catch (e) {
    console.debug('plugin widget cards render failed', e);
  }
}

let _dashDragSrcId = null;

window._dashDragStart = function(e) {
  if (!_dash._editing) { e.preventDefault(); return; }
  _dashDragSrcId = e.currentTarget.dataset.cardId;
  e.currentTarget.classList.add('dboard-dragging');
  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', _dashDragSrcId);
};

window._dashDragOver = function(e) {
  if (!_dash._editing || !_dashDragSrcId) return;
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  if (e.currentTarget.dataset.cardId !== _dashDragSrcId) {
    e.currentTarget.classList.add('dboard-drag-over');
  }
};

window._dashDragLeave = function(e) {
  e.currentTarget.classList.remove('dboard-drag-over');
};

window._dashDrop = function(e) {
  e.preventDefault();
  const target = e.currentTarget;
  target.classList.remove('dboard-drag-over');
  const srcId = _dashDragSrcId;
  const tgtId = target.dataset.cardId;
  if (!srcId || !tgtId || srcId === tgtId) return;
  const layout = _dash._layout || [];
  const si = layout.findIndex(c => c.id === srcId);
  const ti = layout.findIndex(c => c.id === tgtId);
  if (si < 0 || ti < 0) return;
  const [moved] = layout.splice(si, 1);
  layout.splice(ti, 0, moved);
  _dashBuildGrid(layout);
};

window._dashDragEnd = function(e) {
  _dashDragSrcId = null;
  document.querySelectorAll('.dboard-dragging,.dboard-drag-over').forEach(el => {
    el.classList.remove('dboard-dragging', 'dboard-drag-over');
  });
};

// 30-day GitHub-style heatmap ————————————————————————————
function _drawHeatmap() {
  const canvas = document.getElementById('dashHeatmapCanvas');
  if (!canvas) return;
  const W = canvas.clientWidth || canvas.width || 240;
  const H = canvas.clientHeight || canvas.height || 90;
  if (canvas.width !== W) canvas.width = W;
  if (canvas.height !== H) canvas.height = H;
  const ctx = canvas.getContext('2d');
  const css = getComputedStyle(document.documentElement);
  const bg2 = css.getPropertyValue('--bg2').trim() || '#161b2e';
  const bdr = css.getPropertyValue('--border').trim() || '#2d3148';
  const acc = css.getPropertyValue('--accent').trim() || '#7c3aed';
  const txt2 = css.getPropertyValue('--text2').trim() || '#64748b';
  ctx.fillStyle = bg2;
  ctx.fillRect(0, 0, W, H);
  const buckets = _dash._heatmapData || [];
  const loadingEl = document.getElementById('dashHeatmapLoading');
  if (buckets.length === 0) {
    if (loadingEl) loadingEl.style.display = 'flex';
    return;
  }
  if (loadingEl) loadingEl.style.display = 'none';

  // Issue #101 — narrow mode: card width < 300px → 7-day bar chart
  const cardEl = canvas.closest('[data-card-id="heatmap"]');
  const cardCs = cardEl ? parseInt(cardEl.getAttribute('data-cs') || '3', 10) : 3;
  const narrowMode = W < 300 || cardCs <= 3;

  if (narrowMode) {
    // 7-day vertical bar chart
    const last7 = buckets.slice(-7);
    const maxTotal = Math.max(1, ...last7.map(b => b.total || b.session_count || 0));
    const PAD = 6;
    const barCount = last7.length;
    const barGap = 2;
    const barW = Math.max(4, Math.floor((W - PAD * 2 - barGap * (barCount - 1)) / barCount));
    for (let i = 0; i < barCount; i++) {
      const b = last7[i];
      const total = b.total || b.session_count || 0;
      const errors = (b.failed || 0) + (b.killed || 0);
      const errRate = total ? errors / total : 0;
      let fill;
      if (!total) {
        fill = bdr;
      } else if (errRate > 0.2) {
        fill = 'rgba(239,68,68,0.8)';
      } else if (errRate >= 0.05) {
        fill = 'rgba(245,158,11,0.8)';
      } else {
        fill = 'rgba(16,185,129,0.8)';
      }
      const barH = Math.max(2, Math.round((total / maxTotal) * (H - PAD * 2)));
      const x = PAD + i * (barW + barGap);
      const y = H - PAD - barH;
      ctx.fillStyle = fill;
      ctx.beginPath();
      if (ctx.roundRect) ctx.roundRect(x, y, barW, barH, 2);
      else ctx.rect(x, y, barW, barH);
      ctx.fill();
    }
    // "7d" label bottom-right
    ctx.fillStyle = txt2; ctx.font = '8px monospace';
    ctx.textAlign = 'right';
    ctx.fillText('7d', W - 3, H - 2);
    ctx.textAlign = 'left';
    return;
  }

  const COLS = Math.min(buckets.length, 30);
  const PAD = 10, LBL_H = 14;
  const cellPad = 2;
  const cellW = Math.max(4, Math.floor((W - PAD * 2) / COLS) - cellPad);
  const cellH = Math.max(4, H - PAD * 2 - LBL_H);
  const maxCount = Math.max(1, ...buckets.map(b => b.session_count || 0));
  for (let i = 0; i < COLS; i++) {
    const b = buckets[buckets.length - COLS + i];
    const x = PAD + i * (cellW + cellPad);
    const errors = (b.failed || 0) + (b.killed || 0);
    const errRate = b.session_count ? errors / b.session_count : 0;
    let fill;
    if (!b.session_count) {
      fill = bdr;
    } else if (errRate > 0.3) {
      fill = 'rgba(239,68,68,0.7)';
    } else {
      const t = b.session_count / maxCount;
      fill = t < 0.25 ? 'rgba(124,58,237,0.25)' : t < 0.5 ? 'rgba(124,58,237,0.5)' : t < 0.75 ? 'rgba(124,58,237,0.75)' : acc;
    }
    ctx.fillStyle = fill;
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(x, PAD, cellW, cellH, 2);
    else ctx.rect(x, PAD, cellW, cellH);
    ctx.fill();
  }
  ctx.fillStyle = txt2; ctx.font = '8px monospace';
  for (let i = 0; i < COLS; i += 7) {
    const b = buckets[buckets.length - COLS + i];
    if (!b) continue;
    ctx.fillText((b.date || '').slice(5), PAD + i * (cellW + cellPad), PAD + cellH + 10);
  }
  const total = buckets.reduce((n, b) => n + (b.session_count || 0), 0);
  ctx.textAlign = 'right';
  ctx.fillText(`${total} / 30d`, W - PAD, PAD + cellH + 10);
  ctx.textAlign = 'left';
}

// Guardrail verdicts bar chart ————————————————————————————
function _dashRenderGuardrails() {
  const el = document.getElementById('dashGuardrailsCard');
  if (!el) return;
  let block = 0, warn = 0, pass = 0;
  const byRule = {};
  for (const b of Object.values(_dash._boards)) {
    const gv = (b.telemetry && b.telemetry.guardrail_verdicts) || [];
    for (const v of gv) {
      if (v.outcome === 'block') block++;
      else if (v.outcome === 'warn') warn++;
      else pass++;
      const r = v.rule_id || v.rule || 'unknown';
      if (!byRule[r]) byRule[r] = { block: 0, warn: 0, pass: 0 };
      byRule[r][v.outcome === 'block' ? 'block' : v.outcome === 'warn' ? 'warn' : 'pass']++;
    }
  }
  const total = block + warn + pass;
  if (total === 0) {
    el.innerHTML = `<div style="color:var(--text2);font-size:10px;padding:4px 0;">No verdicts yet</div>`;
    return;
  }
  let html = `<div style="display:flex;gap:10px;margin-bottom:6px;">
    <span style="color:var(--error,#ef4444);font-size:11px;font-weight:700;">⛔ ${block}</span>
    <span style="color:var(--warning,#f59e0b);font-size:11px;font-weight:700;">⚠ ${warn}</span>
    <span style="color:var(--success,#10b981);font-size:11px;font-weight:700;">✓ ${pass}</span>
  </div>`;
  const rules = Object.entries(byRule).sort((a, b2) => (b2[1].block + b2[1].warn) - (a[1].block + a[1].warn));
  const maxV = Math.max(1, ...rules.map(([, v]) => v.block + v.warn + v.pass));
  for (const [rule, v] of rules.slice(0, 8)) {
    const tot = v.block + v.warn + v.pass;
    const pct = Math.round(tot / maxV * 100);
    const color = v.block > 0 ? 'var(--error,#ef4444)' : v.warn > 0 ? 'var(--warning,#f59e0b)' : 'var(--success,#10b981)';
    html += `<div style="margin-bottom:5px;">
      <div style="font-size:9px;color:var(--text2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escHtml(rule)}">${escHtml(rule.length > 28 ? rule.slice(0, 27) + '…' : rule)}</div>
      <div style="height:5px;background:var(--border);border-radius:2px;margin-top:2px;">
        <div style="height:100%;width:${pct}%;background:${color};border-radius:2px;"></div>
      </div>
    </div>`;
  }
  el.innerHTML = html;
}

// Memory scope stats card (BL387 Phase 3) — shows scope inventory counts from
// /api/memory/stats. Refreshed on every dashboard tick. State is kept in _dash._memStats.
if (!_dash._memStats) _dash._memStats = null;

function _dashFetchMemoryStats() {
  apiFetch('/api/memory/stats').then(d => {
    _dash._memStats = d || null;
    _dashRenderMemoryScope();
  }).catch(() => {});
}

function _dashRenderMemoryScope() {
  const el = document.getElementById('dashMemoryScopeCard');
  if (!el) return;
  const d = _dash._memStats;
  if (!d) {
    el.innerHTML = `<div style="color:var(--text2);font-size:10px;padding:4px 0;">${escHtml(t('memory_stats_unavailable') || 'Memory stats unavailable')}</div>`;
    _dashFetchMemoryStats();
    return;
  }
  const total = d.total_entries || 0;
  const scopes = d.scopes || {};
  const scopeOrder = ['session-local','story-shared','prd-shared','project-shared','persona-in-project','persona-global'];
  const scopeRows = scopeOrder
    .filter(k => scopes[k] !== undefined)
    .map(k => ({ key: k, n: scopes[k] }));
  // Include any scope not in the canonical order
  for (const k of Object.keys(scopes)) {
    if (!scopeOrder.includes(k)) scopeRows.push({ key: k, n: scopes[k] });
  }
  const maxN = Math.max(1, ...scopeRows.map(r => r.n));
  let html = `<div style="display:flex;align-items:baseline;gap:6px;margin-bottom:6px;">
    <span style="font-size:16px;font-weight:700;color:var(--text);">${total}</span>
    <span style="font-size:9px;color:var(--text2);">total entries</span>
  </div>`;
  for (const { key, n } of scopeRows) {
    const pct = Math.round(n / maxN * 100);
    const label = key.replace(/-/g, ' ');
    html += `<div style="margin-bottom:5px;">
      <div style="display:flex;justify-content:space-between;font-size:9px;color:var(--text2);margin-bottom:2px;">
        <span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escHtml(key)}">${escHtml(label)}</span>
        <span style="flex-shrink:0;margin-left:4px;color:var(--text);">${n}</span>
      </div>
      <div style="height:4px;background:var(--border);border-radius:2px;">
        <div style="height:100%;width:${pct}%;background:var(--accent,#6366f1);border-radius:2px;"></div>
      </div>
    </div>`;
  }
  el.innerHTML = html;
}

// BL391 — multi-provider web search usage tile (Dashboard).
if (!_dash._webSearchStats) _dash._webSearchStats = null;

function _dashFetchWebSearchStats() {
  apiFetch('/api/websearch/stats?days=14').then(d => {
    _dash._webSearchStats = d || null;
    _dashRenderWebSearchUsage();
  }).catch(() => {});
}

function _dashRenderWebSearchUsage() {
  const el = document.getElementById('dashWebSearchUsageCard');
  if (!el) return;
  const d = _dash._webSearchStats;
  if (!d) {
    el.innerHTML = `<div style="color:var(--text2);font-size:10px;padding:4px 0;">${escHtml(t('websearch_stats_unavailable') || 'Search usage stats unavailable')}</div>`;
    _dashFetchWebSearchStats();
    return;
  }
  const sum = d.summary || {};
  const series = (d.daily_series || []).map(p => p.count || 0);
  const providers = sum.providers || [];
  let html = `<div style="display:flex;align-items:baseline;gap:6px;margin-bottom:2px;">
    <span style="font-size:16px;font-weight:700;color:var(--text);">${sum.total||0}</span>
    <span style="font-size:9px;color:var(--text2);">${escHtml(t('websearch_total_searches')||'total searches')}</span>
  </div>
  <div style="display:flex;gap:10px;font-size:9px;color:var(--text2);margin-bottom:6px;">
    <span>${escHtml(t('websearch_today')||'today')}: <b style="color:var(--text);">${sum.today||0}</b></span>
    <span>${escHtml(t('websearch_week')||'week')}: <b style="color:var(--text);">${sum.this_week||0}</b></span>
    <span>${escHtml(t('websearch_month')||'month')}: <b style="color:var(--text);">${sum.this_month||0}</b></span>
    <span>${escHtml(t('websearch_cache')||'cached')}: <b style="color:var(--text);">${sum.cache_hits||0}</b></span>
  </div>`;
  if (series.length >= 2) {
    html += `<div style="margin-bottom:6px;">${_sparkline(series, 140, 28, 'var(--accent,#6366f1)')}</div>`;
  }
  if (!providers.length) {
    html += `<div style="color:var(--text2);font-size:10px;">${escHtml(d.enabled ? (t('websearch_no_providers')||'No providers configured') : (t('websearch_disabled')||'Web search disabled'))}</div>`;
  } else {
    const maxN = Math.max(1, ...providers.map(p => p.total||0));
    for (const p of providers) {
      const n = p.total || 0;
      const pct = Math.round(n / maxN * 100);
      html += `<div style="margin-bottom:5px;">
        <div style="display:flex;justify-content:space-between;font-size:9px;color:var(--text2);margin-bottom:2px;">
          <span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escHtml(p.name)}">${escHtml(p.name)}${p.errors?` <span style="color:var(--error,#ef4444);">(${p.errors} err)</span>`:''}</span>
          <span style="flex-shrink:0;margin-left:4px;color:var(--text);">${n}</span>
        </div>
        <div style="height:4px;background:var(--border);border-radius:2px;">
          <div style="height:100%;width:${pct}%;background:var(--accent,#6366f1);border-radius:2px;"></div>
        </div>
      </div>`;
    }
  }
  el.innerHTML = html;
}

// ── GH#204 phase 4 — "Integration status" card ──────────────────────────────
// Opt-in dashboard card (NOT in DASH_DEFAULT_LAYOUT) surfacing the posted
// results of scheduled jobs / external integrations: one row per schedule
// with its latest status, escaped summary, posted time, an inline SVG
// sparkline of its retained recent statuses (oldest → newest), the retained
// count, and a click-through into the session that posted the latest result.
//
// Mechanism: same cadence and machinery as the other cached dashboard cards
// (web-search usage, memory scope): render runs inside the shared
// _dashLoop rAF cycle (same % 12 gate as _dashRenderWebSearchUsage), the
// fetch is throttled to at most one per ~30s, and it (re)renders on
// completion. No setInterval anywhere — nothing to stack, one loop only.
//
// Data: GET /api/schedule-results → [{ schedule_name, latest: { payload:
//   { title, status, summary, … }, session_id, posted_at }, count,
//   recent_statuses: […oldest→newest] }].
//
// Security: schedule_name / payload fields are agent- or operator-authored
// and treated as untrusted — every interpolation goes through escHtml / 
// escJsAttr, same discipline as the per-session result card (result_payload
// tests) and the SEC-021 sanitize pipeline.
const INTEG_MIN_REFETCH_MS = 30000;
const INTEG_SPARK_MAX = 60; // sparkline dots are bounded even if a history is longer

// Initialize once (the _dash object above is a plain literal; keep the extra
// bookkeeping fields in one place).
_dash._integResults = null;   // Array | null (null = not fetched yet)
_dash._integError = null;     // string | null (last fetch failure)
_dash._integFetchedAt = 0;    // Date.now() of the last attempted fetch

function _integDotColor(status) {
  const s = String(status || '').toLowerCase();
  if (s === 'ok') return 'var(--success,#10b981)';
  if (s === 'warn') return 'var(--warning,#f59e0b)';
  if (s === 'error') return 'var(--error,#ef4444)';
  return 'var(--text2,#94a3b8)';
}

// _integSparklineSVG renders the retained recent statuses (oldest → newest) as
// a small inline SVG: one color-coded bar per result, bounded to
// INTEG_SPARK_MAX (newest wins) so a long history can't produce a giant SVG.
// Empty/unknown input → '' (no svg at all).
function _integSparklineSVG(statuses) {
  const list = (Array.isArray(statuses) ? statuses : []).slice(-INTEG_SPARK_MAX);
  if (!list.length) return '';
  const width = 160, height = 12;
  const step = Math.min(6, width / list.length);
  const bar = Math.min(4, Math.max(1.5, step * 0.6));
  const bars = list.map((st, i) => {
    const x = Math.max(0, i * step + (step - bar) / 2);
    const title = escHtml(String(st == null ? '—' : st));
    return `<rect x="${x.toFixed(1)}" y="1" width="${bar.toFixed(1)}" height="${height - 2}" rx="${(bar / 2).toFixed(1)}" fill="${_integDotColor(st)}" opacity="0.9"><title>${title}</title></rect>`;
  }).join('');
  return `<svg width="${width}" height="${height}" style="flex-shrink:0;display:block;" aria-hidden="true">${bars}</svg>`;
}

// _integRow renders one schedule's row. `item` is one element of the
// /api/schedule-results list; every untrusted string is escaped; the row is
// click-through into the posting session (status tab) when a session_id is
// present. Defensive about every field: a missing latest/payload still
// renders a name-only row instead of throwing.
function _integRow(item) {
  if (!item || typeof item !== 'object') return '';
  const name = escHtml(item.schedule_name || '');
  const latest = (item.latest && typeof item.latest === 'object') ? item.latest : null;
  const payload = (latest && latest.payload && typeof latest.payload === 'object') ? latest.payload : {};
  const st = String(payload.status || '').toLowerCase();
  let badge = '';
  if (st === 'ok' || st === 'warn' || st === 'error') {
    // Closed status set (result contract) — reuse the status-tab keys, all
    // present in the five locale bundles.
    const label = st === 'ok' ? (t('status_result_ok') || 'ok')
      : st === 'warn' ? (t('status_result_warn') || 'warn')
      : (t('status_result_error') || 'error');
    badge = `<span class="integ-badge" style="display:inline-flex;align-items:center;gap:4px;font-size:9px;font-weight:600;color:var(--text2);white-space:nowrap;flex-shrink:0;">` +
      `<span class="integ-dot" style="width:8px;height:8px;border-radius:50%;flex-shrink:0;background:${_integDotColor(st)};"></span>${escHtml(label)}</span>`;
  }
  const summary = payload.summary ? `<span class="integ-summary" style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text2,#94a3b8);" title="${escHtml(payload.summary)}">${escHtml(payload.summary)}</span>` : '';
  const title = payload.title ? `<span class="integ-title" style="font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex-shrink:0;max-width:40%;">${escHtml(payload.title)}</span>` : '';
  const when = (latest && latest.posted_at) ? timeAgo(latest.posted_at) : '';
  const time = when ? `<span class="integ-time" style="font-size:10px;color:var(--text2,#94a3b8);white-space:nowrap;flex-shrink:0;">${escHtml(when)}</span>` : '';
  const countN = Number(item.count) || 0;
  let count = '';
  if (countN > 1) {
    const m = t('dash_integ_retained', [countN]);
    count = `<span class="integ-count" style="font-size:10px;color:var(--text2,#94a3b8);white-space:nowrap;flex-shrink:0;">${escHtml(m !== 'dash_integ_retained' ? m : countN + ' retained')}</span>`;
  }
  const sid = (latest && latest.session_id) ? String(latest.session_id) : '';
  const click = sid ? `onclick="window._integOpenSession('${escJsAttr(sid)}')"` : '';
  return `<div class="integ-row" ${click} title="${escHtml(t('dash_integ_open') || 'Open the session that posted this result')}" style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-bottom:1px solid var(--border,#1e293b);${sid ? 'cursor:pointer;' : ''}">` +
    `<span class="integ-name" style="font-weight:600;white-space:nowrap;flex-shrink:0;max-width:30%;overflow:hidden;text-overflow:ellipsis;" title="${name}">${name}</span>` +
    badge + title + summary + time + _integSparklineSVG(item.recent_statuses) + count +
    `</div>`;
}

// _integHowtoLink — the empty/error states point operators at the
// API reference (POST /api/sessions/{session_id}/result is documented
// there today; a dedicated result-posting howto is a follow-up item).
function _integHowtoLink() {
  const label = escHtml(t('dash_integ_empty_link', [])
    ? t('dash_integ_empty_link') : 'See the result endpoint in the API reference');
  return `<a href="/api/openapi.yaml" target="_blank" rel="noopener" style="color:var(--accent2,#60a5fa);text-decoration:underline;" title="API reference — POST /api/sessions/{session_id}/result">${label}</a>`;
}

function _integEmptyHTML() {
  return `<div class="integ-empty" style="color:var(--text2,#94a3b8);padding:6px 2px;line-height:1.6;">
    <div style="font-weight:700;color:var(--text);">${escHtml(t('dash_integ_empty_title') || 'No results yet')}</div>
    <div style="margin-top:4px;">${escHtml(t('dash_integ_empty') || 'Scheduled jobs can post their results here. From inside one, POST /api/sessions/{id}/result with the job\'s own credential and a payload of title, status (ok/warn/error) and an optional summary.')}</div>
    <div style="margin-top:6px;">${_integHowtoLink()}</div>
  </div>`;
}

function _integErrorHTML() {
  return `<div class="integ-error" style="color:var(--text2,#94a3b8);padding:6px 2px;line-height:1.6;">
    <div style="font-weight:700;color:var(--text);">${escHtml(t('dash_integ_error') || "Couldn't load the results yet.")}</div>
    <div style="margin-top:6px;">${_integHowtoLink()}</div>
  </div>`;
}

// _dashFetchIntegStatus pulls the per-schedule summary list and re-renders.
// Throttled: never more than one in-flight request, and re-fetches are only
// attempted at most once per INTEG_MIN_REFETCH_MS (the "same cadence" rule,
// without any extra timer).
function _dashFetchIntegStatus() {
  if (_dash._integFetching) return Promise.resolve();
  _dash._integFetching = true;
  _dash._integFetchedAt = Date.now();
  return apiFetch('/api/schedule-results').then(d => {
    _dash._integResults = Array.isArray(d) ? d : null;
    _dash._integError = null;
    _dashRenderIntegrationStatus();
  }).catch(e => {
    _dash._integError = String((e && e.message) || e || 'fetch failed');
    if (!_dash._integResults) _dashRenderIntegrationStatus();
  }).finally(() => { _dash._integFetching = false; });
}

// _dashRenderIntegrationStatus renders #dashIntegrationStatusCard from the
// cached list. Runs on the shared loop gate; when the cache is cold it kicks
// the (throttled) fetch itself so the first paint is never stuck at loading.
function _dashRenderIntegrationStatus() {
  const el = document.getElementById('dashIntegrationStatusCard');
  if (!el) return;
  const cold = !_dash._integResults && !_dash._integError;
  const stale = Date.now() - (_dash._integFetchedAt || 0) >= INTEG_MIN_REFETCH_MS;
  if (cold) {
    el.innerHTML = `<div class="integ-loading" style="color:var(--text2,#94a3b8);font-size:10px;padding:4px 0;">${escHtml(t('dash_integ_loading') || 'Loading results…')}</div>`;
    if (stale || !(_dash._integFetchedAt)) _dashFetchIntegStatus();
    return;
  }
  if (_dash._integError && !_dash._integResults) {
    el.innerHTML = _integErrorHTML();
    if (stale) _dashFetchIntegStatus();
    return;
  }
  el.innerHTML = _dash._integResults.length ? _dash._integResults.map(_integRow).join('') : _integEmptyHTML();
  if (stale) _dashFetchIntegStatus();
}

// Click-through: open the posting session's Status tab (the per-session
// result card) — same deep-link the status-tab result card uses for itself.
window._integOpenSession = function(sessionId) {
  if (!sessionId) return;
  if (typeof window.gotoSessionStatus === 'function') window.gotoSessionStatus(sessionId);
  else navigate('session-detail', sessionId);
};

// Smoke run progress card — multi-envelope (BL303 S5 rev2)
// State: _dash._smokeEnvelopes (array), _dash._smokeExpandedId, _dash._smokeExpandedData, _dash._smokeFilter

if (!_dash._smokeFilter) _dash._smokeFilter = 'all';
if (!_dash._smokeEnvelopes) _dash._smokeEnvelopes = [];

function _smokeDeleteRun(id) {
  fetch('/api/smoke/progress/' + encodeURIComponent(id), { method: 'DELETE', headers: tokenHeader() })
    .then(() => {
      _dash._smokeEnvelopes = (_dash._smokeEnvelopes || []).filter(e => e.id !== id);
      if (_dash._smokeExpandedId === id) { _dash._smokeExpandedId = null; _dash._smokeExpandedData = null; }
      _dashRenderSmoke();
    }).catch(() => {});
}
window._smokeDeleteRun = _smokeDeleteRun;

function _smokeDeleteAll() {
  fetch('/api/smoke/progress', { method: 'DELETE', headers: tokenHeader() })
    .then(() => { _dash._smokeEnvelopes = []; _dash._smokeExpandedId = null; _dash._smokeExpandedData = null; _dashRenderSmoke(); })
    .catch(() => {});
}
window._smokeDeleteAll = _smokeDeleteAll;

function _smokeSelectRun(id) {
  if (_dash._smokeExpandedId === id) {
    _dash._smokeExpandedId = null; _dash._smokeExpandedData = null;
  } else {
    _dash._smokeExpandedId = id;
    _dash._smokeExpandedData = null;
    // Fetch detail immediately
    fetch('/api/smoke/progress/' + encodeURIComponent(id)).then(r => r.ok ? r.json() : null)
      .then(d => { if (d) { _dash._smokeExpandedData = d; _dashRenderSmoke(); } }).catch(() => {});
  }
  _dashRenderSmoke();
}
window._smokeSelectRun = _smokeSelectRun;

function _smokSetFilter(f) { _dash._smokeFilter = f; _dashRenderSmoke(); }
window._smokSetFilter = _smokSetFilter;

function _dashRenderSmoke() {
  const el = document.getElementById('dashSmokeCard');
  if (!el) return;

  const envelopes = _dash._smokeEnvelopes || [];
  if (envelopes.length === 0) {
    el.innerHTML = `<div style="padding:12px;color:var(--text2);font-size:11px;">No runs — start <code>release-smoke.sh</code> or <code>run-tests.sh</code></div>`;
    return;
  }

  // ── Envelope list (top section) ──────────────────────────────────────────
  const envRow = (e) => {
    const sel = _dash._smokeExpandedId === e.id;
    const pct = Math.min(100, Math.round(e.pct || 0));
    const barCol = e.fail > 0 ? 'var(--error,#ef4444)' : e.active ? 'var(--warning,#f59e0b)' : 'var(--success,#10b981)';
    const typeTag = e.type === 'e2e' ? 'E2E' : 'SMOKE';
    const typeCol = e.type === 'e2e' ? '#6366f1' : '#0891b2';
    const timeStr = e.updated_at ? new Date(e.updated_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : '';
    const status = e.active ? '▶' : e.fail > 0 ? '✗' : '✓';
    const statusCol = e.active ? 'var(--warning,#f59e0b)' : e.fail > 0 ? 'var(--error,#ef4444)' : 'var(--success,#10b981)';
    const bg = sel ? 'var(--accent-subtle,rgba(99,102,241,0.08))' : 'transparent';
    const border = sel ? '2px solid var(--accent)' : '2px solid transparent';
    return `<div onclick="_smokeSelectRun('${escHtml(e.id)}')" style="display:flex;align-items:center;gap:6px;padding:5px 8px;cursor:pointer;background:${bg};border-left:${border};border-bottom:1px solid var(--border);">
      <span style="color:${statusCol};font-size:12px;flex-shrink:0;">${status}</span>
      <span style="font-size:9px;font-weight:700;color:#fff;background:${typeCol};padding:1px 4px;border-radius:3px;flex-shrink:0;">${typeTag}</span>
      <span style="font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;">${escHtml(e.version || e.id)}</span>
      <span style="font-size:9px;color:var(--text2);flex-shrink:0;">${e.pass}✓ ${e.fail>0?e.fail+'✗ ':''}${timeStr}</span>
      <div style="width:36px;height:4px;background:var(--border);border-radius:2px;flex-shrink:0;">
        <div style="height:100%;width:${pct}%;background:${barCol};border-radius:2px;"></div>
      </div>
      <button onclick="event.stopPropagation();_smokeDeleteRun('${escHtml(e.id)}')" title="Delete" style="background:none;border:none;color:var(--text2);cursor:pointer;font-size:11px;padding:0 2px;flex-shrink:0;">✕</button>
    </div>`;
  };

  const listHeight = envelopes.length > 1 ? Math.min(envelopes.length * 38, 120) : 38;
  const envListHtml = `<div style="flex-shrink:0;border-bottom:2px solid var(--border);overflow-y:auto;max-height:${listHeight}px;">
    ${envelopes.map(envRow).join('')}
    ${envelopes.length > 1 ? `<div style="padding:2px 8px;display:flex;justify-content:flex-end;"><button onclick="_smokeDeleteAll()" style="background:none;border:none;color:var(--text2);cursor:pointer;font-size:9px;padding:2px 4px;">Clear all</button></div>` : ''}
  </div>`;

  // ── Expanded detail panel ────────────────────────────────────────────────
  let detailHtml = '';
  if (_dash._smokeExpandedId) {
    const d = _dash._smokeExpandedData;
    if (!d) {
      detailHtml = `<div style="padding:12px;color:var(--text2);font-size:11px;">${loadingEyeBlock()}</div>`;
    } else {
      const pass = d.pass || 0, fail = d.fail || 0, skip = d.skip || 0;
      const secs = d.sections || [];
      const total = d.total || 82;
      const done = secs.length > 0 ? secs.length : (pass + fail + skip);
      const remaining = Math.max(0, total - done - (d.active ? 1 : 0));
      const pct = Math.min(100, total > 0 ? Math.round(done / total * 100) : 0);
      const barColor = fail > 0 ? 'var(--error,#ef4444)' : d.active ? 'var(--warning,#f59e0b)' : 'var(--success,#10b981)';

      // Filter pills
      const filt = _dash._smokeFilter || 'all';
      const pill = (k, label) => `<span onclick="_smokSetFilter('${k}')" style="display:inline-block;padding:2px 7px;border-radius:10px;font-size:9px;cursor:pointer;border:1px solid ${filt===k?'var(--accent)':'var(--border)'};background:${filt===k?'var(--accent)':'transparent'};color:${filt===k?'var(--bg)':'var(--text2)'};">${label}</span>`;

      let allRows = [];
      if (d.active && d.current_id) allRows.push({ id: d.current_id, name: d.current_name || d.current_id, result: 'active' });
      for (const s of secs) allRows.push(s);

      // When sections is empty but pass/fail/skip counts exist, create synthetic rows for filtering
      if (secs.length === 0 && (pass > 0 || fail > 0 || skip > 0)) {
        if (pass > 0) allRows.push({ id: '_pass', name: `${pass} tests passed`, result: 'pass' });
        if (fail > 0) allRows.push({ id: '_fail', name: `${fail} tests failed`, result: 'fail' });
        if (skip > 0) allRows.push({ id: '_skip', name: `${skip} tests skipped`, result: 'skip' });
      }

      let filtered;
      if (filt === 'all') filtered = allRows;
      else if (filt === 'pending') filtered = []; // pending has no rows; count shown separately
      else filtered = allRows.filter(s => s.result === filt);

      const sRow = (s) => {
        let col, icon, bg = 'transparent';
        if (s.result === 'fail') { col = 'var(--error,#ef4444)'; icon = '✗'; bg = 'rgba(239,68,68,0.06)'; }
        else if (s.result === 'skip') { col = 'var(--text2)'; icon = '⏭'; }
        else if (s.result === 'active') { col = 'var(--warning,#f59e0b)'; icon = '▶'; bg = 'rgba(245,158,11,0.08)'; }
        else { col = 'var(--success,#10b981)'; icon = '✓'; }
        return `<div style="display:flex;align-items:center;gap:5px;padding:4px 8px;background:${bg};border-bottom:1px solid var(--border);" title="${escHtml(s.name||s.id||'')}">
          <span style="color:${col};flex-shrink:0;font-size:11px;width:12px;text-align:center;">${icon}</span>
          <span style="font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:${s.result==='skip'?'var(--text2)':'var(--text)'};">${escHtml(s.name||s.id||'')}</span>
        </div>`;
      };

      let rowsHtml;
      if (filt === 'pending' && remaining > 0) rowsHtml = `<div style="padding:8px;color:var(--text2);font-size:10px;">⏳ ${remaining} pending</div>`;
      else if (filtered.length === 0) rowsHtml = `<div style="padding:8px;color:var(--text2);font-size:10px;">— none —</div>`;
      else {
        rowsHtml = filtered.map(sRow).join('');
        if (filt === 'all' && remaining > 0) rowsHtml += `<div style="padding:4px 8px;color:var(--text2);font-size:10px;font-style:italic;">⏳ ${remaining} pending</div>`;
      }

      // Issue #99 — narrow smoke card mobile layout
      const smokeCardW = el.clientWidth || 0;
      const smokeNarrow = smokeCardW > 0 && smokeCardW < 480;
      const pillsStyle = smokeNarrow
        ? 'display:flex;gap:3px;flex-wrap:nowrap;overflow-x:auto;white-space:nowrap;padding:3px 8px;border-bottom:1px solid var(--border);flex-shrink:0;-webkit-overflow-scrolling:touch;'
        : 'display:flex;gap:3px;flex-wrap:wrap;padding:3px 8px;border-bottom:1px solid var(--border);flex-shrink:0;';
      const detailPaneStyle = smokeNarrow
        ? 'flex:1;min-height:0;display:flex;flex-direction:column;overflow-x:auto;-webkit-overflow-scrolling:touch;'
        : 'flex:1;min-height:0;display:flex;flex-direction:column;';

      detailHtml = `
        <div style="padding:5px 8px 3px;flex-shrink:0;border-bottom:1px solid var(--border);">
          <div style="display:flex;align-items:center;gap:6px;margin-bottom:3px;">
            <span style="font-size:10px;font-weight:700;">${d.active?'🔄 Running':fail>0?'❌ Failed':'✅ Done'}</span>
            <span style="font-size:9px;color:var(--text2);">${done}/${total} · ${pct}%</span>
            <span style="margin-left:auto;font-size:9px;color:var(--text2);">${pass}✓ ${fail}✗ ${skip}⏭</span>
          </div>
          <div style="height:4px;background:var(--border);border-radius:2px;">
            <div style="height:100%;width:${pct}%;background:${barColor};border-radius:2px;transition:width 0.5s;"></div>
          </div>
        </div>
        <div style="${pillsStyle}">
          ${pill('all','All '+(done+(d.active?1:0)))}
          ${d.active?pill('active','▶ Active'):''}
          ${pill('pass','✓ '+pass)}
          ${fail>0?pill('fail','✗ '+fail):''}
          ${skip>0?pill('skip','⏭ '+skip):''}
          ${remaining>0?pill('pending','○ '+remaining):''}
        </div>
        <div style="flex:1;min-height:0;overflow-y:auto;">${rowsHtml}</div>`;
    }
  }

  // Issue #99 — smoke card mobile: narrow pane gets overflow-x:auto
  const _smokeCardW = el.clientWidth || 0;
  const _smokeNarrowOuter = _smokeCardW > 0 && _smokeCardW < 480;
  const _smokePaneStyle = _smokeNarrowOuter
    ? 'flex:1;min-height:0;display:flex;flex-direction:column;overflow-x:auto;-webkit-overflow-scrolling:touch;'
    : 'flex:1;min-height:0;display:flex;flex-direction:column;';
  el.innerHTML = envListHtml + (_dash._smokeExpandedId
    ? `<div style="${_smokePaneStyle}">${detailHtml}</div>`
    : `<div style="padding:10px 8px;color:var(--text2);font-size:10px;">↑ Click a run to expand</div>`);
}

// Node click — session → session-detail, PRD → automata view ————————————————
window._dashNodeClick = function(id) {
  const node = _dash.nodes[id];
  if (!node) return;
  if (node.prd) {
    _automataState.tab = 'automata';  // the Automaton's back control lands on the Automata list
    navigate('autonomous');
    // Give the automata view a moment to render then open the detail
    setTimeout(() => {
      if (typeof window.openAutomataDetail === 'function') window.openAutomataDetail(id);
    }, 80);
  } else {
    navigate('session-detail', id);
  }
};

// Runtime badge for session nodes ————————————————————————
function _runtimeBadge(sess) {
  const cnr = sess.compute_node_ref || '';
  const bf = (sess.backend_family || '').toLowerCase();
  if (cnr) {
    const cn = (_dash._computeNodes || []).find(n => n.id === cnr || n.name === cnr);
    const rt = cn ? (cn.runtime_type || cn.type || '').toLowerCase() : '';
    if (rt.includes('k8s') || rt.includes('kube')) return '☸';
    if (rt.includes('docker')) return '🐳';
    return '🌐';
  }
  if (bf.includes('proxy')) return '⇢';
  if (bf === 'claude-code' || bf === 'opencode-acp' || bf === 'local') return '🖥';
  if (bf) return '🌐';
  return '';
}

// BL317 — shared by renderDashboardView's initial load and _dashLoop's
// periodic re-fetch, so "all servers" mode and the single-server shape
// stay in exactly one place each (the pre-existing duplication between
// those two call sites is exactly how the total_cost_usd/total_usd
// field-name bug fixed in the same pass went unnoticed in one of the
// two copies for as long as it did).
function _dashFetchPRDs() {
  const isAllServers = state.activeServer === 'all';
  // Single server: the summary list narrowed to the three statuses kept below
  // (the all-servers aggregate has no summary or filter form).
  return apiFetch(isAllServers ? '/api/autonomous/prds/aggregated' : '/api/autonomous/prds?status=running,blocked,planning&limit=500').then(d => {
    const list = Array.isArray(d) ? d : ((d && d.prds) || []);
    _dash._prds = list.filter(p => p.status === 'running' || p.status === 'blocked' || p.status === 'planning');
  });
}

function _dashFetchCost() {
  const isAllServers = state.activeServer === 'all';
  return (isAllServers ? apiFetch('/api/cost/aggregated') : apiFetch('/api/cost')).then(d => {
    if (!isAllServers) {
      _dash._costToday = d;
      return;
    }
    // Sum each server's CostSummary into the same shape /api/cost
    // returns for a single server, so _dashUpdateStatBar/
    // _dashRenderBurnRate don't need to know which mode produced it.
    const list = Array.isArray(d) ? d : [];
    _dash._costToday = list.reduce((acc, c) => ({
      sessions: acc.sessions + (c.sessions || 0),
      total_tokens_in: acc.total_tokens_in + (c.total_tokens_in || 0),
      total_tokens_out: acc.total_tokens_out + (c.total_tokens_out || 0),
      total_usd: acc.total_usd + (c.total_usd || 0),
    }), { sessions: 0, total_tokens_in: 0, total_tokens_out: 0, total_usd: 0 });
  });
}

function renderDashboardView() {
  if (state.activeView !== 'dashboard') return;
  const viewEl = document.getElementById('view');
  if (!viewEl) return;
  if (_dash.rafId) { cancelAnimationFrame(_dash.rafId); _dash.rafId = null; }
  _dash._frameCount = 0;

  viewEl.innerHTML = `
    <div class="dboard-cards" id="dashboardWrap">
      <div class="dboard-stat-bar">
        <span style="font-weight:700;letter-spacing:0.7px;color:var(--accent);font-size:11px;">⬡ DASHBOARD</span>
        <span id="dashStatSessions" style="color:var(--text2);">—</span>
        <span id="dashStatTasks" style="color:var(--text2);"></span>
        <span id="dashStatGuardrails" style="color:var(--text2);"></span>
        <span id="dashStatBurnRate" style="display:none;color:var(--text2);font-size:10px;font-family:monospace;border-left:1px solid var(--border);padding-left:8px;margin-left:2px;"></span>
        <span style="flex:1;"></span>
        <span style="color:var(--text2);opacity:0.4;font-size:9px;font-family:monospace;">live · ws</span>
        <a href="/diagrams.html#docs/howto/dashboard.md" target="_blank" rel="noopener" title="${escHtml(t('dashboard_help_tip')||'Open the Dashboard howto — explains cards, editing, and adding new ones')}" aria-label="Help" style="color:var(--text2);text-decoration:none;font-size:11px;border:1px solid var(--border);border-radius:50%;width:16px;height:16px;display:inline-flex;align-items:center;justify-content:center;line-height:1;margin-left:4px;">?</a>
        <button id="dashAddCardBtn" onclick="window._dashShowAddPanel()" style="display:none;background:none;border:1px solid var(--border);border-radius:4px;color:var(--accent);font-size:10px;padding:2px 8px;cursor:pointer;margin-left:6px;">+ Card</button>
        <button id="dashEditBtn" onclick="window._dashStartEdit()" style="background:none;border:1px solid var(--border);border-radius:4px;color:var(--text2);font-size:10px;padding:2px 8px;cursor:pointer;margin-left:4px;">✎ Edit</button>
      </div>
      <div id="dashFedErrorBanner"></div>
      <div class="dboard-card-grid" id="dashCardGrid">
        <div style="grid-column:1/-1;text-align:center;padding:40px 16px;">${loadingEyeBlock(null, 'panel')}</div>
      </div>
      <!-- Expand overlay (sits outside the grid, overlays the whole view) -->
      <div id="dashExpand" class="dboard-expand hidden">
        <div class="dboard-expand-header">
          <button class="dboard-expand-back" onclick="window.closeDashExpand()">&#8592; ${escHtml(t('common_back') || 'Back')}</button>
          <span id="dashExpandTitle" style="font-weight:600;font-size:13px;color:var(--text);flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;"></span>
          <button style="background:none;border:1px solid var(--border);color:var(--accent);font-size:11px;padding:2px 8px;border-radius:3px;cursor:pointer;" onclick="navigate('session-detail',_dash.expandSid);" title="${escHtml(t('dash_open_session') || 'Open session detail')}">&#128172; ${escHtml(t('dash_open_session') || 'Open')}</button>
        </div>
        <div class="dboard-expand-inner">
          <div id="dashExpandTree" class="dboard-expand-sidebar"></div>
          <div id="dashExpandMain" class="dboard-expand-main"></div>
          <div id="dashExpandVerdicts" class="dboard-expand-verdicts"></div>
        </div>
      </div>
    </div>
  `;

  // BL317 — "all servers" mode: the _automataState.allPrds cache is
  // populated from the single-server /api/autonomous/prds fetch
  // elsewhere, so it's bypassed here and _dashFetchPRDs() always hits
  // the aggregated endpoint fresh instead. See _dashFetchPRDs/
  // _dashFetchCost (shared with the periodic re-fetch in _dashLoop).
  const prdData = state.activeServer === 'all' ? null : _automataState.allPrds;
  if (prdData && prdData.length > 0) {
    _dash._prds = prdData.filter(p => p.status === 'running' || p.status === 'blocked' || p.status === 'planning');
  } else {
    // Coordinator-flagged (2026-10-08), extended 2026-10-08: Dashboard's
    // many cards all poll silently and swallow errors by design
    // (reasonable for a stable local daemon's periodic background
    // refresh) -- but that means a federated 401/403 had ZERO visible
    // feedback anywhere. _dashSetFedError/_dashClearFedError (defined
    // near _dashLoop) now cover both this initial load AND every
    // periodic re-fetch below, keyed by source so they don't clobber
    // each other.
    state._dashFedErrors = {};
    _dashRenderFedErrorBanner();
    _dashFetchPRDs().then(() => _dashClearFedError('prds')).catch(e => _dashSetFedError('prds', e));
  }
  if (!_dash._costFetching) {
    _dash._costFetching = true;
    _dashFetchCost().then(() => _dashClearFedError('cost')).catch(e => _dashSetFedError('cost', e)).finally(() => { _dash._costFetching = false; });
  }
  _dashInitNodes();
  // Load layout from server; falls back to default and calls _dashBuildGrid
  _dashLoadLayout();
  _dash.rafId = requestAnimationFrame(_dashLoop);
  _injectServerPickerBar(viewEl, renderDashboardView); // BL312 S6
}

// BL313 — unhide dashboard nav button; only shown when autonomous.enabled.
// Called when dashboard view activates (ensures nav is visible after navigate()).
function _dashCheckEnabled() {
  fetch('/api/autonomous/config', { headers: tokenHeader() })
    .then(r => r.ok ? r.json() : null)
    .then(cfg => {
      const navBtn = document.getElementById('navBtnDashboard');
      if (navBtn && cfg && cfg.enabled === true) navBtn.style.display = '';
    })
    .catch(() => {});
}

function _dashUpdateStatBar() {
  const sessions = state.sessions || [];
  const running = sessions.filter(s => s.state === 'running' || s.state === 'generating' || s.state === 'waiting_input');
  let taskDone = 0, taskTotal = 0, verdictBlock = 0, verdictWarn = 0;
  for (const b of Object.values(_dash._boards)) {
    const tasks = (b.telemetry && b.telemetry.tasks) || [];
    taskTotal += tasks.length;
    taskDone += tasks.filter(t => t.status === 'completed').length;
    const gv = (b.telemetry && b.telemetry.guardrail_verdicts) || [];
    verdictBlock += gv.filter(v => v.outcome === 'block').length;
    verdictWarn += gv.filter(v => v.outcome === 'warn').length;
  }
  let costStr = '';
  if (_dash._costToday) {
    const c = _dash._costToday;
    // BL317 — fixed a pre-existing field-name bug found while adding "all
    // servers" cost aggregation: /api/cost's real field is total_usd, not
    // total_cost_usd, and `sessions` is a count, not an array, so the old
    // fallback branch never actually ran either -- this display has
    // always rendered $0/hidden regardless of server mode.
    const tot = typeof c.total_usd === 'number' ? c.total_usd : 0;
    if (tot > 0) costStr = ` · <span style="color:var(--text2);">$${tot.toFixed(2)}</span>`;
  }
  const elS = document.getElementById('dashStatSessions');
  const elT = document.getElementById('dashStatTasks');
  const elG = document.getElementById('dashStatGuardrails');
  if (elS) elS.innerHTML = `<span style="color:var(--text);">${sessions.length}</span> sess · <span style="color:var(--accent);">${running.length} active</span>${costStr}`;
  if (elT) elT.innerHTML = taskTotal > 0 ? `<span style="color:var(--success,#10b981);">${taskDone}</span>/<span style="color:var(--text);">${taskTotal}</span> tasks` : '';
  if (elG) elG.innerHTML = verdictBlock > 0
    ? `<span style="color:var(--error);font-weight:700;">⚠ ${verdictBlock} blk</span>${verdictWarn > 0 ? ` <span style="color:var(--warning);">${verdictWarn} warn</span>` : ''}`
    : verdictWarn > 0 ? `<span style="color:var(--warning);">${verdictWarn} warn</span>` : '';

  // Issue #100 — burn-rate compact stats in header strip
  const elBR = document.getElementById('dashStatBurnRate');
  if (elBR) {
    let brTot = 0;
    if (_dash._costToday) {
      const c = _dash._costToday;
      brTot = typeof c.total_usd === 'number' ? c.total_usd : 0;
    }
    const runningCount = running.length;
    const automataCount = (_dash._prds || []).length;
    const hasData = brTot > 0 || runningCount > 0 || automataCount > 0;
    if (hasData) {
      let parts = [];
      if (brTot > 0) parts.push(`<span style="color:var(--success,#10b981);font-weight:700;">$${brTot.toFixed(2)} today</span>`);
      parts.push(`<span style="color:var(--accent);">${runningCount} running</span>`);
      if (automataCount > 0) parts.push(`<span style="color:var(--text2);">${automataCount} automata</span>`);
      elBR.innerHTML = parts.join(' · ');
      elBR.style.display = '';
    } else {
      elBR.style.display = 'none';
    }
  }
}

function _dashRenderTree() {
  const el = document.getElementById('dashTree');
  if (!el) return;
  const prds = _dash._prds || [];
  let html = `<div style="padding:5px 10px 3px;font-size:9px;font-weight:700;color:var(--text2);letter-spacing:0.8px;text-transform:uppercase;">Automata</div>`;
  if (prds.length === 0) {
    html += `<div style="color:var(--text2);padding:5px 10px;font-size:10px;opacity:0.7;">no active automata</div>`;
  } else {
    for (const prd of prds) {
      const stories = prd.stories || [];
      const taskTotal = stories.reduce((n, s) => n + (s.tasks || []).length, 0);
      const taskDone = stories.reduce((n, s) => n + (s.tasks || []).filter(t => t.status === 'completed').length, 0);
      const pct = taskTotal > 0 ? Math.round(taskDone / taskTotal * 100) : 0;
      const expanded = _dash._ganttTreeExpand[prd.id] !== false;
      const pc = { running: 'var(--accent)', blocked: 'var(--error)', planning: 'var(--warning)' }[prd.status] || 'var(--text2)';
      html += `<div style="border-left:2px solid ${pc};margin:1px 6px 0;border-radius:0 3px 3px 0;">
        <div style="padding:5px 7px;cursor:pointer;display:flex;align-items:center;gap:3px;" onclick="${escHtml(`window._dashToggleGanttRow(${JSON.stringify(prd.id)})`)}">
          <span style="color:${pc};font-size:9px;flex-shrink:0;">${expanded ? '▼' : '▶'}</span>
          <span style="color:var(--text);font-size:10px;font-weight:600;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escHtml(prd.title || prd.id)}">${escHtml((prd.title || prd.id).slice(0, 20))}</span>
          <span style="color:${pc};font-size:9px;flex-shrink:0;">${pct}%</span>
        </div>
        <div style="margin:0 8px 4px;height:2px;background:var(--border);border-radius:1px;"><div style="height:100%;width:${pct}%;background:${pc};border-radius:1px;transition:width 0.5s;"></div></div>`;
      if (expanded) {
        for (let si = 0; si < stories.length; si++) {
          const st = stories[si];
          const sc = { completed: 'var(--success,#10b981)', running: 'var(--accent)', in_progress: 'var(--accent)', blocked: 'var(--error)', needs_review: 'var(--warning)' }[st.status] || 'var(--text2)';
          const sIcon = { completed: '✓', running: '▶', in_progress: '▶', blocked: '!', needs_review: '?', failed: '✗' }[st.status] || '○';
          const tDone2 = (st.tasks || []).filter(t => t.status === 'completed').length;
          const tTotal2 = (st.tasks || []).length;
          html += `<div style="padding:2px 7px 2px 14px;cursor:pointer;display:flex;align-items:center;gap:3px;" onclick="${escHtml(`window._dashNodeClick(${JSON.stringify(prd.id)})`)}">
            <span style="color:${sc};font-size:9px;flex-shrink:0;">${sIcon}</span>
            <span style="color:var(--text);font-size:9px;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escHtml((st.title || `S${si + 1}`).slice(0, 18))}</span>
            ${tTotal2 > 0 ? `<span style="color:var(--text2);font-size:8px;flex-shrink:0;">${tDone2}/${tTotal2}</span>` : ''}
          </div>`;
        }
      }
      html += `</div>`;
    }
  }
  const activeSessions = (state.sessions || []).filter(s =>
    s.state === 'running' || s.state === 'generating' || s.state === 'waiting_input');
  if (activeSessions.length > 0) {
    html += `<div style="margin-top:10px;padding:5px 10px 3px;font-size:9px;font-weight:700;color:var(--text2);letter-spacing:0.8px;text-transform:uppercase;">Active Sessions</div>`;
    for (const s of activeSessions.slice(0, 8)) {
      const sc2 = { running: 'var(--accent)', generating: 'var(--accent)', waiting_input: 'var(--warning)' }[s.state] || 'var(--text2)';
      const board2 = _dash._boards[s.full_id || s.id];
      const hDot = !board2 ? '○' : board2.hook_health === 'alive' ? '●' : '◐';
      const hColor = !board2 ? 'var(--text2)' : board2.hook_health === 'alive' ? 'var(--success,#10b981)' : 'var(--warning)';
      const focus2 = board2 && board2.current_focus && board2.current_focus.task || '';
      const rtBadge = _runtimeBadge(s);
      html += `<div style="padding:4px 7px;cursor:pointer;border-left:2px solid ${sc2};margin:1px 6px 0;border-radius:0 3px 3px 0;" onclick="${escHtml(`navigate('session-detail',${JSON.stringify(s.full_id || s.id)})`)}">
        <div style="display:flex;align-items:center;gap:3px;">
          <span style="color:${hColor};font-size:8px;">${hDot}</span>
          <span style="color:var(--text);font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;">${escHtml((s.name || s.task || s.id || '').slice(0, 20))}</span>
          ${rtBadge ? `<span style="font-size:10px;flex-shrink:0;" title="${escHtml(s.backend_family||'')}${escHtml(s.compute_node_ref ? ' · '+s.compute_node_ref : '')}">${rtBadge}</span>` : ''}
        </div>
        ${focus2 ? `<div style="color:var(--text2);font-size:8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding-left:10px;">▸ ${escHtml(focus2.slice(0, 24))}</div>` : ''}
      </div>`;
    }
  }
  el.innerHTML = html;
}

function _dashRenderEventFeed() {
  const feedEl = document.getElementById('dashEventFeed');
  if (!feedEl) return;
  const log = _dash._eventLog;
  if (log.length === 0) {
    feedEl.innerHTML = `<div style="color:var(--text2);padding:6px 10px;font-size:10px;opacity:0.6;">Waiting for hook events…</div>`;
    return;
  }
  feedEl.innerHTML = [...log].reverse().map(e => {
    const ts = new Date(e.t).toLocaleTimeString('en-GB', { hour12: false });
    const toolBadge = e.tool ? `<span style="color:var(--accent2,#60a5fa);margin-left:3px;font-size:9px;">${escHtml(e.tool.slice(0, 14))}</span>` : '';
    const taskLine = e.task ? `<div style="color:var(--text2);font-size:9px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding-left:10px;" title="${escHtml(e.task)}">▸ ${escHtml(e.task.slice(0, 32))}</div>` : '';
    const evIcon = { Stop: '◼', PostToolUse: '▶', UserPromptSubmit: '💬', SubagentStop: '◻', update: '·' }[e.event] || '·';
    return `<div style="padding:2px 6px;border-bottom:1px solid rgba(255,255,255,0.03);">
      <div style="display:flex;align-items:center;gap:2px;flex-wrap:nowrap;overflow:hidden;">
        <span style="color:var(--text2);font-size:8px;flex-shrink:0;">${ts}</span>
        <span style="color:${e.color};font-size:8px;flex-shrink:0;">${evIcon}</span>
        <span style="color:var(--text);font-size:9px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:72px;" title="${escHtml(e.name)}">${escHtml(e.name)}</span>
        ${toolBadge}
      </div>
      ${taskLine}
    </div>`;
  }).join('');
}

function _drawGantt() {
  const svgEl = document.getElementById('dashGanttSvg');
  if (!svgEl) return;
  const container = svgEl.parentElement;
  if (!container) return;
  const W = container.clientWidth || 600;
  const LABEL_W = 164;
  const BAR_X = LABEL_W;
  const BAR_W = W - LABEL_W - 24;
  const now = Date.now();
  const WIN_MS = 6 * 3600000;
  const winStart = now - WIN_MS;
  const HEADER_H = 24, AUTO_H = 28, STORY_H = 22, GAP = 8;
  const prds = _dash._prds || [];
  const css = getComputedStyle(document.documentElement);
  const bg = css.getPropertyValue('--bg').trim() || '#0f1117';
  const bg2 = css.getPropertyValue('--bg2').trim() || '#161b2e';
  const bdr = css.getPropertyValue('--border').trim() || '#2d3148';
  const txt = css.getPropertyValue('--text').trim() || '#e2e8f0';
  const txt2 = css.getPropertyValue('--text2').trim() || '#64748b';
  const acc = css.getPropertyValue('--accent').trim() || '#7c3aed';
  const stC = s => ({ completed: '#10b981', running: acc, in_progress: acc, blocked: '#ef4444', needs_review: '#f59e0b', planning: '#8b5cf6', failed: '#ef4444' }[s] || txt2);
  const tsX = ts => BAR_X + Math.max(0, Math.min(1, (ts - winStart) / WIN_MS)) * BAR_W;
  let totalH = HEADER_H + GAP;
  for (const p of prds) {
    totalH += AUTO_H;
    if (_dash._ganttTreeExpand[p.id] !== false) totalH += (p.stories || []).length * STORY_H;
    totalH += GAP;
  }
  totalH = Math.max(totalH, 80);
  let html = '';
  html += `<rect x="0" y="0" width="${W}" height="${HEADER_H}" fill="${bg2}"/>`;
  const startH = Math.ceil(winStart / 3600000), endH = Math.floor(now / 3600000);
  for (let h = startH; h <= endH; h++) {
    const ts = h * 3600000;
    const x = tsX(ts);
    if (x < BAR_X - 2 || x > W - 10) continue;
    const d = new Date(ts);
    const lbl = d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    html += `<line x1="${x.toFixed(1)}" y1="0" x2="${x.toFixed(1)}" y2="${totalH}" stroke="${bdr}" stroke-width="0.5" stroke-dasharray="2,6"/>`;
    html += `<text x="${x.toFixed(1)}" y="14" text-anchor="middle" font-size="9" fill="${txt2}">${escHtml(lbl)}</text>`;
  }
  const nowX = tsX(now);
  html += `<line x1="${nowX.toFixed(1)}" y1="0" x2="${nowX.toFixed(1)}" y2="${totalH}" stroke="${acc}" stroke-width="1.5" stroke-dasharray="4,3" opacity="0.6"/>`;
  html += `<text x="${nowX.toFixed(1)}" y="10" text-anchor="middle" font-size="8" fill="${acc}" font-weight="bold">NOW</text>`;
  let y = HEADER_H + GAP;
  if (prds.length === 0) {
    html += `<text x="${W / 2}" y="${HEADER_H + 50}" text-anchor="middle" font-size="13" fill="${txt2}" opacity="0.6">No active automata — start an Automaton to see its timeline</text>`;
    html += `<text x="${W / 2}" y="${HEADER_H + 68}" text-anchor="middle" font-size="10" fill="${txt2}" opacity="0.4">Live story bars appear here as hooks fire</text>`;
  }
  for (const prd of prds) {
    const stories = prd.stories || [];
    const tTotal = stories.reduce((n, s) => n + (s.tasks || []).length, 0);
    const tDone = stories.reduce((n, s) => n + (s.tasks || []).filter(t => t.status === 'completed').length, 0);
    const pct = tTotal > 0 ? Math.round(tDone / tTotal * 100) : 0;
    const prdColor = stC(prd.status);
    const expanded = _dash._ganttTreeExpand[prd.id] !== false;
    html += `<rect x="0" y="${y}" width="${W}" height="${AUTO_H}" fill="${bg2}" style="cursor:pointer;" onclick="${escHtml(`window._dashToggleGanttRow(${JSON.stringify(prd.id)})`)}"/>`;
    html += `<text x="8" y="${y + AUTO_H / 2 + 4}" font-size="11" fill="${prdColor}" style="cursor:pointer;">${expanded ? '▼' : '▶'}</text>`;
    html += `<text x="22" y="${y + AUTO_H / 2 + 4}" font-size="11" fill="${txt}" font-weight="600" style="cursor:pointer;" onclick="${escHtml(`window._dashNodeClick(${JSON.stringify(prd.id)})`)}">${escHtml((prd.title || prd.id).slice(0, 26))}</text>`;
    const pbX = W - 96, pbY = y + AUTO_H / 2 - 5, pbW = 72, pbH = 7;
    html += `<rect x="${pbX}" y="${pbY}" width="${pbW}" height="${pbH}" rx="3" fill="${bdr}"/>`;
    html += `<rect x="${pbX}" y="${pbY}" width="${(pbW * pct / 100).toFixed(1)}" height="${pbH}" rx="3" fill="${prdColor}" opacity="0.8"/>`;
    html += `<text x="${pbX + pbW + 4}" y="${pbY + pbH - 1}" font-size="9" fill="${txt2}">${pct}%</text>`;
    y += AUTO_H;
    if (!expanded) { y += GAP; continue; }
    const completedCount = stories.filter(s => s.status === 'completed').length;
    for (let si = 0; si < stories.length; si++) {
      const st = stories[si];
      const key = prd.id + ':' + si;
      const timing = _dash._ganttTimings[key];
      let barStart, barEnd;
      if (timing && timing.start) {
        barStart = timing.start;
        barEnd = st.status === 'completed' ? (timing.end || timing.lastSeen || now) : now;
      } else {
        const slotMs = WIN_MS / Math.max(stories.length, 1);
        if (st.status === 'completed') {
          barStart = winStart + si * slotMs;
          barEnd = winStart + (si + 1) * slotMs;
        } else if (st.status === 'running' || st.status === 'in_progress') {
          barStart = winStart + completedCount * slotMs;
          barEnd = now;
        } else {
          barStart = now + (si - completedCount) * (WIN_MS / 12);
          barEnd = barStart + WIN_MS / 12;
        }
      }
      const bx = tsX(barStart);
      const bx2 = Math.min(W - 16, tsX(barEnd));
      const bw = Math.max(3, bx2 - bx);
      const color = stC(st.status);
      const isPending = !st.status || st.status === 'draft' || st.status === 'not_started';
      const rowY = y + 2, rowH = STORY_H - 4;
      html += `<rect x="0" y="${y}" width="${W}" height="${STORY_H}" fill="transparent" onclick="${escHtml(`window._dashNodeClick(${JSON.stringify(prd.id)})`)}" style="cursor:pointer;"/>`;
      const sIcon = { completed: '✓', running: '▶', in_progress: '▶', blocked: '!', needs_review: '?', failed: '✗' }[st.status] || '○';
      html += `<text x="${LABEL_W - 8}" y="${y + STORY_H / 2 + 4}" text-anchor="end" font-size="10" fill="${color}">${sIcon}</text>`;
      html += `<text x="8" y="${y + STORY_H / 2 - 1}" font-size="9" fill="${txt}" opacity="0.8">${escHtml((st.title || `Story ${si + 1}`).slice(0, 24))}</text>`;
      const tD2 = (st.tasks || []).filter(t => t.status === 'completed').length;
      const tT2 = (st.tasks || []).length;
      if (tT2 > 0) html += `<text x="8" y="${y + STORY_H / 2 + 9}" font-size="8" fill="${txt2}">${tD2}/${tT2}</text>`;
      if (isPending) {
        html += `<rect x="${bx.toFixed(1)}" y="${rowY}" width="${bw.toFixed(1)}" height="${rowH}" rx="2" fill="none" stroke="${color}" stroke-width="0.8" stroke-dasharray="3,3" opacity="0.35"/>`;
      } else {
        const op = st.status === 'completed' ? '0.55' : '0.82';
        html += `<rect x="${bx.toFixed(1)}" y="${rowY}" width="${bw.toFixed(1)}" height="${rowH}" rx="2" fill="${color}" opacity="${op}"/>`;
        if (bw > 44) {
          const bl = (st.status === 'running' || st.status === 'in_progress')
            ? `▶ ${(st.title || `S${si + 1}`).slice(0, 14)}`
            : (st.title || `S${si + 1}`).slice(0, 16);
          html += `<text x="${(bx + Math.min(bw, 120) / 2).toFixed(1)}" y="${rowY + rowH / 2 + 4}" text-anchor="middle" font-size="9" fill="white" opacity="0.92" style="pointer-events:none;">${escHtml(bl)}</text>`;
        }
        if ((st.verdicts || []).some(v => v.outcome === 'block')) {
          html += `<text x="${(bx + bw + 4).toFixed(1)}" y="${rowY + rowH - 1}" font-size="10" fill="#ef4444">⛔</text>`;
        }
      }
      y += STORY_H;
    }
    y += GAP;
  }
  svgEl.setAttribute('height', totalH);
  svgEl.setAttribute('width', W);
  svgEl.setAttribute('viewBox', `0 0 ${W} ${totalH}`);
  svgEl.innerHTML = html;
}

function _drawSparklines() {
  const canvas = document.getElementById('dashSparkCanvas');
  if (!canvas) return;
  const W = canvas.clientWidth || 240;
  const H = canvas.clientHeight || 130;
  if (canvas.width !== W) canvas.width = W;
  if (canvas.height !== H) canvas.height = H;
  const ctx = canvas.getContext('2d');
  const css = getComputedStyle(document.documentElement);
  const bg2 = css.getPropertyValue('--bg2').trim() || '#161b2e';
  const bdr = css.getPropertyValue('--border').trim() || '#2d3148';
  const txt2 = css.getPropertyValue('--text2').trim() || '#64748b';
  ctx.fillStyle = bg2;
  ctx.fillRect(0, 0, W, H);
  const allSessions = (state.sessions || []).filter(s =>
    s.state === 'running' || s.state === 'generating' || s.state === 'waiting_input' || s.state === 'idle'
  ).slice(0, 5);
  if (allSessions.length === 0) {
    ctx.fillStyle = txt2; ctx.font = '9px monospace';
    ctx.fillText('no sessions', 8, 18); return;
  }
  const rowH = Math.floor(H / allSessions.length);
  const LABEL_W = 76;
  const SPARK_W = W - LABEL_W - 4;
  const now2 = Date.now();
  const BUCKETS = 60, BUCKET_MS = 2000;
  const sparkStart = now2 - BUCKETS * BUCKET_MS;
  for (let ci = 0; ci < allSessions.length; ci++) {
    const sess = allSessions[ci];
    const sid = sess.full_id || sess.id;
    const color = _dashNodeColor(sess.state);
    const rowY = ci * rowH;
    if (ci > 0) {
      ctx.strokeStyle = bdr; ctx.lineWidth = 0.5;
      ctx.beginPath(); ctx.moveTo(0, rowY); ctx.lineTo(W, rowY); ctx.stroke();
    }
    ctx.fillStyle = color; ctx.font = 'bold 9px monospace';
    ctx.fillText((sess.name || sess.id || '?').slice(0, 9), 4, rowY + rowH * 0.45);
    ctx.fillStyle = txt2; ctx.font = '8px monospace';
    ctx.fillText(sess.state || '', 4, rowY + rowH * 0.78);
    const buckets = new Array(BUCKETS).fill(0);
    for (const e of _dash.ekg) {
      if (e.t >= sparkStart) {
        const bi = Math.min(BUCKETS - 1, Math.floor((e.t - sparkStart) / BUCKET_MS));
        buckets[bi]++;
      }
    }
    const maxB = Math.max(1, ...buckets);
    const barW = SPARK_W / BUCKETS;
    for (let bi = 0; bi < BUCKETS; bi++) {
      const bh = Math.max(0, (buckets[bi] / maxB) * (rowH - 5));
      if (bh < 0.5) continue;
      ctx.fillStyle = color; ctx.globalAlpha = 0.65;
      ctx.fillRect(LABEL_W + bi * barW, rowY + rowH - 3 - bh, Math.max(1, barW - 0.5), bh);
    }
    ctx.globalAlpha = 1;
  }
}

function _dashRenderBurnRate() {
  const el = document.getElementById('dashBurnRate');
  if (!el) return;
  const sessions = (state.sessions || []).filter(s => s.state === 'running' || s.state === 'generating');
  let html = '';
  if (_dash._costToday) {
    const c = _dash._costToday;
    const tot = typeof c.total_usd === 'number' ? c.total_usd : 0;
    if (tot > 0) {
      html += `<div style="color:var(--success,#10b981);font-weight:700;">$${tot.toFixed(2)}</div><div style="font-size:8px;opacity:0.6;">today</div>`;
    }
  }
  html += `<div style="margin-top:3px;color:var(--accent);font-size:9px;">${sessions.length} running</div>`;
  const prds = _dash._prds || [];
  if (prds.length > 0) html += `<div style="font-size:8px;color:var(--text2);">${prds.length} automata</div>`;
  el.innerHTML = html;
}

window._dashToggleGanttRow = function(prdId) {
  _dash._ganttTreeExpand[prdId] = (_dash._ganttTreeExpand[prdId] === false) ? true : false;
  _dashRenderTree();
};

